    ('8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Quiz — Deux manières d’expliquer : par les questions ou librement', 'Philosophie', 'Tle', 'Méthode : l’explication de texte au bac techno', '1d02bf33-56e6-5591-8cd5-7cccd576a242'::uuid)
