-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('6a19acf8-8e7d-53b7-adf8-ca57767c4ca6'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Que proclament les députés du tiers état le 17 juin 1789 ?', 'mcq', '["Ils se déclarent Assemblée nationale","Ils proclament la République","Ils rédigent le Code civil","Ils déclarent la guerre à l’Autriche"]'::jsonb, 0, 'Se dire « Assemblée nationale », c’est affirmer que la souveraineté appartient à la nation et non plus au roi.', 1),
    ('8750fcae-132c-532d-8573-1a471c8fbc09'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Quel texte proclame l’égalité des citoyens devant la loi en août 1789 ?', 'mcq', '["Le Code civil","La Constitution de 1791","La Déclaration des droits de l’homme et du citoyen","Le Concordat"]'::jsonb, 2, 'La Déclaration du 26 août 1789 pose les principes d’égalité en droits et de souveraineté nationale.', 2),
    ('7cb9624e-f974-5023-aabd-d80203deff23'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Que supprime la nuit du 4 août 1789 ?', 'mcq', '["La monarchie","Les privilèges","Le suffrage censitaire","L’esclavage dans les colonies"]'::jsonb, 1, 'L’abolition des privilèges met fin à la société d’ordres (clergé, noblesse, tiers état).', 3),
    ('97a0125b-f754-5904-a68b-98886de7c94a'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Quel régime la Constitution de 1791 met-elle en place ?', 'mcq', '["Une république","Un empire","Une monarchie absolue","Une monarchie constitutionnelle"]'::jsonb, 3, 'Le roi reste chef de l’exécutif, mais il doit respecter une constitution et la loi votée par l’Assemblée.', 4),
    ('7e0f6f1d-102a-5a6f-b49f-ddd307ef1298'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'La République est proclamée en France le 22 septembre 1792.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle est proclamée par la Convention, quelques semaines après la chute de la monarchie le 10 août 1792.', 5),
    ('945ec955-0c85-57c3-a386-a27f33ab53c6'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Pourquoi parle-t-on de la « Terreur » en 1793-1794 ?', 'mcq', '["Pour désigner l’occupation étrangère de Paris","Pour désigner un gouvernement d’exception qui suspend les libertés face aux guerres","Pour désigner la famine de 1789","Pour désigner le règne de Napoléon"]'::jsonb, 1, 'Menacée de l’extérieur et de l’intérieur, la République confie le pouvoir au Comité de salut public, qui fait arrêter et exécuter les « suspects ».', 6),
    ('873f1d20-983a-5d03-afbe-550c05e7858a'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Comment Napoléon Bonaparte arrive-t-il au pouvoir en 1799 ?', 'mcq', '["Par une élection au suffrage universel","Par un héritage dynastique","Par le coup d’État du 18 brumaire","Par une victoire à Waterloo"]'::jsonb, 2, 'Le 18 brumaire an VIII (9 novembre 1799), il renverse le Directoire et fonde le Consulat.', 7),
    ('16b90520-9e00-5577-bf90-8402e47bc23e'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Quel acquis de la Révolution Napoléon conserve-t-il dans le Code civil de 1804 ?', 'mcq', '["La liberté de la presse","Le suffrage universel","Le droit de grève","L’égalité devant la loi"]'::jsonb, 3, 'Le Code civil garantit l’égalité civile et la propriété, mais Napoléon supprime les libertés politiques.', 8),
    ('5b831b50-8e56-5804-a819-6d2516193092'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Les conquêtes napoléoniennes ont diffusé en Europe certains principes révolutionnaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le Code civil et la fin des privilèges sont exportés dans des territoires conquis, tout en imposant la domination française.', 9),
    ('f98217ff-b3d8-5318-b482-a2dd49ab1558'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Quelle est la date de la bataille de Waterloo ?', 'mcq', '["18 juin 1815","14 juillet 1789","2 décembre 1804","10 août 1792"]'::jsonb, 0, 'La défaite de Waterloo met fin aux Cent-Jours et au règne de Napoléon.', 10),
    ('29fb0fd4-eb01-5eff-b43d-95014b801a27'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Quel est le but principal du congrès de Vienne (1814-1815) ?', 'mcq', '["Diffuser les idées révolutionnaires","Restaurer l’ordre monarchique et assurer la paix en Europe","Créer une Europe unie","Libérer les colonies"]'::jsonb, 1, 'Les vainqueurs de Napoléon redessinent l’Europe pour y rétablir les monarchies et un équilibre entre puissances.', 11),
    ('e4b3c971-0796-5d13-b09e-2204db71c451'::uuid, '65b78b86-1451-567a-bd34-fb13c7aa1374'::uuid, 'Quelle notion désigne l’idée que le pouvoir appartient à l’ensemble des citoyens ?', 'mcq', '["Le droit divin","L’absolutisme","La souveraineté nationale","Le suffrage censitaire"]'::jsonb, 2, 'La souveraineté nationale, proclamée en 1789, remplace le pouvoir de droit divin du roi.', 12),
    ('d30311f2-cf79-5bf3-9d5b-7c71cb42b321'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Quel palais est pris d’assaut le 10 août 1792 ?', 'mcq', '["Versailles","Le Louvre","Les Tuileries","La Bastille"]'::jsonb, 2, 'Depuis octobre 1789, la famille royale vit aux Tuileries, à Paris.', 1),
    ('57fa5a9c-63d0-597e-b5e8-bed8b02f66d7'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Quel événement de juin 1791 ruine la confiance envers le roi ?', 'mcq', '["La fuite à Varennes","La bataille de Valmy","Le serment du Jeu de paume","La prise de la Bastille"]'::jsonb, 0, 'Arrêté à Varennes alors qu’il fuyait vers la frontière, le roi apparaît comme un traître.', 2),
    ('06095b3e-df04-5dca-8e46-8801acf6bb98'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Contre quel pays la France déclare-t-elle la guerre en avril 1792 ?', 'mcq', '["Le Royaume-Uni","L’Espagne","La Russie","L’Autriche"]'::jsonb, 3, 'La guerre est déclarée au « roi de Bohême et de Hongrie », c’est-à-dire à l’Autriche, rejointe par la Prusse.', 3),
    ('d854bdf1-277a-5b62-b5f5-c33e8496863b'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Quel texte menace Paris d’une « exécution militaire » à l’été 1792 ?', 'mcq', '["La Déclaration de Pillnitz","Le manifeste de Brunswick","Le Code civil","La loi des suspects"]'::jsonb, 1, 'Ce manifeste du chef des armées prussiennes provoque l’effet inverse de celui voulu : il pousse Paris à l’insurrection.', 4),
    ('3ce2283b-cc3d-52ee-ab8b-262730dad60a'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Qui sont les sans-culottes ?', 'mcq', '["Des nobles émigrés","Des soldats prussiens","Des révolutionnaires du peuple parisien","Des prêtres réfractaires"]'::jsonb, 2, 'Artisans et boutiquiers, ils portent le pantalon et non la culotte des aristocrates, et réclament une démocratie directe.', 5),
    ('04efcb83-41f1-5a0a-a857-989265cf41b6'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Les fédérés marseillais ont popularisé le chant qui deviendra La Marseillaise.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Composé à Strasbourg par Rouget de Lisle, le chant est popularisé par les fédérés marseillais arrivés à Paris en 1792.', 6),
    ('96257d6d-5d4c-5808-abcb-889a99c45776'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Que décide l’Assemblée législative le soir du 10 août 1792 ?', 'mcq', '["Elle rétablit le roi","Elle déclare la guerre à la Prusse","Elle proclame l’Empire","Elle suspend le roi et convoque une Convention"]'::jsonb, 3, 'La Convention sera élue au suffrage universel masculin : c’est un basculement démocratique.', 7),
    ('08184f3b-2358-557d-a80a-518a2a962e4c'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Quelle victoire de septembre 1792 arrête l’avancée prussienne ?', 'mcq', '["Valmy","Austerlitz","Waterloo","Iéna"]'::jsonb, 0, 'La canonnade de Valmy, le 20 septembre 1792, précède d’un jour l’abolition de la royauté.', 8),
    ('516298a0-99f3-5202-8238-445362e2a8a0'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Quand Louis XVI est-il exécuté ?', 'mcq', '["Le 10 août 1792","Le 21 janvier 1793","Le 14 juillet 1790","Le 9 thermidor an II"]'::jsonb, 1, 'Jugé par la Convention, le roi est guillotiné le 21 janvier 1793, ce qui élargit la coalition européenne contre la France.', 9),
    ('9451bc97-49a4-517b-a1df-cf3b756cddf5'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Qui défend les Tuileries le 10 août 1792 ?', 'mcq', '["Les fédérés marseillais","Les sans-culottes","Les gardes suisses","L’armée prussienne"]'::jsonb, 2, 'Les gardes suisses de la garde du roi combattent les insurgés ; beaucoup sont tués.', 10),
    ('5b35656c-9b08-53ef-87ec-f670f4f1a0a5'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'La chute de la monarchie rapproche la France des autres monarchies européennes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : la rupture avec la royauté isole la France et élargit la guerre contre les monarchies européennes.', 11),
    ('e3327c65-bf00-506a-8e92-ccfec30aef4f'::uuid, '03541fdc-4250-598e-9efc-a5f1bb23099e'::uuid, 'Dans quel contexte la République met-elle en place la Terreur ?', 'mcq', '["Une paix durable","Une guerre extérieure et une guerre intérieure","Une crise économique sans conflit","Le retour de Napoléon"]'::jsonb, 1, 'La guerre contre la coalition européenne et le soulèvement de la Vendée expliquent le gouvernement d’exception de 1793-1794.', 12),
    ('6777b1e8-8f90-5820-89c0-c99e4beba1e4'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Où se situe Waterloo ?', 'mcq', '["En Prusse","Près de Bruxelles, dans l’actuelle Belgique","Dans le nord de la France","En Autriche"]'::jsonb, 1, 'Waterloo est au sud de Bruxelles ; en 1815, le territoire appartient au royaume uni des Pays-Bas.', 1),
    ('a7181cda-48ec-5b9f-9c0a-e625997d7084'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Comment appelle-t-on la période du retour de Napoléon en 1815 ?', 'mcq', '["La Restauration","Le Consulat","Les Cent-Jours","La Terreur"]'::jsonb, 2, 'De son débarquement le 1er mars à sa seconde abdication le 22 juin 1815 s’écoulent environ cent jours.', 2),
    ('20dbc284-9b24-569a-9d1e-4fc855b4b74b'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Où Napoléon était-il exilé avant les Cent-Jours ?', 'mcq', '["À Sainte-Hélène","En Corse","À Malte","À l’île d’Elbe"]'::jsonb, 3, 'Après son abdication d’avril 1814, il reçoit la souveraineté de la petite île d’Elbe, en Méditerranée.', 3),
    ('970fbc71-616b-5f6c-8890-8b4af71292bc'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Qui commande l’armée anglo-alliée à Waterloo ?', 'mcq', '["Le duc de Wellington","Le maréchal Blücher","Le maréchal Ney","Le tsar Alexandre Ier"]'::jsonb, 0, 'Wellington tient le plateau de Mont-Saint-Jean en attendant les Prussiens.', 4),
    ('5489653e-1ebe-5eee-b25c-34abf1248f4c'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Quelle armée arrive sur le flanc français l’après-midi du 18 juin ?', 'mcq', '["L’armée autrichienne","L’armée russe","L’armée prussienne de Blücher","L’armée espagnole"]'::jsonb, 2, 'L’arrivée des Prussiens de Blücher décide de la bataille.', 5),
    ('76526831-e7cb-5cd9-828b-fbca814fb34a'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'L’armée anglo-alliée de Wellington ne comptait que des soldats britanniques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle mêlait Britanniques, Néerlandais, Belges et contingents allemands : c’est une armée de coalition.', 6),
    ('bad26b8e-e652-5b4d-84e5-8764c4a1ed38'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Pourquoi les monarchies européennes s’unissent-elles contre Napoléon en 1815 ?', 'mcq', '["Pour lui confier la France","Parce qu’il incarne la Révolution et la guerre permanente","Pour partager l’Amérique","Pour protéger la République française"]'::jsonb, 1, 'Les rois voient en lui l’héritier armé de la Révolution qui menace l’ordre monarchique.', 7),
    ('b78a6560-b487-5695-b367-07fd88b275cd'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Où Napoléon est-il exilé après Waterloo ?', 'mcq', '["À l’île d’Elbe","En Russie","À Sainte-Hélène","En Amérique"]'::jsonb, 2, 'Les Britanniques l’envoient sur cette île isolée de l’Atlantique Sud, où il meurt en 1821.', 8),
    ('54dc168a-1eaf-5517-9c92-0da30244976a'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Quelle bataille Napoléon gagne-t-il contre les Prussiens le 16 juin 1815 ?', 'mcq', '["Ligny","Austerlitz","Iéna","Valmy"]'::jsonb, 0, 'Il bat Blücher à Ligny, mais sans détruire son armée, qui rejoindra Waterloo deux jours plus tard.', 9),
    ('23ae1f56-4e3b-58a1-8a23-9347b4dbf2b1'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Quelle alliance de 1815 réunit la Russie, l’Autriche et la Prusse pour défendre l’ordre monarchique ?', 'mcq', '["La Triple-Entente","La Sainte-Alliance","La Triple-Alliance","La Ligue des nations"]'::jsonb, 1, 'Proposée par le tsar, la Sainte-Alliance veut empêcher le retour des idées révolutionnaires.', 10),
    ('bfadcc52-b4f1-5fcb-aef1-91909eab0751'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Quel roi revient au pouvoir en France après la défaite de Napoléon ?', 'mcq', '["Louis XVI","Charles X","Louis-Philippe","Louis XVIII"]'::jsonb, 3, 'Frère de Louis XVI, Louis XVIII règne de 1814 à 1824, avec l’interruption des Cent-Jours.', 11),
    ('12d87cdb-d066-5cf2-b6ee-9db79f392234'::uuid, '2bbc3821-7c97-5d38-b20d-4201fcc86fd6'::uuid, 'Waterloo a fait environ 50 000 tués et blessés en une journée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’ordre de grandeur, tous camps confondus, montre la violence des batailles napoléoniennes.', 12),
    ('2f6de5d9-0792-52f9-86b4-02adfd900cbe'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Quel roi est renversé par la révolution de février 1848 ?', 'mcq', '["Charles X","Louis-Philippe","Louis XVIII","Napoléon III"]'::jsonb, 1, 'Louis-Philippe, roi de la monarchie de Juillet depuis 1830, abdique face à l’insurrection parisienne.', 1),
    ('dbacf82e-3efa-540f-bfb6-94f291ee60dc'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Que change le suffrage universel masculin instauré en 1848 ?', 'mcq', '["Les femmes obtiennent le droit de vote","Seuls les riches votent","Tous les hommes de 21 ans et plus peuvent voter","Le roi choisit les députés"]'::jsonb, 2, 'Le corps électoral passe d’environ 250 000 à 9 millions d’électeurs.', 2),
    ('e45f39ec-f2cd-5b9a-b5b6-69b4f2b08bdd'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Qui porte le décret d’abolition de l’esclavage d’avril 1848 ?', 'mcq', '["Victor Schœlcher","Victor Hugo","Lamartine","Haussmann"]'::jsonb, 0, 'Le décret du 27 avril 1848 abolit l’esclavage dans les colonies françaises.', 3),
    ('c2904b26-c625-5359-9147-36a090cdf8c4'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Pourquoi les ouvriers parisiens se soulèvent-ils en juin 1848 ?', 'mcq', '["Pour rétablir le roi","Contre la guerre avec la Prusse","Contre le suffrage universel","Contre la fermeture des ateliers nationaux"]'::jsonb, 3, 'La fermeture de ces ateliers qui employaient les chômeurs déclenche l’insurrection, durement réprimée.', 4),
    ('556b3c9c-6687-57f3-a6ea-a08aed941784'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Louis-Napoléon Bonaparte est élu président de la République en décembre 1848.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il l’emporte largement au suffrage universel masculin, grâce au prestige de son nom.', 5),
    ('5ed25da6-0e9a-5e9b-841a-4417ac369e95'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Comment Louis-Napoléon Bonaparte met-il fin à la Deuxième République ?', 'mcq', '["Par une défaite militaire","Par un coup d’État le 2 décembre 1851","Par une élection perdue","Par une révolution ouvrière"]'::jsonb, 1, 'Ne pouvant être réélu, il s’empare du pouvoir par la force ; l’Empire est rétabli un an plus tard.', 6),
    ('1260014e-e041-55b6-9913-eca6e1367e1b'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Pourquoi dit-on que le Second Empire est un régime autoritaire ?', 'mcq', '["Parce qu’il supprime le suffrage universel","Parce que le pouvoir est concentré et les libertés surveillées","Parce qu’il n’a pas de chef","Parce qu’il est dirigé par l’Assemblée"]'::jsonb, 1, 'Le suffrage universel masculin est conservé, mais la presse est surveillée, les opposants exilés et les candidats officiels favorisés.', 7),
    ('66dbe820-8675-5f73-aa15-3ffe3da59a7c'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Quelle loi de 1864 reconnaît le droit de grève ?', 'mcq', '["La loi Le Chapelier","La loi Falloux","La loi Ollivier","La loi Guizot"]'::jsonb, 2, 'La loi Ollivier supprime le délit de coalition : faire grève n’est plus un crime.', 8),
    ('a83b8d8d-7131-593b-9d72-313cd8029367'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Quel préfet transforme Paris sous le Second Empire ?', 'mcq', '["Haussmann","Schneider","Cavaignac","Thiers"]'::jsonb, 0, 'Le baron Haussmann perce de grands boulevards, construit égouts, parcs et immeubles à façade uniforme.', 9),
    ('2babfddc-7419-54f1-ad55-f6044e8fa652'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Quelle défaite entraîne la chute du Second Empire ?', 'mcq', '["Waterloo","Verdun","Solferino","Sedan"]'::jsonb, 3, 'Napoléon III est fait prisonnier à Sedan le 2 septembre 1870 ; la République est proclamée le 4 septembre.', 10),
    ('d250e991-0d82-5ec2-aecc-01d7ce23c0c0'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Sous le Second Empire, la France devient majoritairement urbaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Malgré l’industrialisation et l’urbanisation, la population reste majoritairement rurale jusqu’en 1931.', 11),
    ('f3d91448-4e42-5725-9d37-fee19359b513'::uuid, '4a68153b-0ded-57df-b03d-5c2aa36e0594'::uuid, 'Quelle conséquence la guerre de 1870-1871 a-t-elle pour l’Allemagne ?', 'mcq', '["Elle perd l’Alsace","Elle réalise son unité autour de la Prusse","Elle devient une république","Elle s’allie à la France"]'::jsonb, 1, 'L’Empire allemand est proclamé dans la galerie des Glaces de Versailles le 18 janvier 1871.', 12),
    ('b82e9042-8742-59cf-99e8-808a688f9800'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Quelle est la position politique de Victor Hugo lorsqu’il est élu en juin 1848 ?', 'mcq', '["Socialiste révolutionnaire","Conservateur, élu avec le parti de l’Ordre","Bonapartiste convaincu depuis toujours","Monarchiste légitimiste radical"]'::jsonb, 1, 'Il est d’abord un notable conservateur ; son évolution vers la République démocratique vient ensuite.', 1),
    ('393cfe16-7f28-52c5-afad-0a037d783518'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Quel combat Hugo mène-t-il dans son discours de juillet 1849 ?', 'mcq', '["La guerre contre la Prusse","Le rétablissement de la monarchie","La lutte contre la misère","La colonisation de l’Algérie"]'::jsonb, 2, 'Il affirme que le législateur doit « détruire la misère », un thème qu’on retrouve dans Les Misérables.', 2),
    ('3ddfc3a6-5661-511f-badb-2d47c64b997a'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Contre quelle loi de 1850 Hugo défend-il l’école laïque ?', 'mcq', '["La loi Ferry","La loi Falloux","La loi Ollivier","La loi Guizot"]'::jsonb, 1, 'La loi Falloux renforce la place de l’Église dans l’enseignement ; Hugo la combat au nom de la liberté de pensée.', 3),
    ('bbbd69f7-022f-5415-b2e4-6bc157bac3f0'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Pourquoi Hugo s’exile-t-il en décembre 1851 ?', 'mcq', '["Parce qu’il a perdu une élection","Pour écrire au calme","Parce qu’il est nommé ambassadeur","Parce qu’il s’est opposé au coup d’État de Louis-Napoléon"]'::jsonb, 3, 'Il tente d’organiser la résistance au coup d’État, puis fuit pour échapper à l’arrestation.', 4),
    ('ef4080aa-f860-5d4b-a03a-4f17e63b8006'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Sur quelle île Hugo vit-il la plus grande partie de son exil ?', 'mcq', '["Guernesey","Sainte-Hélène","La Corse","Elbe"]'::jsonb, 0, 'Il s’installe à Guernesey en 1855, dans sa maison de Hauteville House.', 5),
    ('618fa413-2a8a-529c-8515-39b72ef1cf30'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Quel recueil de poèmes de 1853 attaque Napoléon III ?', 'mcq', '["Les Contemplations","Les Misérables","Les Châtiments","Notre-Dame de Paris"]'::jsonb, 2, 'Les Châtiments dénoncent le coup d’État ; le recueil circule clandestinement en France.', 6),
    ('f794a5e4-33af-53f8-bc39-39d2a3db1397'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Comment Hugo surnomme-t-il Louis-Napoléon Bonaparte ?', 'mcq', '["Napoléon le Grand","Napoléon le Petit","Le roi bourgeois","L’Aigle"]'::jsonb, 1, 'Le pamphlet Napoléon le Petit (1852) oppose le neveu au grand oncle.', 7),
    ('b9846452-53fa-567b-a3d6-b115ade392c0'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'En 1859, Hugo accepte l’amnistie et rentre en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la refuse : « Quand la liberté rentrera, je rentrerai. » Il devient alors un exilé volontaire.', 8),
    ('5437e859-d981-586a-bb84-1dbf101a03a6'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Quand Hugo rentre-t-il à Paris ?', 'mcq', '["En 1852","En 1885","En 1859","Au lendemain de la proclamation de la République, en septembre 1870"]'::jsonb, 3, 'Il arrive le 5 septembre 1870, acclamé par la foule.', 9),
    ('4fb4886b-0ca0-5c02-8a9e-457125c1b548'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Quel roman de 1862 met en scène la misère sociale ?', 'mcq', '["Les Misérables","Germinal","Le Rouge et le Noir","Madame Bovary"]'::jsonb, 0, 'Écrit en exil, Les Misérables suit Jean Valjean, ancien forçat, et dénonce l’injustice sociale.', 10),
    ('9a36c97e-6089-500c-b3da-ebfb2e988a73'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'Pourquoi Hugo devient-il une référence des républicains ?', 'mcq', '["Parce qu’il a toujours été républicain","Par son combat pour le suffrage universel et son opposition au Second Empire","Parce qu’il a fondé la IIIe République","Parce qu’il a été président"]'::jsonb, 1, 'Son évolution politique et vingt ans d’exil font de lui un symbole de la résistance au pouvoir personnel.', 11),
    ('0b70c15b-2fdb-55a9-b74b-d9acef95c478'::uuid, 'bbda3ff4-5e80-52c2-9a2f-ca62802d4bf4'::uuid, 'À sa mort en 1885, Victor Hugo reçoit des funérailles nationales et entre au Panthéon.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La IIIe République honore en lui une figure fondatrice de la culture républicaine.', 12),
    ('6bf994bb-3b38-52b4-801c-0597b5cc8a71'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Dans quelle région se trouve Le Creusot ?', 'mcq', '["En Lorraine","En Bourgogne (Saône-et-Loire)","Dans le Nord","En Provence"]'::jsonb, 1, 'Le Creusot est en Saône-et-Loire, près de gisements de charbon et de fer.', 1),
    ('06241e1f-64c4-5dbb-a52c-1d0152b207d1'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'En quelle année les frères Schneider rachètent-ils le Creusot ?', 'mcq', '["1789","1848","1836","1870"]'::jsonb, 2, 'Adolphe et Eugène Schneider rachètent les forges en 1836.', 2),
    ('6d6a1ac1-af33-5f90-82b6-9fbc13bba6e7'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Quelle activité est au cœur des établissements Schneider ?', 'mcq', '["Le textile","L’agriculture","La banque","La sidérurgie et la construction mécanique"]'::jsonb, 3, 'Fonte, fer, acier, locomotives, rails et machines font du Creusot un grand centre sidérurgique.', 3),
    ('70ffd58b-16d2-564a-9928-99e3cecedea7'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Quelle fonction politique Eugène Schneider occupe-t-il de 1867 à 1870 ?', 'mcq', '["Président du Corps législatif","Empereur","Préfet de la Seine","Président de la République"]'::jsonb, 0, 'Il préside l’assemblée élue du Second Empire, ce qui montre le lien entre grands industriels et pouvoir.', 4),
    ('7aa68ec2-bdd5-5bae-b349-e75b2e528567'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Qu’appelle-t-on le paternalisme ?', 'mcq', '["Le pouvoir du père dans la famille","L’encadrement de la vie des ouvriers par le patron (logement, école, santé)","Un syndicat ouvrier","Une loi sur le travail des enfants"]'::jsonb, 1, 'Le patron offre des avantages sociaux mais contrôle ainsi la vie des ouvriers.', 5),
    ('50d05f8e-8ed4-5e96-968c-626bf42f7a1f'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Schneider construit des écoles, des logements et un hôpital pour ses ouvriers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ces équipements fixent la main-d’œuvre et forment les futurs ouvriers.', 6),
    ('aae5d5b6-4a7e-5a8d-bc9c-ab8ce4fa697b'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'D’où viennent principalement les ouvriers du Creusot ?', 'mcq', '["De Paris","D’Angleterre","Des campagnes voisines","Des colonies"]'::jsonb, 2, 'L’exode rural fournit à l’usine une main-d’œuvre venue des campagnes.', 7),
    ('ecb36bcd-779a-5b7b-ab86-b1b0e55d001c'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Que produit notamment le Creusot pour le chemin de fer ?', 'mcq', '["Des locomotives et des rails","Des wagons en bois uniquement","Des billets","Des gares"]'::jsonb, 0, 'Les premières locomotives du Creusot sortent dès 1838 ; les rails alimentent l’essor du réseau.', 8),
    ('bb8d9254-dff7-5362-b3a0-4642148b3eed'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Que se passe-t-il au Creusot en 1870 ?', 'mcq', '["Une révolution qui renverse Napoléon III","La fermeture définitive de l’usine","De grandes grèves ouvrières","L’arrivée des Prussiens"]'::jsonb, 2, 'Les grèves de janvier et du printemps 1870 montrent la montée d’une conscience ouvrière.', 9),
    ('dc3a6157-5452-5253-b74e-f9c5fceb51ae'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Quelle loi permet aux ouvriers de faire grève légalement depuis 1864 ?', 'mcq', '["La loi Falloux","La loi Ollivier","La loi Ferry","La loi de 1905"]'::jsonb, 1, 'La loi Ollivier supprime le délit de coalition.', 10),
    ('de5e3a17-00e3-5e1c-a480-ad7a50d159a8'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Eugène Schneider est opposé au Second Empire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il soutient Napoléon III, dont la politique favorise les grands industriels.', 11),
    ('6e557a9e-eba4-5b6a-a22f-8ff8df245f59'::uuid, 'ddf338df-da8c-594c-807f-78bacc7cee2f'::uuid, 'Quelle ville proche accueille les chantiers navals des Schneider ?', 'mcq', '["Marseille","Le Havre","Lyon","Chalon-sur-Saône"]'::jsonb, 3, 'Reliée au Creusot par le canal du Centre, Chalon-sur-Saône construit des bateaux à vapeur.', 12),
    ('a5b31f99-b920-5287-b224-937689c84e28'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Quand la Troisième République est-elle proclamée ?', 'mcq', '["Le 4 septembre 1870","Le 22 septembre 1792","Le 24 février 1848","Le 11 novembre 1918"]'::jsonb, 0, 'Elle est proclamée à Paris après la capture de Napoléon III à Sedan.', 1),
    ('da0fc77b-d656-5ea8-97f7-752c5cf0fe11'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Que rendent obligatoire les lois Jules Ferry de 1881-1882 ?', 'mcq', '["Le service militaire","Le vote des femmes","L’école primaire, gratuite et laïque","Le catéchisme"]'::jsonb, 2, 'L’école de la République forme des citoyens attachés aux valeurs de 1789.', 2),
    ('13b4c0c1-dfcf-5ea0-9ddb-0e20dd78b6dd'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Quelle date devient la fête nationale en 1880 ?', 'mcq', '["Le 11 novembre","Le 4 août","Le 1er mai","Le 14 juillet"]'::jsonb, 3, 'Le 14 juillet rappelle à la fois la prise de la Bastille (1789) et la fête de la Fédération (1790).', 3),
    ('3769f81b-6c8b-56ab-9fdd-2718753a85f6'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Quelle liberté est accordée en 1884 ?', 'mcq', '["La liberté syndicale","La liberté de culte","Le droit de vote des femmes","La liberté d’association"]'::jsonb, 0, 'La loi Waldeck-Rousseau de 1884 autorise les syndicats ; la liberté d’association date de 1901.', 4),
    ('1dc29adc-dd0e-580f-be00-fccb3d97facd'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'De quoi Alfred Dreyfus est-il accusé à tort en 1894 ?', 'mcq', '["De vol","D’espionnage au profit de l’Allemagne","De désertion","D’assassinat"]'::jsonb, 1, 'Officier juif, il est condamné sans preuve ; le vrai coupable était le commandant Esterhazy.', 5),
    ('2aaa6102-e85c-5870-a2ea-0d8181291da7'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Qui publie « J’accuse… ! » en 1898 ?', 'mcq', '["Victor Hugo","Jean Jaurès","Émile Zola","Georges Clemenceau"]'::jsonb, 2, 'Zola accuse l’état-major d’avoir condamné un innocent ; le texte paraît dans L’Aurore, journal de Clemenceau.', 6),
    ('07b97969-aa87-5586-80ba-c798e3e1867b'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Que révèle l’affaire Dreyfus ?', 'mcq', '["L’absence de divisions en France","Un antisémitisme violent dans une partie de la société","La victoire de la monarchie","La fin de l’armée"]'::jsonb, 1, 'Beaucoup d’antidreyfusards attaquent Dreyfus parce qu’il est juif.', 7),
    ('aa755276-1386-52cf-905c-8129b7ad4498'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'La loi de 1905 interdit toutes les religions en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle garantit au contraire la liberté de conscience et le libre exercice des cultes ; l’État ne reconnaît ni ne finance aucun culte.', 8),
    ('e51b8442-97e2-5159-b17b-713701b3ab36'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Quel texte soumet les « indigènes » des colonies à un régime pénal spécial ?', 'mcq', '["Le Code civil","La loi de 1905","Le code de l’indigénat","La Déclaration des droits de l’homme"]'::jsonb, 2, 'Instauré en 1881 en Algérie puis étendu, il prévoit des sanctions sans jugement pour les sujets colonisés.', 9),
    ('f7654b94-3997-56f3-aabe-29786e346fb6'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Quel homme politique défend la colonisation au nom d’une prétendue « mission civilisatrice » ?', 'mcq', '["Jean Jaurès","Alfred Dreyfus","Georges Clemenceau","Jules Ferry"]'::jsonb, 3, 'En 1885, Ferry avance des arguments économiques, politiques et « civilisateurs » ; Clemenceau lui répond en dénonçant la colonisation.', 10),
    ('e47b7a2c-bdbe-5a4c-b60c-a6396beaadfe'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'Quelle conférence de 1884-1885 organise le partage de l’Afrique entre Européens ?', 'mcq', '["La conférence de Berlin","Le congrès de Vienne","La conférence de Yalta","Le traité de Versailles"]'::jsonb, 0, 'Les puissances y fixent les règles de l’occupation des côtes africaines.', 11),
    ('a49c3359-11e9-5609-9a53-75e1642233ab'::uuid, 'bf102f51-42ba-5736-bd2a-8676584efc55'::uuid, 'En 1914, l’empire colonial français couvre environ 10 millions de km².', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le deuxième empire colonial du monde, derrière l’Empire britannique.', 12),
    ('e01235d4-6f4b-5534-b538-bd24b330d71c'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Qui dirige le Nouveau dictionnaire de pédagogie ?', 'mcq', '["Jules Ferry","Ferdinand Buisson","Camille Sée","Paul Bert"]'::jsonb, 1, 'Ferdinand Buisson, directeur de l’enseignement primaire, est un grand artisan de l’école laïque.', 1),
    ('fc56cd55-a63e-51e4-b44d-cad2af1d80b5'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Que crée la loi Camille Sée de 1880 ?', 'mcq', '["L’école primaire obligatoire","Le droit de vote des femmes","L’enseignement secondaire public pour les jeunes filles","Les universités"]'::jsonb, 2, 'Elle ouvre des collèges et lycées publics de jeunes filles.', 2),
    ('589f7bd2-0bea-5936-8993-69db01f77699'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Pourquoi les républicains veulent-ils instruire les filles ?', 'mcq', '["Pour qu’elles deviennent soldats","Pour qu’elles votent","Pour les éloigner de l’influence de l’Église et former des mères républicaines","Pour qu’elles apprennent le latin"]'::jsonb, 2, 'Les républicains veulent que les futures mères transmettent les valeurs républicaines.', 3),
    ('9aa4945f-d5dd-57a9-97fa-b35763bb17c6'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Les lois Ferry de 1881-1882 rendent l’école primaire obligatoire pour les filles comme pour les garçons.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’obligation concerne tous les enfants de 6 à 13 ans.', 4),
    ('3845d78a-687a-501f-b9d0-4269ded9ef4b'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Quel diplôme termine le secondaire des filles avant 1924 ?', 'mcq', '["Le baccalauréat","Le brevet des collèges","L’agrégation","Un diplôme de fin d’études"]'::jsonb, 3, 'Sans latin ni grec, il ne donnait pas accès à l’université, contrairement au baccalauréat.', 5),
    ('e361ba37-db58-59b9-9b4b-8c9b80a5b4e7'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Quelle matière est ajoutée aux programmes des filles ?', 'mcq', '["Les travaux d’aiguille et l’économie domestique","Le latin","L’escrime","La philosophie"]'::jsonb, 0, 'Ces matières préparent au rôle d’épouse et de mère que la société de l’époque leur assigne.', 6),
    ('5b633491-3fbc-54e4-b907-ee8683c272b1'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Qui est la première bachelière française, en 1861 ?', 'mcq', '["Marie Curie","Louise Michel","Julie-Victoire Daubié","George Sand"]'::jsonb, 2, 'Julie-Victoire Daubié obtient le baccalauréat à Lyon en 1861, avant même la Troisième République.', 7),
    ('28ce2c1a-8f2d-54cc-9482-0d4ca73ecb46'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Que prévoit la loi Paul Bert de 1879 ?', 'mcq', '["Une école normale d’institutrices par département","Le droit de vote des institutrices","La fermeture des écoles religieuses","Le baccalauréat pour les filles"]'::jsonb, 0, 'Ces écoles forment les institutrices qui enseigneront dans les écoles de filles.', 8),
    ('2fffa116-fe7f-58d9-a372-928489ce038d'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Quelle école forme les professeures des lycées de jeunes filles ?', 'mcq', '["L’École polytechnique","L’École normale supérieure de Sèvres","Saint-Cyr","La Sorbonne"]'::jsonb, 1, 'Créée en 1881, l’ENS de Sèvres forme les enseignantes du secondaire féminin.', 9),
    ('b370d90b-5b82-5b18-a920-02c298168932'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'En quelle année les programmes du secondaire deviennent-ils identiques pour filles et garçons ?', 'mcq', '["1882","1905","1944","1924"]'::jsonb, 3, 'La réforme Bérard de 1924 aligne les programmes et ouvre aux filles la préparation du baccalauréat.', 10),
    ('7608ba3b-d5dd-51ea-80fb-b91515fd9b98'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Avant 1914, les institutrices sont payées autant que les instituteurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Leur salaire est longtemps inférieur, signe d’une égalité encore incomplète.', 11),
    ('5ef4f91e-54b2-5623-b8e0-ef11b686332e'::uuid, 'ed9a8e07-f2c2-5e5d-8c88-558d3abf810a'::uuid, 'Quel rôle joue l’institutrice dans un village de la Troisième République ?', 'mcq', '["Elle représente l’Église","Elle incarne la République et enseigne la morale laïque","Elle dirige la mairie","Elle est élue députée"]'::jsonb, 1, 'Comme l’instituteur, elle diffuse les valeurs républicaines, souvent face à l’influence du curé.', 12),
    ('08599fa9-c895-5f0a-bdbe-458c18aa7f4f'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Depuis quand l’Algérie est-elle conquise par la France ?', 'mcq', '["1830","1848","1870","1905"]'::jsonb, 0, 'La prise d’Alger, en juillet 1830, ouvre une longue conquête.', 1),
    ('911e250f-422c-53ff-bbc7-980a8059aa93'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Quel est le statut administratif d’Alger au début du XXe siècle ?', 'mcq', '["Un protectorat","Une colonie à part","La préfecture d’un département français","Un État indépendant"]'::jsonb, 2, 'L’Algérie est divisée en trois départements depuis 1848 : Alger, Oran, Constantine.', 2),
    ('ce9cbea6-1cfc-58b1-8d92-f0386055679b'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Que fait le décret Crémieux de 1870 ?', 'mcq', '["Il abolit l’esclavage","Il donne la citoyenneté française aux Juifs d’Algérie","Il crée le code de l’indigénat","Il sépare les Églises et l’État"]'::jsonb, 1, 'Les Juifs d’Algérie deviennent citoyens français, contrairement aux Algériens musulmans.', 3),
    ('e9aa3cb0-2cca-5098-855a-17c51aabbbc4'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Quel est le statut des Algériens musulmans ?', 'mcq', '["Citoyens français","Étrangers","Européens naturalisés","Sujets français sans droits politiques"]'::jsonb, 3, 'Soumis au code de l’indigénat, ils ne votent pas aux élections nationales.', 4),
    ('13fdb621-e204-5bb0-b590-6b806473793e'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Comment appelle-t-on la vieille ville ottomane d’Alger ?', 'mcq', '["La Casbah","Mustapha","Bab-el-Oued","Le front de mer"]'::jsonb, 0, 'Perchée sur la colline, elle est faite de ruelles étroites et de maisons à terrasses.', 5),
    ('a547a231-5956-5dc1-87ed-077cde96cf1f'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'La loi de 1889 naturalise les enfants d’Européens nés en Algérie (Espagnols, Italiens, Maltais).', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette loi fait des Européens d’origine étrangère des citoyens français et renforce la population européenne.', 6),
    ('5e0891f7-774d-52d7-bde0-208c7ad4413f'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Où se trouve la ville européenne d’Alger ?', 'mcq', '["Dans la Casbah","Dans le désert","Dans la ville basse, le long de la mer","Sur une île"]'::jsonb, 2, 'Boulevards à arcades, places et immeubles de style parisien bordent le front de mer.', 7),
    ('8fc92bdd-01da-5d19-8271-91c0dc1c12c1'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Quel style architectural le gouverneur Jonnart encourage-t-il ?', 'mcq', '["Le style gothique","Le style néo-mauresque","Le style Art déco","Le style roman"]'::jsonb, 1, 'Ce style mêle décor d’inspiration arabe et techniques européennes, comme à la Grande Poste (1910).', 8),
    ('3508d958-9272-588b-868e-d3b87c6c17bf'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Que montre la toponymie des rues d’Alger coloniale ?', 'mcq', '["L’égalité entre habitants","L’influence ottomane","La domination française","L’indépendance de l’Algérie"]'::jsonb, 2, 'Les rues et places portent des noms de généraux et d’hommes politiques français.', 9),
    ('1283b949-62ba-598f-a5dd-a0739e231efd'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Quelle ville est reliée à Alger par des lignes maritimes régulières ?', 'mcq', '["Marseille","Londres","Rome","Tunis seulement"]'::jsonb, 0, 'Le port d’Alger vit des échanges avec la métropole, surtout Marseille.', 10),
    ('e2a27db1-5a4f-5c9c-a38a-0cfba28279b7'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Dans l’Alger coloniale, toutes les populations ont les mêmes droits.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La société coloniale est fondée sur l’inégalité des statuts entre citoyens et sujets.', 11),
    ('ca0cb3fb-2942-58da-917d-b3908a3c4fa8'::uuid, 'ea1fd7ea-5165-58b3-8e2d-04c837eaa9d2'::uuid, 'Que réclament les « Jeunes Algériens » avant 1914 ?', 'mcq', '["L’annexion au Maroc","Le départ immédiat de tous les Européens","Le retour des Ottomans","L’égalité des droits"]'::jsonb, 3, 'Cette petite élite formée à l’école française demande l’égalité au sein de la République.', 12),
    ('e04e4b81-ebb4-53c8-9f13-ae71a2228d79'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quel événement déclenche la crise de l’été 1914 ?', 'mcq', '["L’invasion de la Pologne","L’assassinat de l’archiduc François-Ferdinand à Sarajevo","La révolution russe","Le naufrage du Lusitania"]'::jsonb, 1, 'L’attentat du 28 juin 1914 entraîne, par le jeu des alliances, l’entrée en guerre des puissances européennes.', 1),
    ('ed00ad1e-68b6-5107-bfcd-1e8a0819f3bf'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quels pays forment la Triple-Entente en 1914 ?', 'mcq', '["Allemagne, Autriche-Hongrie, Italie","France, Royaume-Uni, États-Unis","France, Royaume-Uni, Russie","Russie, Empire ottoman, Bulgarie"]'::jsonb, 2, 'L’Italie rejoint les Alliés en 1915 et les États-Unis en 1917.', 2),
    ('dd1e6d30-8e0b-520c-a457-f16efb313cc2'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Comment appelle-t-on la guerre menée dans les tranchées de 1915 à 1917 ?', 'mcq', '["La guerre de position","La guerre de mouvement","La guerre éclair","La guerre froide"]'::jsonb, 0, 'Les armées s’enterrent face à face, et chaque offensive coûte des centaines de milliers de vies pour quelques kilomètres.', 3),
    ('e79bf445-2757-533c-ae22-45a1fda87b03'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Pourquoi parle-t-on d’une guerre mondiale ?', 'mcq', '["Parce qu’elle ne touche que l’Europe","Parce qu’elle dure un an","Parce que seuls les soldats y participent","Parce qu’elle mobilise les empires coloniaux et des pays de tous les continents"]'::jsonb, 3, 'Soldats coloniaux, travailleurs chinois, entrée en guerre des États-Unis et du Japon : le conflit est mondial.', 4),
    ('ed1e3b52-bede-57a7-8182-a92389bfe422'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quel peuple est victime d’un génocide en 1915-1916 ?', 'mcq', '["Les Arméniens","Les Serbes","Les Polonais","Les Grecs"]'::jsonb, 0, 'Le gouvernement jeune-turc organise massacres et déportations : environ 1,2 million de morts.', 5),
    ('e1ef786c-501e-55f4-8cc4-bcefb3ced559'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quand est signé l’armistice ?', 'mcq', '["Le 28 juin 1919","Le 11 novembre 1918","Le 8 mai 1945","Le 1er août 1914"]'::jsonb, 1, 'L’armistice de Rethondes met fin aux combats sur le front Ouest.', 6),
    ('ce276bf6-2a14-55d9-96d5-462e76ad6d44'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Environ 1,4 million de soldats français sont morts pendant la guerre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est environ un homme mobilisé sur six, une saignée qui marque durablement la France.', 7),
    ('6b08bf2b-74d6-5f9d-b2ac-36c56cd6a609'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quel président américain défend le droit des peuples à disposer d’eux-mêmes ?', 'mcq', '["Roosevelt","Lincoln","Wilson","Truman"]'::jsonb, 2, 'Ses Quatorze Points (janvier 1918) guident en partie les traités de paix.', 8),
    ('26c95fb9-a9fb-5b8c-a9ed-a8d144144957'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quel traité est imposé à l’Allemagne ?', 'mcq', '["Le traité de Saint-Germain","Le traité de Sèvres","Le traité de Trianon","Le traité de Versailles"]'::jsonb, 3, 'Signé le 28 juin 1919, il lui retire l’Alsace-Moselle et ses colonies et lui impose des réparations.', 9),
    ('39e65da5-c9a9-5cd6-ad9d-433f49bb1b30'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quels empires disparaissent à la suite de la guerre ?', 'mcq', '["Britannique et français","Allemand, austro-hongrois, russe et ottoman","Japonais et chinois","Espagnol et portugais"]'::jsonb, 1, 'Les empires multinationaux vaincus ou effondrés laissent place à de nouveaux États.', 10),
    ('a1452492-5113-5232-91c4-94284e5d5a00'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Quelle organisation est créée en 1919 pour préserver la paix ?', 'mcq', '["L’ONU","L’OTAN","La Société des Nations","L’Union européenne"]'::jsonb, 2, 'La SDN, installée à Genève, doit régler les conflits par la négociation.', 11),
    ('28dd2398-30e7-5921-ae07-0297d8d877c5'::uuid, '93ebdbde-cf6d-55c5-a890-8a304d7e1af2'::uuid, 'Les Allemands considèrent le traité de Versailles comme une paix juste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils le vivent comme un « diktat », une paix imposée et humiliante.', 12),
    ('f65dfdf8-05c9-5d5b-b26e-bb4cff36e469'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Dans quelle région se déroule la bataille de la Somme ?', 'mcq', '["En Lorraine","En Picardie","En Alsace","En Champagne"]'::jsonb, 1, 'La Somme est un fleuve et un département de Picardie, où se rejoignaient les armées britannique et française.', 1),
    ('46e5bdf5-b7dd-5df5-9ab3-6f08d5a9308d'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Quand commence la bataille de la Somme ?', 'mcq', '["Le 21 février 1916","Le 11 novembre 1918","Le 1er juillet 1916","Le 6 septembre 1914"]'::jsonb, 2, 'L’offensive commence le 1er juillet 1916, après une semaine de bombardement.', 2),
    ('32640114-d54b-53e6-a75d-7ffd6e0d43cc'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Quelle armée fournit l’essentiel de l’effort sur la Somme ?', 'mcq', '["L’armée allemande","L’armée américaine","L’armée russe","L’armée britannique"]'::jsonb, 3, 'La France étant engagée à Verdun, les Britanniques portent la plus grande part de l’offensive.', 3),
    ('b54a498e-b0f9-5567-83d3-4cee291be14e'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Quelle décision alliée prépare l’offensive de la Somme ?', 'mcq', '["La conférence de Chantilly (1915)","Le traité de Versailles","Le congrès de Vienne","L’armistice de Rethondes"]'::jsonb, 0, 'Les Alliés y décident d’attaquer ensemble en 1916 sur plusieurs fronts.', 4),
    ('491b1ca6-a367-5662-b5da-c59de245ee2b'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Quelle innovation apparaît pour la première fois sur la Somme, en septembre 1916 ?', 'mcq', '["Le gaz de combat","Le char d’assaut","La mitrailleuse","Le sous-marin"]'::jsonb, 1, 'Les tanks britanniques attaquent à Flers-Courcelette le 15 septembre 1916.', 5),
    ('ec789d8a-1839-5a7e-86d9-468e91be3235'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Des soldats de tout l’Empire britannique ont combattu sur la Somme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Canadiens, Terre-Neuviens, Australiens, Néo-Zélandais, Sud-Africains et Indiens y ont combattu.', 6),
    ('a82a99e8-6cab-5fb6-ad50-c680db3a9f31'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'À quoi sert l’aviation pendant la bataille ?', 'mcq', '["À bombarder Berlin","À transporter les troupes","À observer les lignes ennemies et régler l’artillerie","À ravitailler les civils"]'::jsonb, 2, 'Avions et ballons d’observation photographient les tranchées et guident les tirs.', 7),
    ('f4f80bfd-d0f2-5bdd-93ad-639d1256d815'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Combien de soldats britanniques meurent le 1er juillet 1916 ?', 'mcq', '["Environ 200","Près de 20 000","Environ 1 million","Environ 2 000"]'::jsonb, 1, 'C’est la journée la plus meurtrière de l’histoire de l’armée britannique.', 8),
    ('5ece2cc7-e6b6-5a0e-a70d-2e76d6ee9a18'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Quel est le bilan total approximatif de la bataille ?', 'mcq', '["Environ 10 000 victimes","Aucune perte grâce aux chars","Plus d’un million de tués, blessés et disparus","Environ 50 000 victimes"]'::jsonb, 2, 'Pour une avancée d’une dizaine de kilomètres, les pertes dépassent le million pour les trois armées.', 9),
    ('5b7432d7-1223-56a1-ade8-2d5b1257690b'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Quel monument porte les noms de plus de 72 000 soldats disparus ?', 'mcq', '["Le mémorial de Thiepval","L’ossuaire de Douaumont","L’Arc de Triomphe","Le mémorial de Caen"]'::jsonb, 0, 'Il honore les soldats britanniques et sud-africains disparus sans sépulture connue.', 10),
    ('a91e96b7-336f-5b3d-b009-a737c05e9089'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Des travailleurs chinois ont été recrutés par les Alliés pendant la guerre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils travaillent à l’arrière du front (ports, routes, dépôts) : un signe de l’échelle mondiale de la guerre.', 11),
    ('d834f62e-376e-54a1-9075-84ed6f7fe180'::uuid, 'de92b146-abc4-5cfa-a8ca-7a13822e2eeb'::uuid, 'Quelle bataille allemande de 1916 explique que la France engage moins de forces sur la Somme ?', 'mcq', '["La Marne","Waterloo","Sedan","Verdun"]'::jsonb, 3, 'Commencée le 21 février 1916, Verdun absorbe une grande partie de l’armée française.', 12),
    ('de2f5bb9-e9fd-5fe6-a93d-be39bf734a92'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Pourquoi appelle-t-on l’Autriche-Hongrie la « double monarchie » ?', 'mcq', '["Parce qu’elle a deux empereurs","Parce que deux États sont réunis sous un même souverain","Parce qu’elle a deux capitales en guerre","Parce qu’elle est alliée à deux pays"]'::jsonb, 1, 'Depuis le compromis de 1867, l’Autriche et la Hongrie partagent le même souverain, François-Joseph.', 1),
    ('68c0da6d-2efa-5f28-9cc8-006cf96b6f52'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Qu’est-ce qu’un empire multinational ?', 'mcq', '["Un empire composé de plusieurs nationalités","Un empire commercial","Une alliance de pays","Une république fédérale"]'::jsonb, 0, 'L’Autriche-Hongrie rassemble une dizaine de peuples, sans majorité nationale.', 2),
    ('ba83df45-38c4-5023-9b6a-96c11e4a45db'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Qui assassine l’archiduc François-Ferdinand à Sarajevo ?', 'mcq', '["Un anarchiste français","Un soldat russe","Gavrilo Princip, nationaliste serbe de Bosnie","Un espion allemand"]'::jsonb, 2, 'Princip appartient à un groupe qui veut unir les Slaves du Sud autour de la Serbie.', 3),
    ('be617ad6-6efb-5f04-895a-585bb566b052'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'À quel pays l’Autriche-Hongrie déclare-t-elle la guerre le 28 juillet 1914 ?', 'mcq', '["À la Serbie","À la France","À la Russie","À l’Italie"]'::jsonb, 0, 'Après un ultimatum jugé inacceptable par Belgrade, la guerre commence ; les alliances font le reste.', 4),
    ('9665f5f3-727d-54be-acec-6ca8a71640e0'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Quel territoire l’Autriche-Hongrie annexe-t-elle en 1908 ?', 'mcq', '["La Galicie","La Bohême","Le Tyrol","La Bosnie-Herzégovine"]'::jsonb, 3, 'Cette annexion attise la rivalité avec la Serbie et la Russie.', 5),
    ('007e49fd-5d3f-578c-b1ab-fb3ab51f6c31'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Quel empereur règne de 1848 à 1916 ?', 'mcq', '["Guillaume II","François-Joseph","Charles Ier","Nicolas II"]'::jsonb, 1, 'Son très long règne incarne l’unité de l’empire ; sa mort en 1916 l’affaiblit encore.', 6),
    ('efd697de-fef7-5dd5-a14f-cad56f1adcca'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'L’Autriche-Hongrie combat aussi contre l’Italie à partir de 1915.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Entrée en guerre aux côtés de l’Entente, l’Italie ouvre un front dans les Alpes et sur l’Isonzo.', 7),
    ('84d8d583-b6b5-52cb-a06a-03126117ef77'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Quel État proclame son indépendance le 28 octobre 1918 ?', 'mcq', '["La Hongrie","L’Autriche","La Tchécoslovaquie","La Roumanie"]'::jsonb, 2, 'Tchèques et Slovaques fondent un État commun, dirigé par Masaryk.', 8),
    ('980787e5-a7cd-5a5a-88bd-7f6b9470d601'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Quel traité règle le sort de l’Autriche en 1919 ?', 'mcq', '["Le traité de Versailles","Le traité de Trianon","Le traité de Sèvres","Le traité de Saint-Germain-en-Laye"]'::jsonb, 3, 'Signé le 10 septembre 1919, il réduit l’Autriche à un petit État.', 9),
    ('fe69a27d-02e9-54b5-9644-943c49aef752'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Que le traité de Saint-Germain interdit-il à l’Autriche ?', 'mcq', '["D’avoir une armée","De s’unir à l’Allemagne","D’avoir une capitale","De commercer"]'::jsonb, 1, 'L’Anschluss est interdit : les vainqueurs ne veulent pas renforcer l’Allemagne.', 10),
    ('93ba1d4e-bc1e-572d-b10c-b796eb5ae23a'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Les nouvelles frontières de 1919-1920 correspondent exactement aux peuples.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque nouvel État compte des minorités : l’Europe centrale reste une zone de tension.', 11),
    ('bcb85597-324e-527a-be48-2039b65ed619'::uuid, '06ac9823-5d9e-5506-9973-e2d88d4fbfce'::uuid, 'Quelle part de son territoire la Hongrie perd-elle au traité de Trianon ?', 'mcq', '["Environ un dixième","La moitié","Aucune","Environ les deux tiers"]'::jsonb, 3, 'Au traité de Trianon (1920), elle perd notamment la Slovaquie, la Croatie et la Transylvanie.', 12),
    ('7ce683c5-a34f-5468-b7b4-ec0b0b32e398'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Depuis quand plus de la moitié de l’humanité vit-elle en ville ?', 'mcq', '["Depuis 1950","Depuis 1990","Depuis 2007","Depuis 2020"]'::jsonb, 2, 'L’ONU estime que la barre des 50 % a été franchie en 2007.', 1),
    ('1b6acea8-281d-50d7-9474-105d8cb202d2'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Qu’est-ce que la métropolisation ?', 'mcq', '["L’étalement des villes à la campagne","La concentration des populations, activités et fonctions de commandement dans les grandes villes","La construction de métros","Le déclin des villes"]'::jsonb, 1, 'La métropolisation renforce le poids des plus grandes villes, qui concentrent le pouvoir.', 2),
    ('78aef18f-399e-57f5-95ee-14377096f22b'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Qu’est-ce qui distingue une métropole d’une simple grande ville ?', 'mcq', '["Ses fonctions de commandement et son rayonnement","Sa superficie","Son climat","Son âge"]'::jsonb, 0, 'Une métropole domine un territoire par ses fonctions politiques, économiques et culturelles.', 3),
    ('fdf86168-e18e-5817-be9a-9102a2f3e4aa'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Quel est un exemple de quartier d’affaires ?', 'mcq', '["La Casbah d’Alger","Le Marais","Un bidonville","La Défense"]'::jsonb, 3, 'La Défense, près de Paris, concentre sièges sociaux et tours de bureaux.', 4),
    ('817ef774-1aeb-54b0-bbaf-165bd15830c1'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Quelle ville est une métropole de rang mondial ?', 'mcq', '["Rennes","Londres","Montpellier","Clermont-Ferrand"]'::jsonb, 1, 'Londres commande l’économie et la finance mondiales, comme New York, Tokyo ou Paris.', 5),
    ('c68733b1-2ae5-5b65-99eb-6cb757e20e59'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Une mégapole est forcément une métropole mondiale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une mégapole est définie par sa taille (plus de 10 millions d’habitants) ; beaucoup ont un rayonnement mondial limité.', 6),
    ('5dc82a34-4c77-5b90-bca6-aa7ef38872fe'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Qu’est-ce qu’une mégalopole ?', 'mcq', '["Une ville de plus de 10 millions d’habitants","Un chapelet de métropoles reliées entre elles","Un bidonville géant","Un quartier d’affaires"]'::jsonb, 1, 'La Mégalopolis américaine relie Boston, New York, Philadelphie, Baltimore et Washington.', 7),
    ('62a41fed-80b4-5453-8141-352d6df5dcf4'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Où se trouve la mégalopole européenne ?', 'mcq', '["De Madrid à Varsovie","De Paris à Moscou","De Londres à Milan","De Lisbonne à Rome"]'::jsonb, 2, 'Cette « dorsale » passe par le Benelux et la vallée du Rhin.', 8),
    ('e42c7334-13d6-5299-8cec-e31afce91d4d'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Dans quelles régions du monde la croissance urbaine est-elle la plus rapide ?', 'mcq', '["En Afrique et en Asie","En Europe de l’Ouest","En Amérique du Nord","Au Japon"]'::jsonb, 0, 'Les pays en développement et émergents connaissent la croissance urbaine la plus forte, avec souvent des quartiers informels.', 9),
    ('8ba597c1-b73a-566e-b223-94ffeb8197c4'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Que désigne le modèle centre-périphérie ?', 'mcq', '["Un plan de ville en cercle","Un réseau de métro","La domination d’un centre sur des espaces qui en dépendent","L’égalité entre territoires"]'::jsonb, 2, 'Le centre concentre richesse et pouvoir ; les périphéries en dépendent.', 10),
    ('1783ca3d-454f-595a-b47d-7e1253f29118'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Les métropoles sont en concurrence pour accueillir les Jeux olympiques ou des sièges d’entreprises.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Attirer ces grands événements et ces entreprises renforce leur rayonnement.', 11),
    ('51b44b20-1d13-53d5-9024-0d65d0e3923f'::uuid, '5eadb667-4287-53cf-ac4d-ea14eb524bf3'::uuid, 'Qu’est-ce qu’une agglomération urbaine ?', 'mcq', '["Une ville sans banlieue","Un village","Une métropole mondiale","Une ville-centre et ses banlieues formant un bâti continu"]'::jsonb, 3, 'L’agglomération dépasse souvent les limites de la commune-centre.', 12),
    ('cba0ebbd-b497-5bdb-b4be-a7f8882b3113'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Quel statut particulier Lyon a-t-elle depuis 2015 ?', 'mcq', '["Capitale régionale unique","Métropole collectivité territoriale exerçant aussi les compétences du département","Ville libre","Département d’outre-mer"]'::jsonb, 1, 'La Métropole de Lyon est une collectivité à statut particulier qui a remplacé le département du Rhône sur son territoire.', 1),
    ('c5359cd8-82e9-5c30-b233-d7c3b03cbd9f'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Au confluent de quels cours d’eau se trouve Lyon ?', 'mcq', '["La Seine et la Marne","La Loire et l’Allier","Le Rhône et la Saône","La Garonne et la Dordogne"]'::jsonb, 2, 'La Presqu’île s’étend entre les deux, jusqu’au confluent.', 2),
    ('6befcafd-116c-5257-9f9c-b19e789dd534'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Quel est le grand quartier d’affaires de Lyon ?', 'mcq', '["La Part-Dieu","La Croix-Rousse","Fourvière","Les Minguettes"]'::jsonb, 0, 'Autour de la gare TGV, la Part-Dieu concentre bureaux et tours.', 3),
    ('d18d76a8-fd38-56d5-8044-49e859217698'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Le quartier Confluence a été construit sur :', 'mcq', '["Des terres agricoles","Une forêt","Un ancien aéroport","D’anciens terrains industriels et portuaires"]'::jsonb, 3, 'C’est un exemple de reconquête de friches et de front d’eau.', 4),
    ('5b078031-5f0f-5eb8-ad2a-c3012dadcdc2'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Quel équipement culturel ouvre en 2014 à la Confluence ?', 'mcq', '["L’Opéra de Lyon","Le musée des Confluences","Le Louvre-Lens","Le Groupama Stadium"]'::jsonb, 1, 'Ce musée de sciences et de sociétés est devenu un symbole de la métropole.', 5),
    ('733b79ff-7370-5b28-92da-be6f68c03741'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Que signifie le fonctionnement polycentrique de Lyon ?', 'mcq', '["La ville a plusieurs centres d’activité","La ville n’a pas de centre","La ville est un seul quartier","La ville est circulaire"]'::jsonb, 0, 'Presqu’île, Part-Dieu, Confluence, Gerland : plusieurs pôles se partagent les fonctions.', 6),
    ('5c497b68-30a3-546a-bd13-d44526784407'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Lyon accueille le siège d’Interpol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’organisation internationale de police criminelle y a son siège depuis 1989.', 7),
    ('99340453-5523-500a-9c37-bf86ce3b9e0b'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Qu’est-ce que l’étalement urbain ?', 'mcq', '["La densification du centre","La progression de l’urbanisation sur les espaces ruraux proches","La construction de tours","La disparition des banlieues"]'::jsonb, 1, 'Les périurbains vivent de plus en plus loin et se déplacent chaque jour vers la métropole.', 8),
    ('50d409d1-7937-5914-9403-59c477581cc1'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Où se concentrent plutôt les quartiers populaires de la métropole lyonnaise ?', 'mcq', '["À l’ouest, dans les Monts d’Or","Dans la Presqu’île","À l’est (Vaulx-en-Velin, Vénissieux)","Sur la colline de Fourvière"]'::jsonb, 2, 'Les banlieues de l’Est concentrent logements sociaux et difficultés sociales.', 9),
    ('c7299062-93a5-5615-84c1-b98d61f8146b'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Quel aéroport dessert la métropole lyonnaise ?', 'mcq', '["Roissy-Charles-de-Gaulle","Saint-Exupéry","Orly","Blagnac"]'::jsonb, 1, 'Lyon-Saint-Exupéry, à l’est, est relié au centre par tramway express et à la ligne TGV.', 10),
    ('e808c186-e7a4-5e72-af38-973a36247408'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'La métropolisation de Lyon a réduit tous les contrastes sociaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle les a plutôt accentués : gentrification de certains quartiers, relégation d’autres.', 11),
    ('9e5c9520-d3c1-5e8e-b782-c918fef58789'::uuid, '1ebc9332-665e-5bcc-9340-b64a87931bff'::uuid, 'Comment appelle-t-on la zone industrielle qui longe le Rhône au sud de Lyon ?', 'mcq', '["La vallée de la chimie","La Silicon Valley","La dorsale européenne","La Plaine Saint-Denis"]'::jsonb, 0, 'Raffinerie de Feyzin et usines chimiques bordent le fleuve.', 12),
    ('882792fe-abc0-5d97-afda-0ed1458f6f5e'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Combien d’habitants compte environ le Grand Londres ?', 'mcq', '["1 million","3 millions","9 millions","30 millions"]'::jsonb, 2, 'Le Grand Londres compte près de 9 millions d’habitants, plus de 14 millions avec sa région urbaine.', 1),
    ('3d9dbfab-fd80-52aa-8f46-c96770c10bf9'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Quel quartier est le cœur historique de la finance londonienne ?', 'mcq', '["La City","Stratford","Chelsea","Heathrow"]'::jsonb, 0, 'La City concentre banques, assurances et bourse depuis des siècles.', 2),
    ('9de75407-5489-5575-beb5-d0793280f200'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Que sont devenus les Docklands ?', 'mcq', '["Un parc naturel","Un aéroport","Une zone agricole","Un quartier d’affaires et résidentiel autour de Canary Wharf"]'::jsonb, 3, 'Réhabilités à partir de 1981, ces anciens docks portent aujourd’hui des tours de bureaux.', 3),
    ('e76b1327-e15e-54f3-9b79-efe1a26519e1'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Quel quartier de l’Est londonien a été rénové pour les Jeux olympiques de 2012 ?', 'mcq', '["Kensington","Stratford","Westminster","Soho"]'::jsonb, 1, 'Le parc olympique a transformé cet ancien quartier industriel et pauvre.', 4),
    ('40e323fe-0598-5d1a-86e8-ed90323f4e11'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Quel est le principal aéroport de Londres ?', 'mcq', '["Heathrow","Orly","Schiphol","Stansted"]'::jsonb, 0, 'Heathrow est l’un des aéroports les plus fréquentés du monde ; Londres en compte six internationaux.', 5),
    ('c794d0dc-ec14-5ece-8cc0-3fd72e0adc77'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Le Brexit a fait perdre à la City toute son importance financière.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Certaines activités sont parties vers l’UE, mais la City reste l’une des premières places financières mondiales.', 6),
    ('6dfcb9ba-d91e-5af3-8afa-d32ad2467b0b'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Où est installée la Tate Modern ?', 'mcq', '["Dans un ancien palais royal","Dans une ancienne centrale électrique","Dans une gare","Dans un stade"]'::jsonb, 1, 'Ce musée d’art moderne ouvert en 2000 occupe l’ancienne centrale de Bankside.', 7),
    ('9e991d18-461f-5bee-b9bb-906cddc07449'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Quel rôle joue la ceinture verte (Green Belt) ?', 'mcq', '["Elle accueille les usines","Elle protège les quartiers d’affaires","Elle limite l’étalement urbain","Elle relie les aéroports"]'::jsonb, 2, 'En limitant l’étalement, elle accroît aussi la pression immobilière dans l’agglomération.', 8),
    ('d468ceb1-e77a-516d-8ce1-e03eee151930'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Quel train relie Londres à Paris par le tunnel sous la Manche ?', 'mcq', '["Le Thalys","L’Eurostar","L’ICE","Le Frecciarossa"]'::jsonb, 1, 'Il part de St Pancras et relie Paris en 2 h 20 environ.', 9),
    ('229096fe-ddea-5376-903e-1a0261673386'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Quelle ligne ferroviaire ouverte en 2022 traverse Londres d’est en ouest ?', 'mcq', '["La ligne Elizabeth","Le RER A","La ligne Victoria","Le DLR"]'::jsonb, 0, 'Cette grande ligne a renforcé les connexions entre les pôles de la métropole et l’aéroport d’Heathrow.', 10),
    ('2eeb569b-0048-5e53-ae85-4306dfeb242c'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'À Londres, des quartiers très pauvres existent à proximité immédiate de Canary Wharf.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Tower Hamlets, voisin des tours de Canary Wharf, compte parmi les quartiers les plus pauvres du pays.', 11),
    ('bfa129b7-1c42-582f-b70d-4baee0382e21'::uuid, '85236155-4515-5089-b065-ec388a9ef23c'::uuid, 'Qu’est-ce que la gentrification ?', 'mcq', '["La construction de tours","La fuite des riches","La démolition des bidonvilles","L’installation de ménages aisés dans un quartier populaire, qui en chasse les habitants modestes"]'::jsonb, 3, 'La hausse des loyers repousse les classes populaires vers la périphérie.', 12),
    ('3004759c-1830-5384-9ce8-19fdb869b4a6'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Qu’est-ce qu’un espace productif ?', 'mcq', '["Un espace naturel protégé","Un espace aménagé pour produire des biens ou des services","Un quartier résidentiel","Une zone sans activité"]'::jsonb, 1, 'Une usine, un port, un quartier d’affaires ou un bassin agricole sont des espaces productifs.', 1),
    ('bcad7a58-d0d5-5cd3-9662-6e7777c1f401'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Que désigne la littoralisation ?', 'mcq', '["L’érosion des côtes","La montée des océans","La concentration des activités et des hommes sur les littoraux","Le tourisme balnéaire uniquement"]'::jsonb, 2, 'Les grandes zones industrialo-portuaires s’installent au bord de la mer, porte d’entrée du commerce mondial.', 2),
    ('751eb0fa-96e8-50db-bc32-45cdf28f010d'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Quelle part du commerce mondial, en volume, passe par la mer ?', 'mcq', '["Environ 20 %","Environ 50 %","Environ 5 %","Environ 80 %"]'::jsonb, 3, 'Le transport maritime est le moins coûteux pour les grandes quantités.', 3),
    ('39a3d123-4864-5251-b2ad-1298ecadebd4'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Qu’est-ce qu’une chaîne mondiale de valeur ajoutée ?', 'mcq', '["Le découpage de la production en étapes réalisées dans différents pays","Une chaîne de magasins","Un réseau de câbles","Une usine unique"]'::jsonb, 0, 'Chaque étape est localisée là où elle est la plus rentable.', 4),
    ('8ae72caa-d53c-5909-b4b8-07d9387507c6'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Dans la production d’un smartphone, quelle étape rapporte le moins de valeur ajoutée ?', 'mcq', '["La conception","L’assemblage","La marque","Le logiciel"]'::jsonb, 1, 'L’assemblage, souvent réalisé en Asie avec une main-d’œuvre peu payée, capte une faible part de la valeur.', 5),
    ('c889b2e0-e4c9-5245-8f58-de82b292f3be'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Où se concentrent les activités à forte valeur ajoutée ?', 'mcq', '["Dans les espaces ruraux isolés","Dans les déserts","Dans les métropoles","Dans les montagnes"]'::jsonb, 2, 'Sièges sociaux, finance et recherche cherchent les métropoles, bien connectées et riches en main-d’œuvre qualifiée.', 6),
    ('262f9155-1b23-5e36-861a-4880aaf37cdd'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Un technopôle associe universités, recherche et entreprises innovantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La Silicon Valley ou le plateau de Saclay en sont des exemples.', 7),
    ('571de1d9-ae15-5e3d-9715-5bb20e83a27f'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Quel est le premier port d’Europe ?', 'mcq', '["Marseille","Hambourg","Anvers","Rotterdam"]'::jsonb, 3, 'Rotterdam domine la Northern Range, la façade maritime de la mer du Nord.', 8),
    ('914e212c-7d0e-5a41-ae12-640f529ac78d'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Quels flux sont dits immatériels ?', 'mcq', '["Les données et les capitaux","Les conteneurs","Le pétrole","Les touristes"]'::jsonb, 0, 'Ils circulent surtout par les câbles sous-marins et les réseaux numériques.', 9),
    ('16a648e4-7f86-57b1-bcb8-0de210a09df5'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Quels acteurs organisent les réseaux internationaux de production ?', 'mcq', '["Uniquement les États","Les firmes transnationales et leurs sous-traitants","Les ONG","Les agriculteurs"]'::jsonb, 1, 'Les FTN répartissent leurs sites dans le monde ; les États les attirent par des aides ou des zones franches.', 10),
    ('b810fb01-8ef9-56fe-88c2-4e90f8af042b'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Les services ne font pas partie des espaces productifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les services (finance, conseil, recherche, tourisme) créent aussi des richesses : le programme demande de ne pas les oublier.', 11),
    ('a491c3b1-bd85-5ee4-8d37-45cfd365f514'::uuid, '15f934a9-c4e7-55ce-9015-8c7460ad5100'::uuid, 'Comment s’appelle la façade maritime européenne de la mer du Nord ?', 'mcq', '["La dorsale","La Mégalopolis","La Northern Range","La Sun Belt"]'::jsonb, 2, 'Du Havre à Hambourg, elle concentre les plus grands ports européens.', 12),
    ('0fa9b7b4-91ca-5264-8ee1-f8633fb76a89'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Quel est le principal concurrent d’Airbus ?', 'mcq', '["Comac","Boeing","Embraer","Dassault"]'::jsonb, 1, 'Airbus et Boeing se partagent l’essentiel du marché mondial des avions de ligne.', 1),
    ('46aa54ef-fbde-52c5-9b0f-0cf30f6a89fc'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Dans quelles villes se trouvent les grandes chaînes d’assemblage d’Airbus en Europe ?', 'mcq', '["Paris et Berlin","Londres et Madrid","Toulouse et Hambourg","Lyon et Munich"]'::jsonb, 2, 'Toulouse assemble notamment les A350, Hambourg une grande partie des A320 et A321.', 2),
    ('06a2d664-1b71-535a-ad3c-420d1817a255'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Où sont fabriquées les ailes des avions Airbus ?', 'mcq', '["À Broughton, au Royaume-Uni","À Toulouse","À Hambourg","À Getafe"]'::jsonb, 0, 'Le site gallois de Broughton est spécialisé dans les ailes.', 3),
    ('43059e23-23da-58a6-a4bb-ff812007134c'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Comment s’appellent les avions-cargos géants qui transportent les tronçons d’Airbus ?', 'mcq', '["Les Concorde","Les Rafale","Les Transall","Les Beluga"]'::jsonb, 3, 'Leur forme de baleine permet de transporter des morceaux entiers de fuselage.', 4),
    ('69558f8c-6fd0-58a7-9d5f-fc942f80f052'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Pourquoi dit-on que la production d’Airbus est organisée en réseau ?', 'mcq', '["Parce qu’elle ne se fait que dans une usine","Parce que plusieurs sites spécialisés dans plusieurs pays fabriquent les pièces avant l’assemblage","Parce qu’Airbus vend sur Internet","Parce qu’Airbus n’a pas de siège"]'::jsonb, 1, 'Chaque site a sa spécialité, et les pièces circulent entre eux.', 5),
    ('3deecded-716f-57b8-99ad-b69e6200fd5c'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Le dynamisme de Toulouse est en partie lié à Airbus et à ses sous-traitants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Emplois directs et indirects, ingénieurs, écoles : Airbus nourrit la croissance de la métropole toulousaine.', 6),
    ('65be5599-48d6-5efa-919d-abef1a1ada9b'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Qu’est-ce qu’un sous-traitant ?', 'mcq', '["Une entreprise qui fabrique pour une autre une partie de sa production","Un client d’Airbus","Un syndicat","Une agence de l’État"]'::jsonb, 0, 'Safran ou Latécoère fabriquent des pièces et équipements pour Airbus.', 7),
    ('eec1f802-0d2b-5bbd-af3c-aefa7867a13a'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Comment s’appelle le pôle de compétitivité aéronautique du Sud-Ouest ?', 'mcq', '["Silicon Valley","Aerospace Valley","Vallée de la chimie","Sophia Antipolis"]'::jsonb, 1, 'Il associe entreprises, écoles et laboratoires en Occitanie et Nouvelle-Aquitaine.', 8),
    ('f5ce1330-d2ef-5618-a2d3-89c0f2d1b04a'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Pourquoi Airbus a-t-il ouvert des chaînes d’assemblage en Chine et aux États-Unis ?', 'mcq', '["Parce que l’Europe interdit l’aéronautique","Pour fuir la concurrence","Pour se rapprocher de ses clients et de ses marchés","Pour fermer Toulouse"]'::jsonb, 2, 'Tianjin et Mobile lui ouvrent l’accès aux marchés chinois et américain.', 9),
    ('e3970a44-2767-5166-9ae6-9af9a71ebf4a'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Quelle agence organise la politique spatiale européenne ?', 'mcq', '["L’ESA","La NASA","L’OTAN","L’ONU"]'::jsonb, 0, 'L’Agence spatiale européenne coordonne les programmes, dont les lanceurs Ariane.', 10),
    ('b55d730f-1e59-5af5-a491-c7368cb14060'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Airbus est une entreprise uniquement française.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Né d’une coopération franco-allemande rejointe par l’Espagne et le Royaume-Uni, Airbus est un groupe européen.', 11),
    ('01f3d854-6260-5d71-9162-ac68f8ca239b'::uuid, 'a795a392-304d-543c-84dd-d9607b8d5026'::uuid, 'Quel constructeur chinois concurrence désormais Airbus et Boeing ?', 'mcq', '["Huawei","BYD","Alibaba","Comac"]'::jsonb, 3, 'Son avion C919 vise d’abord le marché intérieur chinois.', 12),
    ('8305ba51-7b59-5b1c-8ed3-039ead627aa1'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Dans quel pays se trouve Rotterdam ?', 'mcq', '["En Belgique","En Allemagne","Aux Pays-Bas","Au Danemark"]'::jsonb, 2, 'Rotterdam est aux Pays-Bas, à l’embouchure du Rhin et de la Meuse.', 1),
    ('3382fd56-a604-5aaf-af35-0bf0bec57c77'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Quel est le rang de Rotterdam parmi les ports européens ?', 'mcq', '["Premier","Cinquième","Dixième","Deuxième derrière Marseille"]'::jsonb, 0, 'Avec environ 440 millions de tonnes par an, il domine les ports européens.', 2),
    ('7c9f1f61-5d4f-5226-8158-8785bc00c526'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Qu’est-ce que l’hinterland d’un port ?', 'mcq', '["Son avant-port","Sa zone d’influence à l’intérieur des terres","Sa flotte de navires","Son quartier historique"]'::jsonb, 1, 'L’hinterland de Rotterdam s’étend jusqu’à la Ruhr et la Suisse.', 3),
    ('b3fc9aed-9ffd-5234-ab4c-1fff3fcc9595'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Par quel fleuve les barges relient-elles Rotterdam à l’Allemagne ?', 'mcq', '["La Seine","Le Danube","L’Elbe","Le Rhin"]'::jsonb, 3, 'Le Rhin relie Rotterdam à Duisbourg, premier port fluvial d’Europe, et à la Ruhr.', 4),
    ('4ecdb98c-25b6-571a-9f60-b01c50876516'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Dans quel sens le port de Rotterdam s’est-il déplacé ?', 'mcq', '["Vers l’aval, vers la mer","Vers l’amont, vers l’intérieur","Il n’a jamais bougé","Vers le sud, en Belgique"]'::jsonb, 0, 'Du centre-ville au Botlek, à l’Europoort puis à Maasvlakte : il suit les navires de plus en plus grands.', 5),
    ('a6349db3-2957-5418-bb4e-8cf9e76c0bcf'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Maasvlakte 2 a été gagné sur la mer du Nord.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette extension ouverte en 2013 accueille des terminaux à conteneurs automatisés.', 6),
    ('a83fff9d-6536-572d-a900-87ce1400659b'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Que désigne le sigle ZIP ?', 'mcq', '["Une zone interdite portuaire","Une zone industrialo-portuaire","Une zone internationale de pêche","Une zone d’immeubles protégés"]'::jsonb, 1, 'Une ZIP associe port et industries qui transforment les matières importées.', 7),
    ('03b84cfe-306e-568b-b958-d9bfb12d4d9d'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Quelle industrie est très présente à Rotterdam ?', 'mcq', '["L’horlogerie","Le textile","La pétrochimie","L’aéronautique"]'::jsonb, 2, 'Raffineries et complexes chimiques transforment le pétrole importé.', 8),
    ('78e30f47-78df-567e-a6a1-d52ab3229e4d'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Qu’est-ce que la Betuweroute ?', 'mcq', '["Un pont","Une ligne ferroviaire de fret vers l’Allemagne","Un canal","Un oléoduc"]'::jsonb, 1, 'Ouverte en 2007, elle achemine les conteneurs vers l’hinterland allemand.', 9),
    ('7cc6f2ee-9178-5968-8554-b9971fb03b4b'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Que sont devenus les anciens bassins du centre de Rotterdam ?', 'mcq', '["Des terminaux pétroliers","Des zones agricoles","Des quartiers reconvertis (bureaux, logements)","Des bases militaires"]'::jsonb, 2, 'Kop van Zuid est un exemple de reconversion de friches portuaires.', 10),
    ('47bbd1bb-cd4e-5961-8c2d-a7a8e0ec610e'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Rotterdam n’a aucun concurrent en Europe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Anvers-Bruges et Hambourg lui disputent les trafics de la Northern Range.', 11),
    ('901dd20e-f1c8-5e9e-83ec-949dd23b463a'::uuid, 'd989d7c0-5127-507b-816c-cf1b57dae82c'::uuid, 'Quelle façade maritime Rotterdam domine-t-il ?', 'mcq', '["La Northern Range","La façade méditerranéenne","La façade atlantique","La façade baltique"]'::jsonb, 0, 'Du Havre à Hambourg, c’est la première façade maritime d’Europe.', 12),
    ('6bd5b107-2d21-5bf6-b449-20853b3d22af'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Qu’est-ce que la multifonctionnalité d’un espace rural ?', 'mcq', '["Le fait qu’il n’ait qu’une seule fonction","La coexistence de plusieurs fonctions : produire, habiter, se détendre, protéger","L’abandon de l’agriculture","La construction d’usines uniquement"]'::jsonb, 1, 'Un même village peut accueillir agriculteurs, navetteurs, touristes et une zone protégée.', 1),
    ('46c8eabb-209d-54f9-a368-31c3da55c114'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Qu’est-ce que la périurbanisation ?', 'mcq', '["L’extension de l’urbanisation autour des villes dans des communes rurales","L’exode rural","La reconstruction des centres-villes","La création de parcs naturels"]'::jsonb, 0, 'Des citadins s’installent à la campagne tout en travaillant en ville.', 2),
    ('89cd996d-4e7d-50fd-824d-54a9eff35b65'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Quelle part des actifs français sont agriculteurs ?', 'mcq', '["Environ 20 %","Environ 10 %","Environ 1,5 %","Environ 40 %"]'::jsonb, 2, 'Peu nombreux, ils exploitent pourtant plus de la moitié du territoire.', 3),
    ('f0a64bdf-f99c-5857-9bc8-e830e4253de0'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Quelle fonction correspond à l’installation d’éoliennes ou de méthaniseurs ?', 'mcq', '["La fonction de production d’énergie","La fonction résidentielle","La fonction touristique","La fonction de protection"]'::jsonb, 0, 'Les campagnes produisent de plus en plus d’énergies renouvelables.', 4),
    ('db11bce2-c819-5c1e-8885-b075bab92faa'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Les fonctions des espaces ruraux peuvent entrer en conflit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Par exemple, des néo-ruraux se plaignent des nuisances agricoles, ou des habitants refusent des éoliennes.', 5),
    ('9eec4a94-1ab6-594c-ac7a-5e6d97886bc3'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Qu’est-ce que la diagonale des faibles densités ?', 'mcq', '["Une autoroute","Une bande de territoires peu peuplés de la Meuse aux Landes","Une ligne TGV","Une frontière"]'::jsonb, 1, 'Ces espaces ruraux isolés connaissent vieillissement et recul des services.', 6),
    ('31be1b6e-cd63-5bcb-a07c-8e4594fc3f41'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Quelle région française est un grand espace rural agricole productif ?', 'mcq', '["La Beauce","La Côte d’Azur","La Lozère","Le Mercantour"]'::jsonb, 0, 'Ses grandes exploitations céréalières sont très mécanisées.', 7),
    ('69d24cb2-8082-56d1-a687-703140b9196c'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Que désigne la fragmentation d’un espace rural ?', 'mcq', '["Sa division en parcelles égales","Sa protection totale","Sa division en morceaux aux dynamiques opposées qui se côtoient","Son abandon complet"]'::jsonb, 2, 'Grandes exploitations exportatrices et petits paysans pauvres peuvent se côtoyer, par exemple au Brésil.', 8),
    ('ce3da303-67cd-55f3-9859-33f44fd17f16'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Dans les pays en développement, la population rurale est très faible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle reste nombreuse, notamment en Afrique subsaharienne et en Asie du Sud.', 9),
    ('93082044-9598-502f-a32d-80d43f38e369'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Quel phénomène renforce l’installation de citadins à la campagne depuis 2020 ?', 'mcq', '["La fermeture des routes","La hausse des prix à la campagne","La fin des voitures","Le télétravail"]'::jsonb, 3, 'Travailler à distance permet de vivre plus loin de son lieu de travail.', 10),
    ('70a6705a-505c-5422-a1d3-621136e136f5'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Qu’est-ce que l’exode rural ?', 'mcq', '["Le départ des habitants des campagnes vers les villes","L’arrivée de citadins à la campagne","Le tourisme vert","La création de villages"]'::jsonb, 0, 'Il a vidé les campagnes françaises aux XIXe et XXe siècles et reste fort dans les pays du Sud.', 11),
    ('d0a16dbb-0678-5a3c-ab92-2986c4e789a0'::uuid, 'a4e41284-8bbb-51d2-8c7f-059d1ecddc12'::uuid, 'Quel type d’espace rural connaît une croissance démographique ?', 'mcq', '["Le rural isolé","Le rural périurbain","Le rural de haute montagne","Aucun"]'::jsonb, 1, 'Sous l’influence des villes, les communes périurbaines gagnent des habitants.', 12),
    ('5a0cfa99-9b54-555e-ad27-44f99634c655'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Qu’est-ce qu’un espace périurbain ?', 'mcq', '["Le centre historique d’une ville","Un espace rural autour d’une ville dont beaucoup d’actifs travaillent dans le pôle urbain","Un espace montagnard","Un quartier d’affaires"]'::jsonb, 1, 'Il mêle paysages ruraux et habitants au mode de vie urbain.', 1),
    ('b6f6c4ed-3667-501d-8c85-735a049d8679'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Quel logement domine dans le périurbain ?', 'mcq', '["La maison individuelle en lotissement","Le grand ensemble","La tour de bureaux","L’immeuble haussmannien"]'::jsonb, 0, 'Le rêve pavillonnaire a porté la périurbanisation depuis les années 1970.', 2),
    ('02500842-656d-5db5-9f90-cc0cae12fe97'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Quel moyen de transport rend la périurbanisation possible ?', 'mcq', '["Le métro","Le bateau","L’automobile","L’avion"]'::jsonb, 2, 'La voiture permet de vivre loin de son travail, au prix d’une forte dépendance.', 3),
    ('cb2b04bb-c770-5162-a960-c373851c6966'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Quelle part des Français vit dans une couronne périurbaine ?', 'mcq', '["Environ 1 %","Environ 75 %","Environ 50 %","Environ un quart"]'::jsonb, 3, 'Environ un Français sur quatre vit dans ces couronnes.', 4),
    ('1e822a01-71e9-5eed-8185-1543adc351b0'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Pourquoi trouve-t-on des entrepôts dans le périurbain ?', 'mcq', '["Pour profiter de terrains moins chers près des autoroutes","Parce que c’est interdit en ville","Pour cacher les marchandises","Pour l’agriculture"]'::jsonb, 0, 'Les plateformes logistiques cherchent des grands terrains accessibles.', 5),
    ('b22cbcdf-1b20-5cbe-be12-62c251f30343'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'L’agriculture progresse fortement dans les espaces périurbains.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle recule sous l’effet des fonctions résidentielles, logistiques et commerciales.', 6),
    ('4da367f1-9941-5815-bfef-ef6983a10b83'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Que signifie l’objectif ZAN ?', 'mcq', '["Zone agricole nouvelle","Zéro artificialisation nette","Zone d’aménagement national","Zéro automobile en navette"]'::jsonb, 1, 'Fixé par la loi Climat et résilience de 2021 pour 2050.', 7),
    ('3e09b790-678e-53d0-b164-9e77d7c2375e'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Qu’est-ce que l’artificialisation des sols ?', 'mcq', '["La plantation de forêts","La transformation de terres naturelles ou agricoles en surfaces bâties ou revêtues","L’irrigation","Le drainage"]'::jsonb, 1, 'Elle détruit des terres fertiles et des habitats naturels.', 8),
    ('65fd5a5c-dc6f-50b1-b340-945528e41190'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'À La Réunion, où progresse la périurbanisation ?', 'mcq', '["Dans les Hauts et les pentes au-dessus des villes littorales","Au sommet du Piton des Neiges","Dans l’océan","Seulement dans le centre de Saint-Denis"]'::jsonb, 0, 'Le relief contraint l’urbanisation, qui gagne les pentes aux dépens de la canne à sucre.', 9),
    ('05d9cd74-62eb-52f4-af11-b790b0347fa7'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Quel mouvement social de 2018 est parti en partie des espaces périurbains ?', 'mcq', '["Mai 68","Nuit debout","Les gilets jaunes","La Manif pour tous"]'::jsonb, 2, 'La hausse du prix des carburants frappait des ménages très dépendants de la voiture.', 10),
    ('106930f5-e1bf-51fe-8ce7-99f5871a5c6c'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Dans les outre-mer, le relief et le littoral limitent l’espace disponible, ce qui renforce les conflits d’usage.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Agriculture, habitat et protection des mangroves se disputent peu de terres.', 11),
    ('3e76946f-14d0-524d-8dcb-e20ae62e7db3'::uuid, '587516b8-cc37-5956-bf37-dbdcde7c804a'::uuid, 'Comment l’Insee appelle-t-il aujourd’hui l’ensemble formé par un pôle et sa couronne ?', 'mcq', '["Une métropole","Une commune nouvelle","Une région","Une aire d’attraction d’une ville"]'::jsonb, 3, 'Ce zonage de 2020 mesure l’influence d’une ville par les déplacements domicile-travail.', 12),
    ('840947fc-f2ac-5dd4-bd47-a86956af1407'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Qu’est-ce que l’agro-tourisme ?', 'mcq', '["Un tourisme balnéaire","Un tourisme qui valorise l’agriculture et les produits du terroir","Un tourisme d’affaires","Un tourisme en ville"]'::jsonb, 1, 'Dormir à la ferme, visiter une exploitation, acheter des produits locaux en sont des formes.', 1),
    ('2027499c-1e72-53ef-93e3-f70a778fb80a'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Qu’est-ce qu’une ferme-auberge ?', 'mcq', '["Une ferme qui sert des repas avec ses propres produits","Un hôtel de luxe","Un supermarché","Une usine agroalimentaire"]'::jsonb, 0, 'Elles sont nombreuses dans les Vosges et en Alsace.', 2),
    ('965f4dcd-b019-5f40-9ad9-9d76770055f4'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Comment s’appelle le tourisme de visite des vignobles et des caves ?', 'mcq', '["L’écotourisme","Le tourisme vert","L’œnotourisme","Le tourisme de masse"]'::jsonb, 2, 'Il est une forme importante d’agro-tourisme en Bourgogne, en Champagne ou dans le Bordelais.', 3),
    ('f278e597-f75f-5325-a3c1-6db7f938f077'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Quelle politique européenne soutient le développement rural ?', 'mcq', '["La politique de cohésion urbaine","Schengen","L’euro","La politique agricole commune (PAC)"]'::jsonb, 3, 'Son deuxième pilier, financé par le FEADER, soutient le développement rural et les programmes LEADER.', 4),
    ('5337a468-4115-50ab-a6f6-ca5526d902c6'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'L’agro-tourisme représente des flux touristiques massifs à l’échelle nationale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les flux restent modestes, même si l’activité est en plein essor.', 5),
    ('d43fb897-2e12-5623-b7e9-7ed99420cd8d'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Quel avantage l’agro-tourisme apporte-t-il aux agriculteurs ?', 'mcq', '["Un complément de revenu","La fin de leur activité agricole","Une exonération de tout impôt","Des subventions automatiques"]'::jsonb, 0, 'En diversifiant leur activité, ils sécurisent leurs revenus.', 6),
    ('3fefd8e1-32ec-5e80-b780-50c17a911971'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Quel réseau regroupe des agriculteurs qui accueillent le public ?', 'mcq', '["Airbnb","Bienvenue à la ferme","Club Med","Center Parcs"]'::jsonb, 1, 'Porté par les chambres d’agriculture, il rassemble plus de 8 000 agriculteurs.', 7),
    ('cd281cd8-043a-5ad5-aa7b-e788a63beede'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Que peut-on visiter en Martinique dans le cadre de l’agro-tourisme ?', 'mcq', '["Des vignobles","Des mines de charbon","Des distilleries de rhum","Des stations de ski"]'::jsonb, 2, 'Le rhum agricole de Martinique bénéficie d’une AOC.', 8),
    ('6134b1fb-26c7-50a7-b09e-6d1cf1da142f'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Quelle limite de l’agro-tourisme est soulignée par le programme ?', 'mcq', '["L’absence totale de touristes","La question de la préservation du patrimoine rural","La pollution industrielle","La disparition des routes"]'::jsonb, 1, 'Une fréquentation accrue peut menacer le patrimoine bâti, paysager ou culturel.', 9),
    ('2906ec3f-486f-5ed4-a680-0e6eefb5ca7e'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'L’agro-tourisme contribue à diversifier les populations des espaces ruraux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Touristes saisonniers, travailleurs saisonniers et nouveaux habitants s’ajoutent aux populations permanentes.', 10),
    ('46a90669-9d8a-5aeb-a164-0dbc80558f64'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'À quelle échelle se situe l’agriculteur qui ouvre un gîte ?', 'mcq', '["Mondiale","Européenne","Nationale","Locale"]'::jsonb, 3, 'L’agro-tourisme est né de volontés individuelles locales, relayées par les politiques publiques.', 11),
    ('1456970c-7555-56dd-aefa-c614569eca6c'::uuid, 'f562adeb-c72e-5750-bc0e-5d2aee35eab1'::uuid, 'Que désigne le risque de « muséification » ?', 'mcq', '["La construction de musées","La transformation du patrimoine en décor figé pour touristes","La destruction des fermes","La vente des terres"]'::jsonb, 1, 'Le patrimoine risque de devenir une vitrine sans vie locale réelle.', 12),
    ('3de70e4b-4c44-58ad-b9ea-1cf534caf055'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Environ quelle part de la population chinoise vit en ville en 2024 ?', 'mcq', '["20 %","67 %","40 %","90 %"]'::jsonb, 1, 'La Chine est passée d’environ 20 % d’urbains en 1980 à environ deux tiers aujourd’hui.', 1),
    ('d57ed380-cafc-5a30-b88f-72a58efa2a85'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Qui sont les mingong ?', 'mcq', '["Des paysans qui refusent de partir","Des travailleurs migrants venus des campagnes vers les villes","Des chefs d’entreprise","Des touristes"]'::jsonb, 1, 'Ils ont fourni la main-d’œuvre de l’« atelier du monde ».', 2),
    ('22d80a27-605c-5642-b545-282654937f30'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'À quoi sert le hukou ?', 'mcq', '["C’est un passeport","C’est une carte bancaire","C’est un livret de résidence qui rattache chacun à son lieu d’origine","C’est un permis de conduire"]'::jsonb, 2, 'En ville, un migrant sans hukou urbain a un accès limité aux services publics.', 3),
    ('6b9cc4b9-7c2f-5868-a95d-e45aa2709be1'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Qui lance l’ouverture économique de la Chine à partir de 1978 ?', 'mcq', '["Mao Zedong","Xi Jinping","Sun Yat-sen","Deng Xiaoping"]'::jsonb, 3, 'Ses réformes ouvrent la Chine aux capitaux étrangers et au marché.', 4),
    ('cc509cd9-2a42-5f46-92ae-cddc22c00db4'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Quelle ville était un bourg de pêcheurs avant de devenir une zone économique spéciale en 1980 ?', 'mcq', '["Shenzhen","Pékin","Wuhan","Lhassa"]'::jsonb, 0, 'Voisine de Hong Kong, Shenzhen compte aujourd’hui plus de 17 millions d’habitants.', 5),
    ('d0887cfd-2963-5754-9f27-a10685d44d6b'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Quel est le premier port à conteneurs du monde ?', 'mcq', '["Rotterdam","Singapour","Shanghai","Los Angeles"]'::jsonb, 2, 'Shanghai, à l’embouchure du Yangzi, domine le classement mondial.', 6),
    ('8793d8d4-aa2d-5915-abb6-64a5fa094ad2'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Le littoral chinois concentre l’essentiel des industries et des exportations.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la littoralisation : la façade Est est tournée vers la mondialisation.', 7),
    ('676bff79-c338-5566-b476-433ec4a53714'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Quelle politique vise à rattraper le retard de l’intérieur ?', 'mcq', '["Les zones économiques spéciales","Le développement de l’Ouest","Le Grand Bond en avant","La politique de l’enfant unique"]'::jsonb, 1, 'Lancée en 2000, elle finance infrastructures et industries dans l’intérieur.', 8),
    ('c637f168-de06-5ddc-bc08-4a70504951e7'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Quelle part des actifs chinois travaille encore dans l’agriculture ?', 'mcq', '["Environ 2 %","Environ 80 %","Environ 60 %","Environ 22 %"]'::jsonb, 3, 'Elle a fortement reculé, mais reste bien plus élevée qu’en Europe.', 9),
    ('b71a41d9-6027-5b0c-9ee1-3b4870791483'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Quelle région urbaine rassemble Canton, Shenzhen et Hong Kong ?', 'mcq', '["Le delta de la rivière des Perles","Le delta du Yangzi","La région Pékin-Tianjin","Le Sichuan"]'::jsonb, 0, 'C’est l’une des plus grandes concentrations urbaines et industrielles du monde.', 10),
    ('e7c34987-6452-52e5-81f5-7d50202defe0'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Les campagnes chinoises gagnent des jeunes grâce à l’exode urbain.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : les jeunes partent en ville, les campagnes vieillissent.', 11),
    ('66a3a258-7918-5711-bbd6-18413090634e'::uuid, '22a95129-b55a-5a76-91f0-ef5bea3034f4'::uuid, 'Quel grand ouvrage hydraulique a été construit sur le Yangzi ?', 'mcq', '["Le barrage d’Assouan","Le canal de Suez","Le barrage des Trois-Gorges","Le barrage Hoover"]'::jsonb, 2, 'Achevé en 2006-2012, c’est la plus grande centrale hydroélectrique du monde.', 12),
    ('5e810837-26a1-5b8b-a684-2346bed2b81c'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Quel élément caractérise un régime totalitaire ?', 'mcq', '["Plusieurs partis en concurrence","Un parti unique qui veut contrôler toute la société","Une presse libre","Des élections libres"]'::jsonb, 1, 'Le totalitarisme veut encadrer tous les individus par l’idéologie, la propagande et la terreur.', 1),
    ('1908d759-3cf4-5cdc-9634-72bfad430f3f'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Quand Hitler devient-il chancelier ?', 'mcq', '["Le 30 janvier 1933","Le 1er septembre 1939","Le 9 novembre 1923","Le 8 mai 1945"]'::jsonb, 0, 'Il est nommé légalement par le président Hindenburg, puis détruit la démocratie en quelques mois.', 2),
    ('e52d7089-b03f-5530-9100-b8989d96ffb2'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Comment s’appelle le système des camps de travail forcé en URSS ?', 'mcq', '["Le Reich","Le kolkhoze","Le goulag","Le Komintern"]'::jsonb, 2, 'Des millions de personnes y ont été déportées, beaucoup y sont mortes.', 3),
    ('9b0ba2ea-eb54-5f32-967a-37b5666f5035'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Quelles lois de 1935 excluent les Juifs de la citoyenneté allemande ?', 'mcq', '["Les lois Ferry","Les lois de Vichy","Les lois de Weimar","Les lois de Nuremberg"]'::jsonb, 3, 'Elles interdisent aussi les mariages entre Juifs et non-Juifs.', 4),
    ('b8b6de50-32c6-5e86-98c9-a5a7464bb6ed'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Quel événement déclenche la Seconde Guerre mondiale en Europe ?', 'mcq', '["L’attaque de Pearl Harbor","L’invasion de la Pologne par l’Allemagne","Le débarquement en Normandie","La bataille de Stalingrad"]'::jsonb, 1, 'Le 1er septembre 1939, l’Allemagne envahit la Pologne ; la France et le Royaume-Uni déclarent la guerre le 3.', 5),
    ('3cba2a25-e9f7-5305-ba29-d216d75d0ebd'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Pourquoi les États-Unis entrent-ils en guerre en décembre 1941 ?', 'mcq', '["Parce que l’Allemagne envahit la France","Parce que le Japon attaque Pearl Harbor","Parce que l’URSS les attaque","Pour libérer la Pologne"]'::jsonb, 1, 'Le 7 décembre 1941, l’attaque japonaise sur leur base du Pacifique les fait entrer dans le conflit.', 6),
    ('e40e6e9d-3fb8-5867-9b54-100986fd3661'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Combien de Juifs d’Europe ont été assassinés pendant la Shoah ?', 'mcq', '["Environ 600 000","Environ 60 000","Environ 6 millions","Environ 60 millions"]'::jsonb, 2, 'Les nazis ont voulu exterminer tous les Juifs d’Europe, par les fusillades puis les centres de mise à mort.', 7),
    ('5332908e-387b-5a79-acea-c9e9f178b8e5'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Qu’est-ce que la collaboration ?', 'mcq', '["La politique de coopération du régime de Vichy avec l’Allemagne nazie","L’alliance entre la France libre et le Royaume-Uni","La Résistance intérieure","La reconstruction après 1945"]'::jsonb, 0, 'Vichy collabore sur le plan économique, policier (rafles) et politique.', 8),
    ('9d945e42-f285-5139-9d87-96de0c59c9e8'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Qui unifie la Résistance intérieure au sein du Conseil national de la Résistance ?', 'mcq', '["Philippe Pétain","Pierre Laval","Jean Moulin","Léon Blum"]'::jsonb, 2, 'Envoyé par de Gaulle, Jean Moulin réunit le CNR en mai 1943 ; il est arrêté en juin et meurt sous la torture.', 9),
    ('9b6d726c-ddb2-5270-a051-00130e08f64c'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Le génocide des Tsiganes a aussi été perpétré par les nazis.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les Tsiganes (Roms et Sinti) ont été persécutés, internés et exterminés en raison de leur origine.', 10),
    ('1644aaf5-7820-5b90-a688-4f9f24dd11c1'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Quelle organisation internationale est créée en 1945 pour garantir la paix ?', 'mcq', '["La SDN","L’OTAN","L’Union européenne","L’ONU"]'::jsonb, 3, 'Sa charte est signée à San Francisco en juin 1945.', 11),
    ('c1f158e1-b655-5e7a-88a4-0da218fbe546'::uuid, 'ec089617-34cc-5d6e-a48f-0f8b24703b2f'::uuid, 'Le procès de Nuremberg juge les dirigeants japonais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nuremberg juge les dirigeants nazis (1945-1946) ; les dirigeants japonais sont jugés à Tokyo.', 12),
    ('9562c606-45ad-548f-87e6-85263760ba84'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Comment s’appelle l’attaque allemande contre l’URSS le 22 juin 1941 ?', 'mcq', '["L’opération Overlord","L’opération Barbarossa","L’opération Torch","Le Blitz"]'::jsonb, 1, 'Elle ouvre sur le front de l’Est une guerre d’anéantissement.', 1),
    ('ad0d4614-b77e-593b-8ba3-65f18e86b2c2'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Pourquoi parle-t-on de « guerre d’anéantissement » à l’Est ?', 'mcq', '["Parce que la guerre y est courte","Parce qu’elle vise à détruire des peuples et une idéologie, pas seulement une armée","Parce qu’on n’y combat pas","Parce qu’elle se déroule en mer"]'::jsonb, 1, 'Pour Hitler, il s’agit d’éliminer le « judéo-bolchevisme » et de coloniser l’espace slave.', 2),
    ('9e2ac98f-b021-57b6-b1a8-1cdf90fbc084'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Qui sont les Einsatzgruppen ?', 'mcq', '["Des unités mobiles de tuerie qui fusillent les Juifs derrière le front","Des résistants polonais","Des soldats soviétiques","Des diplomates allemands"]'::jsonb, 0, 'Ces unités de la SS et de la police commettent la « Shoah par balles ».', 3),
    ('cab36c9b-4a05-56c8-8f93-44e51e40de67'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Quel massacre fait plus de 33 000 victimes près de Kiev en septembre 1941 ?', 'mcq', '["Oradour-sur-Glane","Katyn","Nankin","Babi Yar"]'::jsonb, 3, 'En deux jours, les 29 et 30 septembre 1941, les Juifs de Kiev sont fusillés dans un ravin.', 4),
    ('2b742e59-6e15-58a9-8600-a7391200f13b'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Que décide la conférence de Wannsee en janvier 1942 ?', 'mcq', '["L’invasion de l’URSS","La coordination administrative de la « solution finale »","La paix avec les Alliés","La création des ghettos"]'::jsonb, 1, 'Des hauts responsables nazis y organisent la déportation des Juifs de toute l’Europe.', 5),
    ('35976154-e798-5869-8e95-b4d0f490a1b4'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Quel est le plus grand centre de mise à mort nazi ?', 'mcq', '["Dachau","Buchenwald","Auschwitz-Birkenau","Drancy"]'::jsonb, 2, 'Environ 1,1 million de personnes y sont assassinées, en grande majorité des Juifs.', 6),
    ('d5a0ed39-9ec9-5dbc-9635-2e5a47ca66dd'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Les ghettos ont été créés avant les centres de mise à mort.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dès 1939-1940, les Juifs de Pologne sont enfermés dans des ghettos, où la faim et les épidémies tuent en masse.', 7),
    ('9687cbde-7784-5a2a-8777-c88ffded0a3d'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Pourquoi les nazis passent-ils des fusillades aux chambres à gaz ?', 'mcq', '["Par manque de soldats à l’Est","Parce que les Alliés l’exigent","Pour tuer davantage et plus vite, en éloignant les tueurs des victimes","Pour cacher la guerre"]'::jsonb, 2, 'Les chambres à gaz industrialisent le meurtre de masse.', 8),
    ('60a121e4-bd0b-52c5-83d9-4f700f3bab80'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Combien de prisonniers de guerre soviétiques meurent en captivité allemande ?', 'mcq', '["Environ 3 millions","Environ 30 000","Environ 300","Aucun"]'::jsonb, 0, 'Affamés et maltraités, ils sont victimes de la dimension raciale de la guerre.', 9),
    ('fe752635-bd38-58a9-b81a-c0d2264a9c8c'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Quand le ghetto de Varsovie se soulève-t-il ?', 'mcq', '["En 1939","En avril 1943","En 1945","En juin 1941"]'::jsonb, 1, 'Les combattants juifs résistent près d’un mois à l’armée allemande.', 10),
    ('84fe24cd-ddd2-55a2-a0fa-4bdb4b3f2932'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Le 27 janvier est la journée internationale de la mémoire de l’Holocauste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la date de la libération d’Auschwitz par l’Armée rouge en 1945.', 11),
    ('534b19aa-3006-5ec1-8081-76a3b959c59f'::uuid, '00d200ff-6527-5c27-9105-a8274b35b2cd'::uuid, 'Quel pays a compté le plus de victimes juives de la Shoah ?', 'mcq', '["La France","L’Allemagne","L’Italie","La Pologne"]'::jsonb, 3, 'Environ 3 millions de Juifs polonais ont été assassinés, soit environ la moitié des victimes.', 12),
    ('29bc8372-c04f-549b-a68d-1cf483c8c6b0'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'D’où de Gaulle lance-t-il son appel le 18 juin 1940 ?', 'mcq', '["D’Alger","De Londres, sur la BBC","De Paris","De Vichy"]'::jsonb, 1, 'Il s’exprime à la radio britannique, avec l’accord de Churchill.', 1),
    ('97f44d5f-12db-5f5a-8cad-05fd4dabb7f8'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Que dit l’appel du 18 juin ?', 'mcq', '["Qu’il faut signer l’armistice","Que la guerre est perdue","Que la guerre est mondiale et qu’il faut continuer le combat","Qu’il faut collaborer avec l’Allemagne"]'::jsonb, 2, 'Il rappelle que la France a un empire et des alliés, et appelle à poursuivre la lutte.', 2),
    ('08b5a2ee-4152-5e83-9d7b-67ca75c4335f'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Quel territoire se rallie le premier à la France libre, en août 1940 ?', 'mcq', '["Le Tchad","L’Algérie","Le Maroc","L’Indochine"]'::jsonb, 0, 'Le gouverneur Félix Éboué rallie le Tchad, puis l’AEF suit.', 3),
    ('93d27185-a282-5093-85d4-27c307e98eb6'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Quelle bataille de 1942 montre la valeur militaire des Forces françaises libres ?', 'mcq', '["Stalingrad","Verdun","Dunkerque","Bir Hakeim"]'::jsonb, 3, 'Les troupes de Kœnig résistent deux semaines à l’Afrikakorps de Rommel en Libye.', 4),
    ('2417a365-1611-5658-8628-a726c33d7f91'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Quelle est la mission de Jean Moulin ?', 'mcq', '["Diriger l’armée à Londres","Unifier les mouvements de la Résistance intérieure","Négocier avec Vichy","Commander la 2e DB"]'::jsonb, 1, 'Il crée le Conseil national de la Résistance, réuni pour la première fois le 27 mai 1943.', 5),
    ('50cdf093-d6ed-52cb-b44d-0c1a81cbab6e'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Quel chef allié se méfie de de Gaulle ?', 'mcq', '["Churchill","Staline","Roosevelt","Eisenhower"]'::jsonb, 2, 'Le président américain préfère d’abord traiter avec Darlan puis Giraud.', 6),
    ('1d842574-256a-5e75-8400-594a77707946'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Le régime de Vichy a condamné de Gaulle à mort par contumace.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Pour Vichy, il est un rebelle ; pour de Gaulle, c’est Vichy qui est illégitime.', 7),
    ('649356b2-23e0-58b4-b8bc-00a5c56a44c9'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Que prévoit le programme du CNR de mars 1944 ?', 'mcq', '["Le retour de la monarchie","Des réformes sociales comme la Sécurité sociale","L’alliance avec l’Allemagne","L’indépendance des colonies"]'::jsonb, 1, 'Ce programme inspire les grandes réformes de la Libération.', 8),
    ('4b6274e7-baca-5cfb-b36d-6990f951f773'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Quel serment le général Leclerc prononce-t-il à Koufra en 1941 ?', 'mcq', '["Libérer Paris avant Noël","Ne jamais revenir en France","Ne déposer les armes que quand le drapeau flottera sur Strasbourg","Prendre Berlin"]'::jsonb, 2, 'Il tiendra parole : la 2e DB libère Strasbourg en novembre 1944.', 9),
    ('40af26e3-63cc-5064-b23e-f1462bc141f6'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Comment s’appelle le gouvernement de la France libre formé en juin 1944 ?', 'mcq', '["Le GPRF","Le Directoire","Le Front populaire","Le Consulat"]'::jsonb, 0, 'Le Gouvernement provisoire de la République française succède au CFLN d’Alger.', 10),
    ('272e3517-a552-53ae-9cf2-9a464db0bbb0'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Quand Paris est-il libéré ?', 'mcq', '["Le 6 juin 1944","Le 8 mai 1945","Le 11 novembre 1944","Le 25 août 1944"]'::jsonb, 3, 'La 2e DB de Leclerc et les FFI libèrent la capitale ; de Gaulle y défile le lendemain.', 11),
    ('d71be543-14de-5b67-8acd-d25032f8631c'::uuid, '2280778e-eccd-50ff-9bee-c6c1fceb6954'::uuid, 'Grâce à l’action de la France libre, la France obtient un siège permanent au Conseil de sécurité de l’ONU.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La France est comptée parmi les vainqueurs, avec une zone d’occupation en Allemagne.', 12),
    ('6869073a-be4d-505c-9012-9763f9a0ddf2'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Quelles puissances s’opposent pendant la guerre froide ?', 'mcq', '["La France et l’Allemagne","Les États-Unis et l’URSS","La Chine et le Japon","Le Royaume-Uni et l’Inde"]'::jsonb, 1, 'Les deux superpuissances s’affrontent sans guerre directe, sous la menace nucléaire.', 1),
    ('1e7b8ced-66ee-5e13-b6ef-98c84ec036f6'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Pourquoi parle-t-on de guerre « froide » ?', 'mcq', '["Parce qu’elle se déroule en Arctique","Parce qu’elle dure un hiver","Parce que les deux Grands ne s’affrontent pas directement","Parce qu’il n’y a aucun mort"]'::jsonb, 2, 'La dissuasion nucléaire empêche le conflit direct ; les affrontements sont indirects.', 2),
    ('4a61bdb7-02a7-5afd-9668-312c5676abd0'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Quelle alliance militaire les États-Unis créent-ils en 1949 ?', 'mcq', '["Le pacte de Varsovie","L’ONU","Le CAEM","L’OTAN"]'::jsonb, 3, 'L’Organisation du traité de l’Atlantique Nord unit les États-Unis et les pays d’Europe de l’Ouest.', 3),
    ('20c92bab-1745-52ab-8091-3f6b80d7eea2'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Quelle crise de 1962 met le monde au bord de la guerre nucléaire ?', 'mcq', '["La crise des missiles de Cuba","Le blocus de Berlin","La guerre de Corée","La crise de Suez"]'::jsonb, 0, 'L’URSS installe des missiles à Cuba ; après treize jours de tension, elle les retire.', 4),
    ('81137932-49f6-5fd0-b705-6ed36d69d6fe'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Quand le mur de Berlin tombe-t-il ?', 'mcq', '["Le 13 août 1961","Le 9 novembre 1989","Le 25 décembre 1991","En 1945"]'::jsonb, 1, 'Sa chute annonce la fin des démocraties populaires et la réunification allemande (1990).', 5),
    ('e8085392-d7fe-5a8b-b28f-9053e746bee0'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Quel pays devient indépendant en 1947 ?', 'mcq', '["L’Algérie","Le Sénégal","L’Inde","Le Vietnam"]'::jsonb, 2, 'L’indépendance de l’Inde, avec la partition et la création du Pakistan, ouvre la décolonisation.', 6),
    ('7257a294-fcbd-5a6c-a73c-737a64573370'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Que réunit la conférence de Bandung en 1955 ?', 'mcq', '["Les pays d’Asie et d’Afrique décolonisés ou en lutte","Les pays de l’OTAN","Les pays communistes","Les fondateurs de l’Europe"]'::jsonb, 0, 'Elle marque l’entrée du tiers monde sur la scène internationale.', 7),
    ('3a9557f8-c8e7-5117-a004-6c9b05e6bae7'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Les non-alignés refusent de choisir entre les deux blocs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mouvement, fondé à Belgrade en 1961, veut une troisième voie.', 8),
    ('668162bd-06d1-5e1a-9ff4-c77f862b3197'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Quel traité fonde l’Union européenne en 1992 ?', 'mcq', '["Le traité de Rome","Le traité de Lisbonne","Le traité de Versailles","Le traité de Maastricht"]'::jsonb, 3, 'Il crée l’UE et prévoit la monnaie unique.', 9),
    ('f1759ba5-f96c-5ae1-99ea-db55fcfb798f'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Combien d’États membres compte l’Union européenne depuis 2020 ?', 'mcq', '["6","15","27","28"]'::jsonb, 2, 'Elle est passée de 28 à 27 membres avec la sortie du Royaume-Uni.', 10),
    ('baddf891-10a5-5f3e-bdc8-b271fabf8142'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Après 1991, les nouvelles formes de conflits incluent le terrorisme et les guerres civiles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le génocide des Tutsi au Rwanda (1994) ou les attentats du 11 septembre 2001 en sont des exemples.', 11),
    ('a495bf74-847d-5dca-aa85-4e83dafaf111'::uuid, '05d24671-1876-5db5-aaab-8a67fcb02c3c'::uuid, 'Quel pays s’affirme comme deuxième économie mondiale au XXIe siècle ?', 'mcq', '["La Russie","La Chine","Le Brésil","L’Allemagne"]'::jsonb, 1, 'La Chine est un pôle majeur du monde multipolaire, rival des États-Unis.', 12),
    ('55c6313e-e186-56db-886e-f5a8fea4c1c8'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Quel est le premier satellite artificiel de l’histoire ?', 'mcq', '["Explorer 1","Apollo 11","Spoutnik 1","Vostok 1"]'::jsonb, 2, 'Lancé par l’URSS le 4 octobre 1957, il provoque un choc aux États-Unis.', 1),
    ('69c4a246-ddec-5d86-88e6-d63ec368f9c1'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Qui est le premier homme dans l’espace ?', 'mcq', '["Youri Gagarine","Neil Armstrong","Alexeï Leonov","John Glenn"]'::jsonb, 0, 'Le 12 avril 1961, il fait un tour de la Terre à bord de Vostok 1.', 2),
    ('7542e469-f068-54a5-af4b-69e2d656b324'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Pourquoi Spoutnik inquiète-t-il les Américains ?', 'mcq', '["Parce qu’il pollue l’espace","Parce qu’il montre que l’URSS peut aussi lancer des missiles jusqu’aux États-Unis","Parce qu’il espionne la Lune","Parce qu’il est américain"]'::jsonb, 1, 'La fusée qui lance un satellite peut porter une bombe nucléaire.', 3),
    ('dc34e23a-92d0-51cf-b482-512232ffad8d'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Quelle agence les États-Unis créent-ils en 1958 ?', 'mcq', '["La CIA","L’ESA","Le CNES","La NASA"]'::jsonb, 3, 'La NASA organise le programme spatial civil américain.', 4),
    ('36e27834-8d30-5e63-8452-5e790cbcf4c2'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Quel président américain fixe l’objectif d’aller sur la Lune ?', 'mcq', '["Kennedy","Nixon","Reagan","Eisenhower"]'::jsonb, 0, 'Le 25 mai 1961, il promet un homme sur la Lune avant la fin de la décennie.', 5),
    ('2557d4ca-cac3-52d4-bc97-7262d4e834fa'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Qui est la première femme dans l’espace, en 1963 ?', 'mcq', '["Sally Ride","Valentina Terechkova","Claudie Haigneré","Svetlana Savitskaïa"]'::jsonb, 1, 'Cette Soviétique vole à bord de Vostok 6 : nouvelle victoire symbolique de l’URSS.', 6),
    ('33b37b56-ae61-58e8-8cba-f1d02c6f23ca'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Neil Armstrong et Buzz Aldrin marchent sur la Lune en juillet 1969.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La mission Apollo 11 est une victoire symbolique majeure des États-Unis.', 7),
    ('8357d5ea-9ac7-5772-b9e4-c51aa45a9c03'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Que symbolise la mission Apollo-Soyouz de 1975 ?', 'mcq', '["Le début de la guerre froide","La course à la Lune","La coopération pendant la détente","La fin de l’URSS"]'::jsonb, 2, 'Américains et Soviétiques s’arriment et se serrent la main en orbite.', 8),
    ('44216984-237f-5b64-af84-85fca3098c95'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Qu’est-ce que l’Initiative de défense stratégique de 1983 ?', 'mcq', '["Un projet de bouclier antimissile dans l’espace","Une station spatiale commune","Un traité de désarmement","Une mission vers Mars"]'::jsonb, 0, 'Reagan veut détruire les missiles soviétiques en vol grâce à des satellites et des lasers.', 9),
    ('c06315a5-6c1a-5bf2-8b39-2493db999610'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Pourquoi surnomme-t-on l’IDS « guerre des étoiles » ?', 'mcq', '["Parce qu’elle vise les étoiles","Par référence au film Star Wars","Parce qu’elle a lieu la nuit","Parce qu’elle est soviétique"]'::jsonb, 1, 'La presse reprend le titre du film de George Lucas sorti en 1977.', 10),
    ('a6ce0f97-9646-5315-99de-0bb228b3ec87'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Le traité de l’espace de 1967 autorise les armes nucléaires en orbite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il les interdit, ainsi que l’appropriation de la Lune par un État.', 11),
    ('754756b9-9436-522f-85cb-792255f33c71'::uuid, '78d79b28-2059-53e4-9802-e917e75cf5ae'::uuid, 'Quel effet la « guerre des étoiles » a-t-elle sur l’URSS ?', 'mcq', '["Elle la rend plus riche","Elle lui fait gagner la guerre froide","Elle n’a aucun effet","Elle la pousse dans une course aux armements qu’elle ne peut plus financer"]'::jsonb, 3, 'En crise économique, l’URSS ne peut suivre, ce qui contribue à la fin de la guerre froide.', 12),
    ('f8fa7938-f168-5078-a582-bb1a40b1aed7'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Quelle organisation terroriste commet les attentats du 11 septembre 2001 ?', 'mcq', '["L’État islamique","Le Hezbollah","Al-Qaïda","L’IRA"]'::jsonb, 2, 'Dirigée par Oussama Ben Laden, elle a préparé l’attaque depuis l’Afghanistan.', 1),
    ('d513e454-03bc-53dc-903d-c857ea2b33bb'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Combien de personnes sont tuées le 11 septembre 2001 ?', 'mcq', '["Environ 300","Près de 3 000","Environ 30 000","Environ 30"]'::jsonb, 1, 'On compte 2 977 victimes, de plus de 90 nationalités.', 2),
    ('2dc592a9-13f0-5013-86c0-91cb8be8147e'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Quels bâtiments sont frappés par les avions ?', 'mcq', '["Le World Trade Center et le Pentagone","La Maison-Blanche et le Capitole","La statue de la Liberté et l’Empire State Building","Le siège de l’ONU"]'::jsonb, 0, 'Le quatrième avion, qui visait sans doute Washington, s’écrase en Pennsylvanie.', 3),
    ('080a7c2e-e706-5789-8b71-a4f7e9dbb4bb'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Pourquoi le vol United 93 n’atteint-il pas sa cible ?', 'mcq', '["Il est abattu par l’armée","Il tombe en panne","Il fait demi-tour","Les passagers se révoltent contre les pirates de l’air"]'::jsonb, 3, 'Informés par téléphone des autres attaques, ils tentent de reprendre l’avion, qui s’écrase en Pennsylvanie.', 4),
    ('8bbd872b-756e-576f-b0f0-d74b65e1f9b8'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Que symbolise le World Trade Center pour les terroristes ?', 'mcq', '["La puissance militaire","La puissance économique et financière des États-Unis","La religion chrétienne","Le pouvoir politique"]'::jsonb, 1, 'Les tours jumelles incarnaient le capitalisme américain et la mondialisation.', 5),
    ('f712876b-9b18-5527-bba3-72bc08531507'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Quel pays les États-Unis attaquent-ils dès octobre 2001 ?', 'mcq', '["L’Irak","L’Iran","L’Afghanistan","La Syrie"]'::jsonb, 2, 'Le régime des talibans y protégeait Al-Qaïda ; il est renversé.', 6),
    ('08584e83-5f85-59ad-9477-e92a50e53253'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'La guerre d’Irak de 2003 a été autorisée par l’ONU.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les États-Unis interviennent sans mandat de l’ONU ; la France s’y oppose.', 7),
    ('50c7c303-4cbd-5aed-8b06-94622da0dedc'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Qu’est-ce que le terrorisme ?', 'mcq', '["L’usage de la violence contre des civils pour créer la peur et atteindre des buts politiques","Une guerre entre deux armées","Une révolution pacifique","Un coup d’État militaire"]'::jsonb, 0, 'Frapper des civils vise à terroriser une société entière.', 8),
    ('186deffc-9479-5131-9001-9b7ca35260d7'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Quand Oussama Ben Laden est-il tué ?', 'mcq', '["En 2001","En 2003","En 2021","En 2011"]'::jsonb, 3, 'Un commando américain le tue au Pakistan le 2 mai 2011.', 9),
    ('c76d8655-33fb-5d4a-9c7f-23719d08dc33'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Quelle loi américaine de 2001 renforce la surveillance ?', 'mcq', '["Le Patriot Act","Le New Deal","Le Civil Rights Act","Le plan Marshall"]'::jsonb, 0, 'Elle étend les pouvoirs des services de renseignement, au prix de certaines libertés.', 10),
    ('a67f456f-7551-5857-85f5-6b784aa3a947'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Les talibans ont repris le pouvoir en Afghanistan en 2021.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après vingt ans de présence, les troupes américaines se retirent en août 2021.', 11),
    ('e1ed04fa-4936-501d-b460-458b77fd0049'::uuid, '613c254e-3539-5372-9580-6426b1957ec9'::uuid, 'Qu’y a-t-il aujourd’hui à l’emplacement des tours jumelles ?', 'mcq', '["Un parc d’attractions","Un aéroport","Le mémorial du 11-Septembre et le One World Trade Center","Rien, le site est abandonné"]'::jsonb, 2, 'Deux bassins marquent l’emplacement des tours, avec les noms des victimes.', 12),
    ('374c1ccb-b4e3-5d30-a663-5cb756993baf'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Quand les Françaises votent-elles pour la première fois ?', 'mcq', '["En 1936","En 1945","En 1958","En 1968"]'::jsonb, 1, 'Le droit est accordé par l’ordonnance d’avril 1944 ; premier vote aux municipales d’avril 1945.', 1),
    ('9acd642b-5d74-5636-a135-a0a1b23c2135'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Quelle grande institution sociale est créée en 1945 ?', 'mcq', '["La Sécurité sociale","Le RSA","Pôle emploi","Le SMIC"]'::jsonb, 0, 'Elle protège les travailleurs contre la maladie, les accidents et la vieillesse.', 2),
    ('fda5b47a-7f95-511d-b263-bd09480a2bff'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Pourquoi la IVe République est-elle jugée instable ?', 'mcq', '["Parce qu’elle n’a pas de parlement","Parce que le président a trop de pouvoir","Parce que les gouvernements tombent très souvent","Parce qu’elle dure 50 ans"]'::jsonb, 2, 'Plus de vingt gouvernements se succèdent en douze ans.', 3),
    ('f2e9fc24-be19-54cc-9700-96a9a6ebc2ed'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Quelle guerre fait tomber la IVe République en 1958 ?', 'mcq', '["La guerre d’Indochine","La guerre de Corée","La guerre du Golfe","La guerre d’Algérie"]'::jsonb, 3, 'La crise du 13 mai 1958 à Alger ramène de Gaulle au pouvoir.', 4),
    ('1174f603-4c63-5820-88e4-bf07aeba5553'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Depuis 1962, comment le président de la République est-il élu ?', 'mcq', '["Par le Parlement","Au suffrage universel direct","Par les maires","Par le Conseil constitutionnel"]'::jsonb, 1, 'La réforme de 1962, adoptée par référendum, renforce la légitimité du président.', 5),
    ('368048cc-a089-53df-a731-f79a35eeb6bb'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Qu’est-ce qu’une cohabitation ?', 'mcq', '["Un président et un Premier ministre de camps politiques opposés","Deux présidents en même temps","Une union entre deux partis","Un gouvernement sans ministres"]'::jsonb, 0, 'La première a lieu en 1986 : Mitterrand (gauche) et Chirac (droite).', 6),
    ('f42ea789-70fa-5e04-b0e3-6c09267b4434'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'La loi Veil de 1975 légalise l’interruption volontaire de grossesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Portée par la ministre Simone Veil, elle est une étape majeure des droits des femmes.', 7),
    ('3943095c-c8de-5921-80c1-190a065bff85'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Pourquoi la France a-t-elle fait appel à l’immigration pendant les Trente Glorieuses ?', 'mcq', '["Pour peupler les colonies","Pour le service militaire","Pour fournir de la main-d’œuvre à une économie en forte croissance","Pour des raisons touristiques"]'::jsonb, 2, 'Travailleurs italiens, espagnols, portugais et maghrébins construisent routes, logements et usines.', 8),
    ('088a67e9-65f5-5278-8ff5-16932a49b8ab'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Quelle loi de 2000 favorise l’égal accès des femmes et des hommes aux mandats électoraux ?', 'mcq', '["La loi sur le PACS","La loi sur la parité","La loi Neuwirth","La loi Veil"]'::jsonb, 1, 'Elle impose des listes paritaires à certaines élections.', 9),
    ('ead57e7d-5888-5308-9777-c1507c578c2c'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'En quelle année le mariage est-il ouvert aux couples de même sexe ?', 'mcq', '["1999","1975","2020","2013"]'::jsonb, 3, 'La loi de 2013 fait évoluer le Code civil ; le PACS existait depuis 1999.', 10),
    ('67840d20-a4ef-5180-8ff6-b30ed4f0d8ee'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Le quinquennat a remplacé le septennat présidentiel en 1981.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le quinquennat est adopté par référendum en 2000 et s’applique à partir de 2002.', 11),
    ('fb880351-5eff-5e26-a422-79f0dc1a54c7'::uuid, 'da4bacab-8ba4-53eb-8fc9-551c66a6ae0b'::uuid, 'Quel atout fait de la France une puissance d’influence mondiale ?', 'mcq', '["Son siège permanent au Conseil de sécurité de l’ONU","Sa population, la plus nombreuse d’Europe","Son empire colonial actuel","Sa monnaie nationale, le franc"]'::jsonb, 0, 'Elle est aussi puissance nucléaire et moteur de l’Union européenne.', 12),
    ('e7f48d0e-cba6-5e67-a41a-90c53c23d76b'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Quand commence la guerre d’Algérie ?', 'mcq', '["Le 8 mai 1945","Le 1er novembre 1954","Le 13 mai 1958","Le 18 mars 1962"]'::jsonb, 1, 'Le FLN lance une série d’attentats : c’est la « Toussaint rouge ».', 1),
    ('e7bf2518-4160-55e4-9f89-6ac27384971c'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Quel était le statut de l’Algérie avant 1962 ?', 'mcq', '["Un protectorat","Un État indépendant","Un ensemble de départements français","Un territoire ottoman"]'::jsonb, 2, 'Cette situation particulière explique que la France ait refusé longtemps de parler de guerre.', 2),
    ('557799cc-4ded-5df2-b37f-10a85fc096ff'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Quel mouvement lance l’insurrection de 1954 ?', 'mcq', '["Le FLN","L’OAS","Le MNA","Le GPRA"]'::jsonb, 0, 'Le Front de libération nationale et son armée, l’ALN, mènent la lutte armée.', 3),
    ('0905658e-83c9-5985-be0f-d559e4d6fa3c'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Qui sont les appelés du contingent ?', 'mcq', '["Des soldats professionnels","Des Algériens engagés dans l’armée française","Des militants du FLN","Des jeunes Français effectuant leur service militaire en Algérie"]'::jsonb, 3, 'Environ 1,5 million de jeunes hommes servent en Algérie.', 4),
    ('c9e8746f-9dd3-5966-84bd-ae10685ae372'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Quelle pratique de l’armée française pendant la bataille d’Alger est dénoncée ?', 'mcq', '["La torture","Le bombardement atomique","L’usage des gaz","La conscription des femmes"]'::jsonb, 0, 'Utilisée pour obtenir des renseignements, elle est dénoncée par des intellectuels et des journalistes.', 5),
    ('5f645d00-83fe-55fd-9076-ed4978b43b95'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Qui sont les harkis ?', 'mcq', '["Des colons européens","Des Algériens musulmans ayant servi comme supplétifs dans l’armée française","Des soldats de l’ALN","Des généraux putschistes"]'::jsonb, 1, 'Beaucoup sont massacrés après l’indépendance ; une partie est accueillie en France.', 6),
    ('bff9eacf-bc3d-5168-9b79-2ed827edc515'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Quelle organisation multiplie les attentats pour empêcher l’indépendance ?', 'mcq', '["Le FLN","L’ONU","L’OAS","Le GPRA"]'::jsonb, 2, 'L’Organisation de l’armée secrète frappe en Algérie et en métropole en 1961-1962.', 7),
    ('ce245a6d-d622-5386-90a6-f026be5d8158'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Les accords d’Évian sont signés le 18 mars 1962.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils prévoient un cessez-le-feu le 19 mars et un référendum d’autodétermination.', 8),
    ('fee14142-2034-52b2-891a-6cf7652ec69d'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Combien de pieds-noirs quittent l’Algérie en 1962 ?', 'mcq', '["Environ 8 000","Environ 80 000","Environ 8 millions","Environ 800 000"]'::jsonb, 3, 'Ces rapatriés arrivent souvent dans l’urgence en métropole.', 9),
    ('fad52ffd-dfd8-5d34-85c6-1041d6ccaef2'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Quelle conséquence politique la guerre a-t-elle en France ?', 'mcq', '["Le retour de la monarchie","La chute de la IVe République et la naissance de la Ve","La fin du suffrage universel","Le départ de la France de l’ONU"]'::jsonb, 1, 'La crise du 13 mai 1958 ramène de Gaulle, qui fait adopter une nouvelle constitution.', 10),
    ('f2de99ba-9227-58f3-a594-477eb8e64a1e'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'La France a officiellement reconnu l’expression « guerre d’Algérie » dès 1954.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut attendre une loi de 1999 ; on parlait avant d’« événements » ou d’« opérations de maintien de l’ordre ».', 11),
    ('5f8e2b9b-1e53-5882-9204-331cf4468bfc'::uuid, '864296c6-b44c-5df6-8381-a7bd2727d02d'::uuid, 'Quand l’Algérie devient-elle indépendante ?', 'mcq', '["Le 5 juillet 1962","Le 1er novembre 1954","Le 19 mars 1962","Le 13 mai 1958"]'::jsonb, 0, 'L’indépendance est proclamée après le référendum du 1er juillet 1962.', 12),
    ('6bfb5b4d-0281-5922-aa15-7d81c735d126'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Quand les femmes obtiennent-elles le droit de vote en France ?', 'mcq', '["En 1918","En 1944","En 1968","En 1975"]'::jsonb, 1, 'L’ordonnance du 21 avril 1944 leur donne le droit de vote et d’éligibilité.', 1),
    ('196f0720-b4eb-5e63-8ede-690784291953'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Que permet la réforme de 1965 aux femmes mariées ?', 'mcq', '["Voter","Divorcer","Travailler et ouvrir un compte bancaire sans l’autorisation de leur mari","Avorter"]'::jsonb, 2, 'Avant 1965, le mari pouvait s’opposer à ce que sa femme exerce un métier.', 2),
    ('c274afb1-00e7-5f88-81b7-4f6368a5bdc9'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Que remplace l’autorité parentale en 1970 ?', 'mcq', '["La puissance paternelle","Le mariage","Le divorce","Le PACS"]'::jsonb, 0, 'Désormais, les deux parents exercent ensemble l’autorité sur leurs enfants.', 3),
    ('64579db1-d7b3-51c8-926b-ec6bdbcfc31f'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Quelle loi autorise la contraception en 1967 ?', 'mcq', '["La loi Veil","La loi Roudy","La loi sur la parité","La loi Neuwirth"]'::jsonb, 3, 'Portée par le député Lucien Neuwirth, elle autorise notamment la pilule.', 4),
    ('bdcdb71f-2c3d-5e15-99f1-1b5730079bf9'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Qui défend la loi légalisant l’IVG en 1975 ?', 'mcq', '["Gisèle Halimi","Simone Veil","Édith Cresson","Simone de Beauvoir"]'::jsonb, 1, 'Ministre de la Santé, elle affronte une Assemblée presque entièrement masculine.', 5),
    ('d3433125-baae-5b22-8981-359280e87d8d'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Quelle avocate défend une jeune fille poursuivie pour avortement au procès de Bobigny ?', 'mcq', '["Gisèle Halimi","Simone Veil","Yvette Roudy","Olympe de Gouges"]'::jsonb, 0, 'Le procès de 1972 prépare la légalisation de l’IVG.', 6),
    ('3e8c226b-9271-5cc1-90b0-14c1ca522935'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'En 2024, la liberté de recourir à l’IVG a été inscrite dans la Constitution.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La France est devenue le premier pays à le faire.', 7),
    ('d614e80c-ff11-53e6-9c66-78d4b8952c22'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Quel est l’objectif de la loi sur la parité de 2000 ?', 'mcq', '["Interdire le divorce","Favoriser l’égal accès des femmes et des hommes aux mandats électoraux","Supprimer le vote des femmes","Créer l’autorité parentale"]'::jsonb, 1, 'Elle impose des listes paritaires à certaines élections.', 8),
    ('6f883e3d-6e0f-56d9-a5f7-0d1f52876f0d'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Qui est la première femme Première ministre en France ?', 'mcq', '["Élisabeth Borne","Simone Veil","Édith Cresson","Ségolène Royal"]'::jsonb, 2, 'Elle est nommée par François Mitterrand en 1991.', 9),
    ('cb687e3e-3431-56ad-83c1-3d86446fa8e5'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Que désigne le « plafond de verre » ?', 'mcq', '["Une loi sur le logement","Un type de bâtiment","Un salaire minimum","L’obstacle invisible qui freine l’accès des femmes aux postes de direction"]'::jsonb, 3, 'Les femmes restent minoritaires dans les directions d’entreprise.', 10),
    ('612e79f2-c8eb-5301-b041-e7bec67f349b'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Aujourd’hui, les salaires des femmes et des hommes sont parfaitement égaux en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un écart persiste, lié au temps partiel, aux métiers exercés et aux discriminations.', 11),
    ('f24039c2-f9bd-5d28-87fb-5618e26ba0b3'::uuid, 'f1bd5e1f-34d6-5d70-95ae-84703a3ff906'::uuid, 'Quelle loi de 1983 porte sur l’égalité professionnelle ?', 'mcq', '["La loi Roudy","La loi Neuwirth","La loi Veil","La loi Ferry"]'::jsonb, 0, 'Portée par la ministre des Droits de la femme Yvette Roudy, elle interdit les discriminations professionnelles.', 12),
    ('96644d9d-af51-567f-b8d0-c6cb89e90fe9'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Quelle part du commerce mondial, en volume, passe par la mer ?', 'mcq', '["Environ 20 %","Environ 50 %","Environ 80 %","Environ 99 %"]'::jsonb, 2, 'Le transport maritime est le plus économique pour de grandes quantités.', 1),
    ('3673e309-b15c-5dd6-a736-ec6dfe756a28'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Qu’est-ce que la maritimisation ?', 'mcq', '["La montée du niveau de la mer","Le poids croissant des activités et échanges maritimes dans l’économie","La pollution des océans","La construction de navires de guerre"]'::jsonb, 1, 'Elle est l’un des moteurs de la mondialisation.', 2),
    ('283c521f-b8f2-5370-ab71-1c1a1029eef0'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Quelle invention de 1956 a révolutionné le transport maritime ?', 'mcq', '["Le conteneur","Le moteur à vapeur","Le GPS","Le pétrolier"]'::jsonb, 0, 'Standardisé, il permet de charger et décharger rapidement et à bas coût.', 3),
    ('4a432b00-7603-55d2-9965-246e235b5d1b'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Qu’est-ce qu’une zone économique exclusive (ZEE) ?', 'mcq', '["Une zone franche portuaire","Une zone interdite à la navigation","Une zone de pêche internationale","Un espace maritime de 200 milles où un État exploite seul les ressources"]'::jsonb, 3, 'Elle est définie par la convention de Montego Bay (1982).', 4),
    ('4135a23e-c5da-5079-8740-dc120204fea1'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Quel détroit voit passer environ un cinquième du pétrole mondial ?', 'mcq', '["Gibraltar","Le Bosphore","Ormuz","Le pas de Calais"]'::jsonb, 2, 'À la sortie du golfe Persique, il est très sensible aux tensions avec l’Iran.', 5),
    ('56fe4144-0015-504e-8b8f-b074b8a01e9b'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Quel navire a bloqué le canal de Suez en 2021 ?', 'mcq', '["Le Titanic","L’Ever Given","Le Queen Mary 2","Le Charles-de-Gaulle"]'::jsonb, 1, 'Ce porte-conteneurs échoué a bloqué le canal six jours, montrant sa vulnérabilité.', 6),
    ('369afc8e-0b97-561f-8188-ceca93646bc3'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Sept des dix premiers ports à conteneurs du monde sont chinois.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Shanghai, Ningbo-Zhoushan, Shenzhen, Qingdao, Canton, Tianjin, Xiamen : la Chine domine le classement.', 7),
    ('83f0b349-5725-5b29-adc9-261b111d0baa'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Quelle route maritime passe par Malacca et Suez ?', 'mcq', '["La route transatlantique","La route transpacifique","La route arctique","La route Asie-Europe"]'::jsonb, 3, 'C’est l’une des routes les plus fréquentées du monde.', 8),
    ('841869c6-2945-5ea7-a654-d78f8b9a9881'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Où la piraterie maritime est-elle particulièrement active ?', 'mcq', '["En mer Baltique","Dans le golfe de Guinée et le golfe d’Aden","En Méditerranée occidentale","Dans les Grands Lacs"]'::jsonb, 1, 'Elle menace les navires et justifie des opérations navales internationales.', 9),
    ('bc298cd6-be8e-5c5b-af63-3a696d3f4314'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Pourquoi le trafic du canal de Suez a-t-il chuté en 2024 ?', 'mcq', '["À cause d’une sécheresse","À cause des attaques des Houthis en mer Rouge","À cause de sa fermeture définitive","À cause d’un nouveau canal"]'::jsonb, 1, 'De nombreux navires ont contourné l’Afrique par le cap de Bonne-Espérance.', 10),
    ('c372e6ba-8bc8-5599-9072-29d3bc1d0f2b'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Les échanges maritimes sont répartis de façon égale entre tous les littoraux du monde.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils se concentrent sur quelques façades ; d’autres littoraux restent en marge.', 11),
    ('0ac8a654-79d8-5c47-8e56-4ba960065276'::uuid, 'eb90ba5b-a361-5524-b1d5-76e3958dfe57'::uuid, 'Quelle ressource est extraite en mer, notamment dans le golfe de Guinée ?', 'mcq', '["Le pétrole","Le charbon","L’uranium","Le cuivre"]'::jsonb, 0, 'Environ un tiers du pétrole mondial provient de gisements offshore.', 12),
    ('6c31c6c3-11aa-594e-9bae-dbe3de60e069'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Quelle part des communications intercontinentales passe par des câbles sous-marins ?', 'mcq', '["Environ 10 %","Environ 50 %","Plus de 95 %","Aucune, tout passe par satellite"]'::jsonb, 2, 'Les satellites ne transportent qu’une petite part du trafic.', 1),
    ('1c068d88-bd5e-5862-88ff-d4f7679266a2'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'En quoi sont faits les câbles sous-marins modernes ?', 'mcq', '["En cuivre","En fibre optique","En plastique simple","En acier uniquement"]'::jsonb, 1, 'La fibre transporte la lumière et des débits énormes.', 2),
    ('30f44989-03dc-5e1b-ac85-b73c8a00cf3f'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Qu’est-ce qu’un point d’atterrage ?', 'mcq', '["Le lieu où un câble sort de la mer et rejoint la terre","Un aéroport","Un port de pêche","Un satellite"]'::jsonb, 0, 'C’est un point stratégique et vulnérable du réseau.', 3),
    ('5a5c88ab-f342-57cc-bde8-98ecd4423478'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Quelle ville française est un grand carrefour de câbles sous-marins ?', 'mcq', '["Lyon","Strasbourg","Paris","Marseille"]'::jsonb, 3, 'Plus de quinze câbles y relient l’Europe à l’Afrique, au Moyen-Orient et à l’Asie.', 4),
    ('8e82fbee-34d1-5d8a-9f4e-a33b0148bd2f'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Qui finance aujourd’hui une grande part des nouveaux câbles ?', 'mcq', '["Les géants du numérique comme Google ou Meta","L’ONU","Les compagnies aériennes","Les agriculteurs"]'::jsonb, 0, 'Ils ont besoin d’énormes capacités pour leurs services et centres de données.', 5),
    ('5d5ac521-5641-5dd2-910c-67767a054327'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Quelle est la principale cause des ruptures de câbles ?', 'mcq', '["Les requins","Les ancres et les chaluts","Le froid","Les satellites"]'::jsonb, 1, 'Les activités humaines accidentelles causent la plupart des incidents.', 6),
    ('e77cad4e-673d-5303-8dc6-c7b6d7f55e71'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Quel archipel a été coupé du monde après une éruption volcanique en 2022 ?', 'mcq', '["Hawaï","Les Canaries","Tonga","Les Açores"]'::jsonb, 2, 'L’éruption et le tsunami ont rompu son unique câble international.', 7),
    ('43d7c4a5-2f49-5703-8186-1dc1ee2debff'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Une entreprise française figure parmi les grands poseurs de câbles sous-marins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alcatel Submarine Networks est l’un des trois leaders mondiaux avec SubCom et NEC.', 8),
    ('cbd030f4-b85a-5fbf-9dc5-e45cf54d24d0'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Pourquoi les câbles sont-ils des enjeux stratégiques pour les États ?', 'mcq', '["Parce qu’ils produisent de l’électricité","Parce qu’ils peuvent être sabotés ou espionnés","Parce qu’ils transportent du pétrole","Parce qu’ils servent à la pêche"]'::jsonb, 1, 'Des câbles ont été coupés en mer Baltique et en mer Rouge ; les États surveillent les fonds marins.', 9),
    ('bb5cebaa-34c1-5f04-ad9e-54d730477c20'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'De quand date le premier câble télégraphique transatlantique ?', 'mcq', '["1988","1945","1914","1858"]'::jsonb, 3, 'Le premier câble à fibre optique transatlantique date de 1988.', 10),
    ('acbc2d96-c0b2-5357-8931-48e444aca63a'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Tous les pays du monde sont reliés par de nombreux câbles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Certains pays ou îles ne dépendent que d’un ou deux câbles : le réseau reflète une insertion inégale.', 11),
    ('b32a2dd6-5458-59fc-a776-c09a2da4e790'::uuid, '62d794aa-141d-5994-ad0d-53c7b24be3eb'::uuid, 'Entre quels espaces les câbles sont-ils les plus nombreux ?', 'mcq', '["Afrique et Amérique du Sud","Amérique du Nord, Europe et Asie de l’Est","Océanie et Antarctique","Asie centrale et Afrique"]'::jsonb, 1, 'Ce sont les pôles majeurs de la mondialisation.', 12),
    ('36a83ce5-b2cb-58b9-8c84-6917c71acd52'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Quels espaces maritimes le détroit de Malacca relie-t-il ?', 'mcq', '["L’Atlantique et le Pacifique","L’océan Indien et la mer de Chine méridionale","La Méditerranée et la mer Rouge","La mer Noire et la Méditerranée"]'::jsonb, 1, 'Il est le passage le plus court entre l’océan Indien et le Pacifique.', 1),
    ('a6cb4115-d648-5000-8186-63eda0eff195'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Entre quelles terres se trouve le détroit ?', 'mcq', '["La péninsule malaise et Sumatra","Java et Bornéo","Taïwan et la Chine","L’Inde et le Sri Lanka"]'::jsonb, 0, 'La Malaisie est au nord-est, l’Indonésie (Sumatra) au sud-ouest.', 2),
    ('e29203a9-1a7e-5971-9844-241ea1565b6b'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Quelle part du commerce mondial passe par Malacca ?', 'mcq', '["Environ 5 %","Environ 60 %","Environ 1 %","Près d’un tiers"]'::jsonb, 3, 'C’est l’un des passages les plus fréquentés au monde.', 3),
    ('2c9708be-16cf-59c2-a93f-d9e2c4f490e6'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Quel grand port se situe à l’extrémité sud-est du détroit ?', 'mcq', '["Hong Kong","Shanghai","Singapour","Djakarta"]'::jsonb, 2, 'Deuxième port à conteneurs du monde, c’est un grand port de transbordement.', 4),
    ('7bc5c96c-a977-5af5-81ea-b737ea1ad404'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Quelle menace a longtemps touché le détroit de Malacca ?', 'mcq', '["La piraterie","Les icebergs","Les cyclones polaires","Les requins"]'::jsonb, 0, 'Au début des années 2000, c’était l’une des zones les plus touchées au monde.', 5),
    ('3ad0ab1f-03d9-5a8b-b65a-ba61c8bff47f'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Les États riverains organisent des patrouilles communes contre la piraterie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Indonésie, Malaisie, Singapour et Thaïlande coopèrent depuis 2004.', 6),
    ('5c5843d1-82e5-5484-bcff-7dce61d06c82'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Qu’appelle-t-on le « dilemme de Malacca » ?', 'mcq', '["Le choix entre deux ports","La crainte chinoise d’un blocage du détroit qui couperait ses approvisionnements","Un conflit entre pêcheurs","Un problème de pollution"]'::jsonb, 1, 'La Chine développe des routes de contournement et renforce sa marine.', 7),
    ('093dd899-127f-5827-9d53-287cd815abab'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Pourquoi les plus gros pétroliers évitent-ils Malacca ?', 'mcq', '["À cause de la profondeur limitée du détroit","À cause de la glace","À cause d’un péage trop cher","À cause d’une interdiction de l’ONU"]'::jsonb, 0, 'Ils passent par le détroit de Lombok, plus profond.', 8),
    ('610f6f4c-e1bb-5e36-8a53-d205421dd1a8'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Quel pays surveille l’entrée ouest du détroit depuis les îles Andaman-et-Nicobar ?', 'mcq', '["Le Japon","La Chine","Les États-Unis","L’Inde"]'::jsonb, 3, 'L’Inde veut peser face à l’influence chinoise dans l’océan Indien.', 9),
    ('44f46a0f-05c1-552c-ac93-dc202ca6546d'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Quelle est la largeur minimale du détroit ?', 'mcq', '["Environ 280 km","Environ 28 km","Environ 2,8 km","Environ 28 m"]'::jsonb, 2, 'Près de Singapour, le chenal est très étroit, d’où la saturation.', 10),
    ('84fa24a1-529d-5bf0-ac8a-60bd8853a711'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Les nouvelles routes de la soie chinoises cherchent notamment à contourner Malacca.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Oléoducs à travers la Birmanie et port de Gwadar au Pakistan en sont des exemples.', 11),
    ('ef970c4f-7969-515f-bcb7-af584151b802'::uuid, 'b7c405e6-db1d-561b-ab51-d2e88533ec49'::uuid, 'Pourquoi dit-on que Malacca est un goulet d’étranglement ?', 'mcq', '["Parce qu’il est très large","Parce qu’il est fermé","Parce qu’un passage étroit concentre un trafic énorme dont dépend l’économie asiatique","Parce qu’il n’a pas de port"]'::jsonb, 2, 'Un blocage paralyserait une grande partie du commerce et de l’énergie de l’Asie de l’Est.', 12),
    ('b3c2f2cb-122f-5c1b-a349-c4e0bc8e903a'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Qu’est-ce qu’un centre de décision ?', 'mcq', '["Un bureau de vote","Un lieu où se prennent les décisions qui orientent l’économie ou la politique mondiale","Un centre commercial","Un tribunal"]'::jsonb, 1, 'Sièges de firmes, bourses et organisations internationales en sont des exemples.', 1),
    ('43c294ab-4c04-514d-a2f4-ec844e07a71a'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Qu’est-ce qu’un hub ?', 'mcq', '["Une plateforme où convergent et se redistribuent les flux","Un quartier résidentiel","Une frontière","Un satellite"]'::jsonb, 0, 'Les grands aéroports et ports fonctionnent comme des hubs.', 2),
    ('0d56bcc8-6d2e-50f9-8947-3bce140b173f'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Quelle région fait partie des marges de la mondialisation ?', 'mcq', '["La Northern Range","Le Sahel","La Mégalopolis américaine","Le delta de la rivière des Perles"]'::jsonb, 1, 'Enclavement, pauvreté et conflits y limitent l’intégration.', 3),
    ('7ff1bdda-17b9-5a16-b035-10f0c276f48d'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Quelle mesure est un exemple de protectionnisme ?', 'mcq', '["La création d’une zone de libre-échange","La suppression des douanes","La hausse des droits de douane","Un nouveau câble sous-marin"]'::jsonb, 2, 'Les États-Unis ont relevé leurs droits de douane en 2018 puis fortement en 2025.', 4),
    ('5c101975-fefa-5e51-836e-f91ec6512dab'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Qu’est-ce qu’une plateforme multimodale ?', 'mcq', '["Une scène de concert","Un réseau social","Un lieu qui relie plusieurs modes de transport","Un aéroport sans avion"]'::jsonb, 2, 'Roissy associe avion, TGV, RER et autoroutes.', 5),
    ('b3ccf584-adab-53a1-9b4e-d5aca2d36396'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Les organisations régionales comme l’UE ou l’ASEAN facilitent les échanges entre leurs membres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles réduisent les barrières et créent de grands marchés.', 6),
    ('d71e34ac-a337-5a26-a56f-35b8363c82bb'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Quelle part du commerce mondial représentent les pays les moins avancés ?', 'mcq', '["Environ 25 %","Environ 10 %","Environ 50 %","Environ 1 %"]'::jsonb, 3, 'Ils restent en marge malgré leur population importante.', 7),
    ('5982a3b5-5414-5c6b-ade0-ab8854aa0655'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Que désigne le « nearshoring » ?', 'mcq', '["Le rapprochement de la production vers les marchés de consommation","La délocalisation vers l’Asie lointaine","La fermeture des ports","La construction de câbles"]'::jsonb, 0, 'Des firmes installent des usines au Mexique ou au Maroc pour être plus près des États-Unis ou de l’Europe.', 8),
    ('9fac6625-ae99-5b6c-8d92-2947876a1a7f'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Quels critères guident les implantations des firmes transnationales ?', 'mcq', '["Uniquement le climat","Le coût du travail, la taille du marché, les infrastructures","La couleur du drapeau","Le hasard"]'::jsonb, 1, 'Elles cherchent à maximiser leurs profits et l’accès aux marchés.', 9),
    ('a7c9486f-1747-50fe-bfb4-46d9e1a2d57a'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'La hiérarchie des centres de décision mondiaux ne change jamais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle évolue : les métropoles asiatiques concurrencent New York, Londres ou Paris.', 10),
    ('f70d3885-2b74-5729-b2d2-642f37361064'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'Quelle région chinoise est la mieux intégrée à la mondialisation ?', 'mcq', '["Le Tibet","Le Xinjiang","Le littoral","La Mongolie-Intérieure"]'::jsonb, 2, 'Ports, zones franches et métropoles en font l’interface avec le monde.', 11),
    ('2d025fba-9cda-5acd-909a-deed92a714e8'::uuid, '0cf26129-1373-5116-ae60-06b8d64c95d0'::uuid, 'À quelle échelle observe-t-on des contrastes entre quartiers d’affaires et quartiers pauvres ?', 'mcq', '["Mondiale","Continentale","Nationale","Locale"]'::jsonb, 3, 'Les inégalités existent aussi à l’intérieur d’une même métropole.', 12),
    ('3f81aa7c-14fc-5734-9770-de4c89577816'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quelle rue de Manhattan symbolise la finance mondiale ?', 'mcq', '["Broadway","Wall Street","Fifth Avenue","Times Square"]'::jsonb, 1, 'Elle abrite le New York Stock Exchange, première bourse mondiale.', 1),
    ('93972086-55f7-5548-85e6-2c314bfacf0d'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quelle organisation internationale a son siège à New York ?', 'mcq', '["L’ONU","L’OTAN","L’Union européenne","L’OMC"]'::jsonb, 0, 'Le siège, sur l’East River, accueille l’Assemblée générale chaque automne.', 2),
    ('55561a3e-f27b-58b9-8a56-64172519a62e'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Combien d’habitants compte l’aire métropolitaine de New York ?', 'mcq', '["Environ 2 millions","Environ 8 millions","Plus de 19 millions","Environ 50 millions"]'::jsonb, 2, 'La ville elle-même compte environ 8,3 millions d’habitants.', 3),
    ('a06d6b50-8aa8-5ef1-952c-eb48d1e3bab4'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quelles sont les deux premières bourses du monde ?', 'mcq', '["Londres et Paris","Tokyo et Shanghai","Francfort et Hong Kong","Le NYSE et le Nasdaq"]'::jsonb, 3, 'Toutes deux sont à New York.', 4),
    ('22c15310-233b-5657-98d5-d1c0abc74b09'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quel quartier new-yorkais est célèbre pour ses théâtres ?', 'mcq', '["Broadway","Harlem","Le Bronx","Staten Island"]'::jsonb, 0, 'Les comédies musicales de Broadway attirent des millions de spectateurs.', 5),
    ('204b4c3c-1447-5db0-9cbf-10c6e004ae0b'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'New York fait partie de la Mégalopolis du Nord-Est des États-Unis.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette mégalopole s’étend de Boston à Washington.', 6),
    ('5e60ced3-039a-5aab-a7b9-b2458252a63f'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Pourquoi dit-on que New York est une ville-monde ?', 'mcq', '["Parce qu’elle est la plus peuplée du monde","Parce qu’elle cumule des fonctions financières, politiques et culturelles de rang mondial","Parce qu’elle est la capitale des États-Unis","Parce qu’elle est la plus ancienne"]'::jsonb, 1, 'Washington est la capitale ; New York domine par ses fonctions de commandement.', 7),
    ('657b7982-9940-5b5d-9a29-e811e5f60830'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quel est le principal aéroport international de New York ?', 'mcq', '["Heathrow","O’Hare","JFK","Roissy"]'::jsonb, 2, 'New York est desservie par trois grands aéroports : JFK, Newark et LaGuardia.', 8),
    ('4cdbcb18-a5c5-515c-a571-495e3306f208'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quelle part des New-Yorkais sont nés à l’étranger ?', 'mcq', '["Aucun","Environ 5 %","Plus des trois quarts","Plus d’un tiers"]'::jsonb, 3, 'Cette population cosmopolite reflète l’attractivité mondiale de la ville.', 9),
    ('df7d6121-7e20-53b0-bd70-124531d28cad'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quel ouragan a frappé New York en 2012 ?', 'mcq', '["Katrina","Sandy","Irma","Harvey"]'::jsonb, 1, 'Il a inondé une partie de Manhattan et montré la vulnérabilité de la ville.', 10),
    ('75fec301-d796-52a9-913d-418cd132eeac'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'New York n’a aucune concurrente parmi les métropoles mondiales.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Londres, Tokyo, Shanghai ou Singapour lui disputent des fonctions de commandement.', 11),
    ('b7461678-deff-5780-848e-1cc7156e173c'::uuid, 'c550d44d-8fce-571b-9d60-a883f4c7094c'::uuid, 'Quel musée new-yorkais est consacré à l’art moderne ?', 'mcq', '["Le MoMA","Le Louvre","Le British Museum","Le Prado"]'::jsonb, 0, 'Le Museum of Modern Art est l’un des plus grands musées d’art moderne du monde.', 12),
    ('7ecf8f2b-5985-591a-a73b-c3236565b737'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Qu’est-ce qu’un hub aéroportuaire ?', 'mcq', '["Un petit aéroport régional","Une plateforme de correspondance où une compagnie concentre ses vols","Une piste d’atterrissage","Une compagnie aérienne"]'::jsonb, 1, 'Les passagers y changent d’avion pour rejoindre de nombreuses destinations.', 1),
    ('39c0cbff-c3d4-5b6e-baf9-4f17cbe276a7'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Quelle compagnie a fait de Roissy-CDG son hub ?', 'mcq', '["Air France","British Airways","Lufthansa","Emirates"]'::jsonb, 0, 'Air France, au sein du groupe Air France-KLM, concentre ses vols long-courriers à Roissy.', 2),
    ('1206b1a7-6461-5d04-9adc-d8aa269bd432'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Combien de passagers Roissy-CDG accueille-t-il environ par an ?', 'mcq', '["7 millions","700 millions","70 millions","7 000"]'::jsonb, 2, 'C’est l’un des plus grands aéroports d’Europe.', 3),
    ('49600d92-0851-54d3-aebf-2ba7f683a029'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Quel changement a favorisé la formation des hubs ?', 'mcq', '["La nationalisation des compagnies","L’interdiction des vols internationaux","La fin du fret aérien","L’ouverture à la concurrence et la déréglementation du transport aérien"]'::jsonb, 3, 'Les compagnies ont concentré leurs dessertes sur un pôle unique pour être plus compétitives.', 4),
    ('cfc4ba8d-815b-5531-8ce5-6caf7da61984'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Quel aéroport est le hub de British Airways ?', 'mcq', '["Londres-Heathrow","Paris-Orly","Francfort","Amsterdam-Schiphol"]'::jsonb, 0, 'Chaque grande compagnie européenne a son hub.', 5),
    ('a5bd25cc-a2be-5dc5-be5d-baf2b311a65d'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Roissy est relié au réseau TGV depuis 1994.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La gare TGV du terminal 2 est sur l’interconnexion des lignes à grande vitesse.', 6),
    ('6bc3a7c5-57df-5951-85ec-d46bf73de5d4'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Pourquoi dit-on que Roissy est une plateforme multimodale ?', 'mcq', '["Parce qu’il a plusieurs terminaux","Parce qu’il relie avion, trains (RER, TGV) et autoroutes","Parce qu’il accueille plusieurs compagnies","Parce qu’il a quatre pistes"]'::jsonb, 1, 'Cette connexion multiplie son aire d’attraction.', 7),
    ('5bc90ea0-42f0-5d57-a62c-6e02a5ad9c6a'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Quel type de marchandises transporte surtout le fret aérien ?', 'mcq', '["Du charbon","Du pétrole brut","Des produits de forte valeur ou urgents","Des céréales"]'::jsonb, 2, 'Médicaments, électronique et luxe justifient le coût élevé de l’avion.', 8),
    ('882c58d9-97f1-5f68-95ff-3d3d24c04ec9'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Quelle entreprise de livraison a son hub européen à Roissy ?', 'mcq', '["DHL","UPS","Amazon Air","FedEx"]'::jsonb, 3, 'DHL a choisi Leipzig ; FedEx a choisi Roissy.', 9),
    ('2d48d6e6-0ead-5762-a56a-367cdb26644d'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Pourquoi le projet de terminal 4 a-t-il été abandonné en 2021 ?', 'mcq', '["Par manque de terrain","Pour des raisons climatiques et de trafic","À cause d’une grève","Parce que Roissy ferme"]'::jsonb, 1, 'Le gouvernement l’a jugé incompatible avec les objectifs de réduction des émissions.', 10),
    ('a1e71acb-39cd-5a13-975f-4c44b609c4b5'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Les communes voisines de Roissy profitent toutes pleinement des emplois de l’aéroport.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Beaucoup d’habitants des communes populaires proches accèdent peu aux emplois qualifiés, et subissent les nuisances.', 11),
    ('daa462c3-4a19-51da-b842-a74201ad436f'::uuid, '51b3898b-a7c2-5cac-be8f-60b50c343a77'::uuid, 'Quels hubs concurrencent Roissy pour les correspondances entre l’Europe et l’Asie ?', 'mcq', '["Dubaï, Doha et Istanbul","Lyon et Marseille","Nice et Bâle","Orly et Beauvais"]'::jsonb, 0, 'Les hubs du Golfe et d’Istanbul captent une part croissante des correspondances.', 12),
    ('6d4ba346-4098-529a-bf0c-29a75dca2a41'::uuid, '446654f5-f14e-54e5-bbf5-337bbe74e638'::uuid, 'Quelle différence entre rayonnement et attractivité ?', 'mcq', '["Aucune","Le rayonnement se fait connaître à l’étranger ; l’attractivité attire sur son territoire","Le rayonnement concerne l’économie seulement","L’attractivité concerne l’armée"]'::jsonb, 1, 'Un pays rayonne vers l’extérieur et attire vers l’intérieur.', 1),
