    ('1bb0da6f-2016-5b0a-8d22-703cf9ddade3'::uuid, '446654f5-f14e-54e5-bbf5-337bbe74e638'::uuid, 'Combien de francophones compte-t-on dans le monde ?', 'mcq', '["Environ 32 millions","Environ 3 milliards","Environ 320 millions","Environ 68 millions"]'::jsonb, 2, 'Une grande partie vit en Afrique, où la francophonie progresse avec la démographie.', 3),
    ('db650307-865b-5da3-8e76-ab9e886d8566'::uuid, '446654f5-f14e-54e5-bbf5-337bbe74e638'::uuid, 'Quel musée français a ouvert une antenne à Abu Dhabi en 2017 ?', 'mcq', '["Le musée d’Orsay","Le Centre Pompidou","Le musée Grévin","Le Louvre"]'::jsonb, 3, 'Le Louvre Abu Dhabi est un exemple de diplomatie culturelle.', 4),
