    ('08735e81-7223-57ce-a241-cec93cec758b'::uuid, '446654f5-f14e-54e5-bbf5-337bbe74e638'::uuid, 'La France est la première destination touristique du monde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle accueille environ 100 millions de touristes internationaux par an.', 6),
    ('74b75e6e-15bc-5a9b-b7c9-e5be68663298'::uuid, '446654f5-f14e-54e5-bbf5-337bbe74e638'::uuid, 'Quelle organisation internationale a son siège à Paris ?', 'mcq', '["L’ONU","L’UNESCO","L’OTAN","L’OMC"]'::jsonb, 1, 'Paris accueille aussi l’OCDE ; Strasbourg le Conseil de l’Europe et le Parlement européen.', 7),
