    ('93b0c739-4394-54d6-a9ac-a0bb4870800e'::uuid, '20888332-85be-5b98-bcc9-b8ae690503d7'::uuid, 'Quelle agence européenne finance une grande partie de la base ?', 'mcq', '["L’OTAN","L’ONU","La NASA","L’ESA"]'::jsonb, 3, 'L’Agence spatiale européenne réunit plus de vingt États membres.', 4),
    ('ad4adb97-495f-5114-9e72-bec6c2ea8bcf'::uuid, '20888332-85be-5b98-bcc9-b8ae690503d7'::uuid, 'Quel lanceur européen a fait son premier vol en juillet 2024 ?', 'mcq', '["Ariane 5","Soyouz","Ariane 6","Falcon 9"]'::jsonb, 2, 'Il succède à Ariane 5, retirée en 2023.', 5),
