    ('c482a33b-3270-5980-8157-e3f615772ea1'::uuid, '20888332-85be-5b98-bcc9-b8ae690503d7'::uuid, 'Pourquoi la France choisit-elle Kourou en 1964 ?', 'mcq', '["Pour remplacer les bases du Sahara perdues avec l’indépendance de l’Algérie","Parce que c’est près de Paris","Parce que la Guyane est un désert","Pour être loin de l’océan"]'::jsonb, 0, 'Les premiers essais français avaient lieu à Hammaguir, dans le Sahara algérien.', 12),
    ('2938f5a6-2ef3-508d-8d52-5bd8cd0313c5'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Quand Disneyland Paris a-t-il ouvert ?', 'mcq', '["En 1972","En 1992","En 2002","En 1987"]'::jsonb, 1, 'L’accord avec l’État date de 1987 ; le parc ouvre en avril 1992.', 1),
