    ('b69b3c06-f96b-568f-ab73-7d7da7d4eaab'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Quel pays concurrençait la France pour accueillir le parc ?', 'mcq', '["L’Allemagne","L’Italie","Le Royaume-Uni","L’Espagne"]'::jsonb, 3, 'Disney a finalement choisi la région parisienne pour sa situation et sa renommée.', 4),
