    ('74738ce3-4ccb-569b-a8a0-da937becc1ba'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Quelle infrastructure relie directement le site à Roissy et aux grandes villes européennes ?', 'mcq', '["Un aéroport privé","La gare TGV Marne-la-Vallée-Chessy","Un port fluvial","Un téléphérique"]'::jsonb, 1, 'Ouverte en 1994, elle est à moins de 15 minutes de Roissy.', 7),
    ('088b8eeb-0608-54f7-9248-f4486a3dd712'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Combien de salariés compte environ Disneyland Paris ?', 'mcq', '["Environ 170","Environ 1 700","Environ 170 000","Environ 17 000"]'::jsonb, 3, 'C’est le premier employeur privé sur un seul site en Île-de-France.', 8),
    ('ed9b1cbe-3371-5c06-8133-b10c85b8351c'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Qui aménage le secteur autour du parc ?', 'mcq', '["Disney seul","L’Union européenne seule","Des acteurs publics et privés ensemble","Aucun acteur"]'::jsonb, 2, 'L’État, la Région, les communes et l’établissement public EPAFRANCE travaillent avec Disney.', 9),
    ('136c13c2-80d0-5d99-96fa-de7d2ccbd9b4'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Pourquoi Disneyland Paris est-il un marqueur de l’intégration de la France dans la mondialisation ?', 'mcq', '["Parce qu’il est gratuit","Parce qu’une firme américaine y attire des visiteurs du monde entier grâce à la renommée de la France","Parce qu’il appartient à l’État","Parce qu’il n’accueille que des Français"]'::jsonb, 1, 'Il associe firme transnationale, flux touristiques internationaux et attractivité française.', 10),
    ('5186d8a6-e684-5784-9280-56fbe8c7709b'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Le parc n’a eu aucun effet négatif sur son territoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Artificialisation des terres, emplois précaires, critiques culturelles : il y a aussi des limites.', 11),
    ('de144b12-9a7e-51fa-9393-b99ed640c59c'::uuid, 'b5a78cf8-1f6d-54be-ab97-fe5b33341f4d'::uuid, 'Quel centre commercial s’est développé à côté du parc ?', 'mcq', '["Val d’Europe","Les Quatre Temps","Part-Dieu","Euralille"]'::jsonb, 0, 'Le Val d’Europe et l’outlet La Vallée Village attirent aussi une clientèle internationale.', 12),
