    ('6520059d-7e84-5bb3-a312-21ed84a3cfa5'::uuid, 'f1d75104-1562-5057-945d-c1eb0dc45233'::uuid, 'Diminuer une quantité de 30 %, c’est la multiplier par…', 'mcq', '["0,7","0,3","1,3","0,97"]'::jsonb, 0, '1 − 30/100 = 0,7.', 3),
    ('02a15f9e-e14f-5523-aa35-cae8a42c2943'::uuid, 'f1d75104-1562-5057-945d-c1eb0dc45233'::uuid, 'Un prix de 50 € augmente de 10 %. Quel est le nouveau prix ?', 'mcq', '["51 €","55 €","60 €","50,10 €"]'::jsonb, 1, '50 × 1,1 = 55.', 4),
