    ('510fb4c5-6953-5088-b40d-b7eb54f147da'::uuid, 'f1d75104-1562-5057-945d-c1eb0dc45233'::uuid, 'Une hausse de 20 % suivie d’une baisse de 20 % équivaut à…', 'mcq', '["Aucune évolution","Une hausse de 4 %","Une baisse de 40 %","Une baisse de 4 %"]'::jsonb, 3, '1,2 × 0,8 = 0,96, soit − 4 %.', 6),
