    ('9d7378cb-209a-55d7-81ef-df5bcb8b3c62'::uuid, 'f1d75104-1562-5057-945d-c1eb0dc45233'::uuid, 'Après une hausse de 10 %, un prix vaut 66 €. Quel était le prix initial ?', 'mcq', '["59,40 €","60 €","56 €","76 €"]'::jsonb, 1, '66 ÷ 1,1 = 60.', 8),
    ('28b5fd48-3b18-55b6-8e3a-01dd90b7d161'::uuid, 'f1d75104-1562-5057-945d-c1eb0dc45233'::uuid, '40 % des élèves sont des filles et 25 % d’entre elles font de la natation. Quelle proportion des élèves sont des nageuses ?', 'mcq', '["65 %","15 %","10 %","25 %"]'::jsonb, 2, 'Proportion d’une proportion : 0,4 × 0,25 = 0,1.', 9),
    ('45c59c86-6a1e-500c-aa19-51f103cd76be'::uuid, 'f1d75104-1562-5057-945d-c1eb0dc45233'::uuid, 'Deux hausses successives de 10 % équivalent à une hausse de 20 %.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '1,1 × 1,1 = 1,21 : c’est une hausse de 21 %.', 10),
    ('4828ec1f-4b75-5ae7-8165-7a0fcaddc0e2'::uuid, 'f1d75104-1562-5057-945d-c1eb0dc45233'::uuid, 'Un coefficient multiplicateur de 0,75 correspond à…', 'mcq', '["Une hausse de 75 %","Une baisse de 75 %","Une hausse de 25 %","Une baisse de 25 %"]'::jsonb, 3, '0,75 = 1 − 0,25.', 11),
