    ('ae79f152-1801-5893-a441-f1be645ca514'::uuid, '2757d143-df54-5d3e-8630-12507b29330d'::uuid, 'Combien vaut 2/3 × 3/4 ?', 'mcq', '["1/2","5/7","6/7","8/9"]'::jsonb, 0, '6/12 = 1/2.', 2),
