    ('5f42aab3-5baf-5d2a-885a-77fb37636364'::uuid, '2757d143-df54-5d3e-8630-12507b29330d'::uuid, 'Combien vaut 10³ × 10^(−5) ?', 'mcq', '["10^(−15)","10⁸","10^(−2)","10²"]'::jsonb, 2, 'On additionne les exposants : 3 + (−5) = −2.', 4),
