    ('0c6ea785-4f0b-5bcb-ad3c-8b1ce74e4065'::uuid, '8543887a-e01c-5098-8b43-229bc3c3412f'::uuid, 'Une droite passe par G1(1 ; 3) et G2(5 ; 11). Quelle est son équation ?', 'mcq', '["y = 3x","y = 2x + 3","y = 8x − 5","y = 2x + 1"]'::jsonb, 3, 'a = 8 ÷ 4 = 2, puis 3 = 2 + b donc b = 1.', 8),
