    ('3f4c4e97-5dcf-54af-a822-284c61509f0f'::uuid, '259ac9a1-a810-58e9-a689-e45cfaafc87b'::uuid, 'P(A) = 0,5 et P(A ∩ B) = 0,2. Combien vaut P_A(B) ?', 'mcq', '["0,1","0,7","0,4","2,5"]'::jsonb, 2, '0,2 ÷ 0,5 = 0,4.', 1),
    ('2f8a0cab-a356-51e6-98d8-169b9be84508'::uuid, '259ac9a1-a810-58e9-a689-e45cfaafc87b'::uuid, 'P(A) = 0,6 et P_A(B) = 0,3. Combien vaut P(A ∩ B) ?', 'mcq', '["0,9","0,5","0,3","0,18"]'::jsonb, 3, '0,6 × 0,3 = 0,18.', 2),
    ('4bd9119f-118b-56ee-9887-7d9574a52262'::uuid, '259ac9a1-a810-58e9-a689-e45cfaafc87b'::uuid, 'Dans l’exemple de la fiche, P(C ∩ L) = 0,18 et P(C̄ ∩ L) = 0,04. Combien vaut P(L) ?', 'mcq', '["0,22","0,14","0,4","0,0072"]'::jsonb, 0, 'Formule des probabilités totales : 0,18 + 0,04.', 3),
