    ('43f71556-0ff0-5cc4-b7e3-196ac4eb1b6a'::uuid, '259ac9a1-a810-58e9-a689-e45cfaafc87b'::uuid, 'A et B sont indépendants si…', 'mcq', '["P(A ∩ B) = 0","P(A) = P(B)","P(A) + P(B) = 1","P(A ∩ B) = P(A) × P(B)"]'::jsonb, 3, 'C’est équivalent à P_A(B) = P(B).', 6),
