    ('979052f7-3310-5e02-9bf4-0849221f37e8'::uuid, '259ac9a1-a810-58e9-a689-e45cfaafc87b'::uuid, 'A et B sont indépendants, P(A) = 0,3 et P(B) = 0,5. Combien vaut P(A ∩ B) ?', 'mcq', '["0,8","0,15","0,2","0,6"]'::jsonb, 1, '0,3 × 0,5 = 0,15.', 8),
