    ('d35631d3-d981-5c97-b955-cbe779288ba7'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Si y ≈ k × a^x, quel changement de variable rend le nuage alignable ?', 'mcq', '["z = y²","z = 1/y","z = y + x","z = log(y)"]'::jsonb, 3, 'log(y) = log(k) + x log(a), affine en x.', 4),
    ('f3e57665-96c8-5377-a39b-4d279d610e8a'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Si y ≈ 3 × 2^x, que vaut le coefficient directeur dans le repère (x ; log(y)) ?', 'mcq', '["log(2) ≈ 0,301","3","2","log(3)"]'::jsonb, 0, 'log(y) = log(3) + x × log(2).', 5),
    ('db194c21-ebb2-5001-8d35-f6328a628302'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Si y ≈ a/x + b, quel changement de variable convient ?', 'mcq', '["t = x²","t = 1/x","t = log(x)","t = x + 1"]'::jsonb, 1, 'y = at + b devient affine en t.', 6),
    ('ffb023fd-ac0d-5cc9-84c5-d38088d8f6ac'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Avec l’ajustement y = 1,8x + 12, quelle estimation pour x = 10 ?', 'mcq', '["28","18","30","120"]'::jsonb, 2, '1,8 × 10 + 12 = 30.', 7),
    ('2329ec89-1a3f-5d91-9add-a8bf4007d108'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Un bon ajustement affine prouve un lien de cause à effet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il décrit une tendance, pas une cause.', 8),
    ('72d4b318-d1ec-530c-8535-489c68b0671e'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Pourquoi une extrapolation lointaine est-elle fragile ?', 'mcq', '["La calculatrice se trompe","Elle est interdite","Elle ne passe pas par G","Rien ne garantit que la tendance se poursuive"]'::jsonb, 3, 'Saturation, changement de contexte : le modèle peut cesser d’être valable.', 9),
    ('55f38bfa-9f8e-55c1-8f9a-9cb9e6ea41e6'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Quand envisage-t-on directement un ajustement affine ?', 'mcq', '["Quand le nuage est allongé, à peu près rectiligne","Quand le nuage est circulaire","Quand il y a un seul point","Jamais"]'::jsonb, 0, 'Sinon, on cherche un changement de variable.', 10),
    ('e1543777-d7f2-5dcb-bba2-c94d428212a5'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Le point moyen a pour coordonnées…', 'mcq', '["(x_1 ; y_1)","(x̄ ; ȳ)","(0 ; 0)","(max x ; max y)"]'::jsonb, 1, 'Les moyennes des deux séries.', 11),
    ('c9e4298f-b414-59de-840b-0a4cb7c4dc87'::uuid, '61062e30-ac48-5e88-9a22-fb248e1e18ca'::uuid, 'Dans un repère semi-logarithmique, une croissance exponentielle apparaît…', 'mcq', '["En forme de parabole","Circulaire","Alignée","Aléatoire"]'::jsonb, 2, 'Le logarithme la transforme en relation affine.', 12),
    ('8e69e1f0-4923-5ef8-8ecc-c7cb676c0c9c'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'P(A) = 0,4 et P(A ∩ B) = 0,1. Combien vaut P_A(B) ?', 'mcq', '["0,04","0,25","0,5","4"]'::jsonb, 1, '0,1 ÷ 0,4 = 0,25.', 1),
    ('6899593c-4ec9-55e9-a233-49f5ff6205b0'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'Dans l’exemple de la fiche, combien vaut P(A ∩ D) ?', 'mcq', '["0,52","0,02","0,010","0,5"]'::jsonb, 2, '0,5 × 0,02 = 0,010.', 2),
    ('6cb106bc-6849-56e3-9a2a-d0c16fb9a7a1'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'Dans l’exemple de la fiche, combien vaut P(D) ?', 'mcq', '["0,10","0,033","0,01","0,029"]'::jsonb, 3, '0,010 + 0,009 + 0,010.', 3),
    ('7c5b1d53-4f7b-5a8b-94d0-92012a43d823'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'Dans l’exemple de la fiche, P_D(C) vaut environ…', 'mcq', '["0,345","0,05","0,2","0,01"]'::jsonb, 0, '0,010 ÷ 0,029.', 4),
    ('014eeeb1-594c-5376-b24b-8ea15f26fca8'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'La probabilité d’un chemin dans un arbre est…', 'mcq', '["La somme des probabilités de ses branches","Le produit des probabilités de ses branches","Toujours 1","La plus petite de ses branches"]'::jsonb, 1, 'On multiplie le long d’un chemin.', 5),
    ('aaf66eff-4f29-5b55-a703-eca77ed3f7b8'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'Pour appliquer la formule des probabilités totales, les événements A1, A2, A3 doivent…', 'mcq', '["Être indépendants","Avoir la même probabilité","Former une partition de l’univers","Être incompatibles avec B"]'::jsonb, 2, 'Sans chevauchement et couvrant tous les cas.', 6),
    ('08184271-d062-556a-8d56-86cbacecbd0a'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'P(A) = 0,5 et P(B) = 0,6. A et B sont indépendants. Combien vaut P(A ∩ B) ?', 'mcq', '["1,1","0,1","0,5","0,3"]'::jsonb, 3, '0,5 × 0,6 = 0,3.', 7),
    ('cc2060e1-e1dd-5a79-ac9e-6178c2557ff3'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'P(A) = 0,2, P(B) = 0,5 et P(A ∩ B) = 0,15. A et B sont-ils indépendants ?', 'mcq', '["Non, car 0,2 × 0,5 = 0,1 ≠ 0,15","Oui","Oui, car 0,15 < 0,5","On ne peut pas savoir"]'::jsonb, 0, 'Il faudrait P(A ∩ B) = P(A) × P(B).', 8),
    ('97dc032b-c7ab-5488-a966-e48d2d755e5f'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'L’indépendance de deux événements (de probabilités non nulles) est symétrique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si B est indépendant de A, A est indépendant de B.', 9),
    ('6dd73934-5a7f-5759-97a4-e84f250e2223'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'Deux événements incompatibles de probabilités non nulles sont indépendants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'P(A ∩ B) = 0 alors que P(A) × P(B) > 0.', 10),
    ('e43b55c0-0bff-5f17-83fa-a9ea0f1941e3'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'P(A) = 0,7, P_A(B) = 0,2 et P_Ā(B) = 0,5. Combien vaut P(B) ?', 'mcq', '["0,7","0,29","0,35","0,14"]'::jsonb, 1, '0,7 × 0,2 + 0,3 × 0,5 = 0,14 + 0,15 = 0,29.', 11),
    ('d592ec5d-1d6f-5d01-b63c-3ba10b00c98b'::uuid, 'b10ae8aa-5d10-5c0c-93f7-d1221fcd6ac3'::uuid, 'Que vaut la somme des probabilités des branches issues d’un même nœud ?', 'mcq', '["0","0,5","1","La probabilité du nœud"]'::jsonb, 2, 'Elles couvrent toutes les issues possibles.', 12),
    ('4d7922d5-9914-5757-ac35-0f24a8d13163'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Que représente le coefficient binomial (n k) ?', 'mcq', '["n × k","La probabilité de k succès","Le nombre de chemins à exactement k succès parmi n épreuves","k divisé par n"]'::jsonb, 2, 'C’est sa définition à partir de l’arbre.', 1),
    ('8576d22c-c47b-52ed-8a3f-27867b6a17ae'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Combien vaut (4 2) ?', 'mcq', '["4","8","2","6"]'::jsonb, 3, 'Ligne 4 : 1, 4, 6, 4, 1.', 2),
    ('beaebc4d-7f4a-5574-90cf-adae96371216'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Combien vaut (5 2) ?', 'mcq', '["10","7","5","25"]'::jsonb, 0, 'Ligne 5 : 1, 5, 10, 10, 5, 1.', 3),
    ('cd26b7dc-7037-51ec-bd9c-d706d39d2ee9'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Combien vaut (6 3) ?', 'mcq', '["18","20","15","6"]'::jsonb, 1, 'Ligne 6 : 1, 6, 15, 20, 15, 6, 1.', 4),
    ('0727015d-07c8-5aa8-bbe9-da45d67e3de1'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Combien vaut (10 1) ?', 'mcq', '["1","11","10","0"]'::jsonb, 2, '(n 1) = n : le succès peut être à n places.', 5),
    ('6f7bda4f-bd86-5292-97dc-6aaaa2d8f580'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Combien vaut (7 7) ?', 'mcq', '["7","49","0","1"]'::jsonb, 3, 'Un seul chemin tout en succès.', 6),
    ('4c1abaaf-1a67-5ade-b096-4bd050c06dff'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, '(5 3) est égal à (5 2).', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Symétrie : (n k) = (n n−k).', 7),
    ('f7a8ccbe-ad94-5680-888c-98bdd6e298ad'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Que vaut la somme des nombres de la ligne 4 du triangle de Pascal ?', 'mcq', '["16","8","10","32"]'::jsonb, 0, '1 + 4 + 6 + 4 + 1 = 16 = 2⁴.', 8),
    ('4f3defe0-4eaf-5d4a-9131-4b5037e7973b'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Par la formule de Pascal, (4 1) + (4 2) est égal à…', 'mcq', '["(4 3)","(5 2)","(8 3)","(5 3) + 1"]'::jsonb, 1, '(n k) + (n k+1) = (n+1 k+1).', 9),
    ('5c0c4313-240a-5922-b3bf-2bb1239bc122'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Combien vaut (6 2) ?', 'mcq', '["12","8","15","30"]'::jsonb, 2, 'Ligne 6 : 1, 6, 15… — pas 6 × 2.', 10),
    ('91bb7f14-3a07-55d8-8498-3c2d27d5984c'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Combien vaut (10 9) ?', 'mcq', '["9","90","1","10"]'::jsonb, 3, '(10 9) = (10 1) = 10.', 11),
    ('489433a3-372b-5666-a02a-e3f35bdad0df'::uuid, '5907c616-0c8b-5673-8b55-65bda9d70fdd'::uuid, 'Dans le triangle de Pascal, chaque nombre est…', 'mcq', '["La somme des deux nombres au-dessus","Le produit des deux nombres au-dessus","Le double du nombre au-dessus","Le rang de la ligne"]'::jsonb, 0, 'C’est la formule de Pascal.', 12),
    ('eb41cffd-da33-55d7-9bf1-69c951ccf653'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X suit B(4 ; 0,5). Combien vaut P(X = 2) ?', 'mcq', '["0,5","0,25","0,0625","0,375"]'::jsonb, 3, '6 × 0,5⁴ = 6 × 0,0625.', 1),
    ('3d2549f0-5670-5717-9088-cac8048b1c8a'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X suit B(n ; p). Quelle est son espérance ?', 'mcq', '["n × p","p","n + p","n × (1 − p)"]'::jsonb, 0, 'Résultat admis au programme.', 2),
    ('62bbb223-5258-50a3-bb8c-d3bbcedf167f'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X suit B(10 ; 0,2). Combien vaut E(X) ?', 'mcq', '["0,2","2","8","10"]'::jsonb, 1, '10 × 0,2 = 2.', 3),
    ('8208733f-a26a-507d-b3e1-38aabe5fd0fa'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X suit B(3 ; 0,1). Combien vaut P(X = 0) ?', 'mcq', '["0,1","0,001","0,729","0,271"]'::jsonb, 2, '0,9³ = 0,729.', 4),
    ('356c57f7-0928-549e-bc05-a82bc3de123a'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X suit B(3 ; 0,1). Combien vaut P(X ≥ 1) ?', 'mcq', '["0,729","0,3","0,1","0,271"]'::jsonb, 3, '1 − 0,729.', 5),
    ('79966735-3345-5e79-8bba-a0e8b2bbe817'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X suit B(3 ; 0,1). Combien vaut P(X = 1) ?', 'mcq', '["0,243","0,1","0,081","0,3"]'::jsonb, 0, '3 × 0,1 × 0,81.', 6),
    ('f0eddf3a-6049-51e9-985c-50046eb6cae3'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'Quelle condition n’est PAS nécessaire pour une loi binomiale ?', 'mcq', '["Deux issues par épreuve","Une probabilité de succès égale à 0,5","Des répétitions indépendantes","Des épreuves identiques"]'::jsonb, 1, 'p peut prendre n’importe quelle valeur entre 0 et 1.', 7),
    ('6cb09668-9381-5ed5-80dd-6d5b458eebc6'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'Pour calculer P(X ≥ 1), le plus simple est de calculer…', 'mcq', '["P(X = 1)","P(X = n)","1 − P(X = 0)","E(X)"]'::jsonb, 2, 'On passe par l’événement contraire.', 8),
    ('bf3c4f87-91bd-5038-a3a0-6cfbea99bb39'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X suit B(n ; p). Combien vaut P(X = n) ?', 'mcq', '["(1 − p)^n","n × p","1","p^n"]'::jsonb, 3, 'Un seul chemin : tous les succès.', 9),
    ('17a5c9c9-39d9-5b60-8773-7ef5f41dd0c8'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'Un jeu est équitable si l’espérance du gain est égale à 1.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est équitable si l’espérance est nulle.', 10),
    ('6ba18828-74ac-5669-b0ca-09eacc71a2df'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'X prend les valeurs 0, 5 et 20 avec les probabilités 0,5 ; 0,4 et 0,1. Combien vaut E(X) ?', 'mcq', '["4","8,33","2","25"]'::jsonb, 0, '0 + 2 + 2 = 4.', 11),
    ('b2915508-2751-5e02-81f4-1095af43ec3d'::uuid, '8e5e689f-4ee5-57ea-bebb-208cdb79338a'::uuid, 'Tirer 5 boules SANS remise dans une petite urne et compter les rouges donne une loi binomiale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans remise, les tirages ne sont ni identiques ni indépendants.', 12),
    ('5e4b4d91-4158-53ca-b526-01cc0d8d3a0d'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Que signifiait d’abord le mot latin *ars* ?', 'mcq', '["Une œuvre de musée","Une émotion forte","Un savoir-faire réglé","Un don divin"]'::jsonb, 2, '*Ars* traduit le grec *technè* : l’artisan et l’artiste portaient le même nom.', 1),
    ('e0b52e97-32db-5b6a-af3a-11828b1cf4c6'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Pour Platon, pourquoi la peinture d’un lit est-elle trompeuse ?', 'mcq', '["Elle coûte plus cher que le lit","Elle représente mal les couleurs","Elle est réservée aux riches","Elle ne copie qu’une copie de l’Idée du lit"]'::jsonb, 3, 'Le lit peint imite le lit du menuisier, qui imite l’Idée : trois degrés d’éloignement.', 2),
    ('5ac1082d-371c-5a7f-8203-3e40606e5ff1'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Pour Hegel, la beauté artistique est…', 'mcq', '["Supérieure à la beauté naturelle, car née de l’esprit","Inférieure à la beauté naturelle","Identique à la beauté naturelle","Une pure illusion"]'::jsonb, 0, 'L’œuvre manifeste une idée ; elle porte la marque de l’esprit.', 3),
    ('ff771870-3d79-5ff6-8f85-a5a0b22f2a73'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Selon Bergson, que fait l’artiste ?', 'mcq', '["Il copie fidèlement ce que tout le monde voit","Il dévoile ce que notre regard utilitaire ne voit plus","Il décore les objets utiles","Il invente des mondes sans rapport avec le réel"]'::jsonb, 1, 'Nous percevons les choses selon leur usage ; l’artiste lève ce voile.', 4),
    ('05d70bad-fe27-5380-8dbb-168b98ff13e0'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Chez Kant, le beau est ce qui plaît…', 'mcq', '["À chacun selon ses goûts","Parce que c’est utile","Universellement sans concept","Parce que c’est cher"]'::jsonb, 2, 'Je ne démontre pas qu’une œuvre est belle, mais j’attends l’accord de tous.', 5),
    ('c3ea87a3-cfd9-5613-9bff-b9037a88ebbb'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Le plaisir esthétique est, selon Kant, désintéressé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Je n’ai pas besoin de posséder ou de consommer l’objet pour le trouver beau.', 6),
    ('4f870df3-ad66-58e2-a268-94aa686b07a6'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Quel critère Hume propose-t-il pour reconnaître une grande œuvre ?', 'mcq', '["Son prix de vente","L’avis de son auteur","Le nombre de visiteurs en une année","Qu’elle continue de plaire à travers les époques et les peuples"]'::jsonb, 3, 'Les préjugés d’une époque passent ; la durée de l’admiration fait preuve.', 7),
    ('96546bd7-04d5-557c-b737-dc5cef66856b'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Le génie, chez Kant, est le talent qui…', 'mcq', '["Donne ses règles à l’art","Applique parfaitement les règles existantes","Refuse toute technique","Copie les maîtres anciens"]'::jsonb, 0, 'Il invente une manière que d’autres imiteront.', 8),
    ('94006ecc-010e-544f-a960-7faab476f3ce'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Qu’est-ce qui distingue d’abord l’œuvre d’art de l’objet d’usage ?', 'mcq', '["Le matériau employé","Sa fin : être contemplée et durer, non servir puis s’user","Le temps de fabrication","Le nombre d’exemplaires"]'::jsonb, 1, 'Un objet d’usage est fait pour être consommé ; l’œuvre pour être regardée.', 9),
    ('be2d8040-3901-51aa-9cc1-272ea164df97'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Selon Hannah Arendt, l’œuvre d’art est l’objet le plus ___ du monde humain.', 'mcq', '["Utile","Fragile","Durable","Coûteux"]'::jsonb, 2, 'Elle échappe au cycle de la consommation.', 10),
    ('ecbf337d-c4f6-56d6-ab3f-ef1e92faacc7'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Le proverbe « des goûts et des couleurs on ne discute pas » confond le beau avec…', 'mcq', '["Le vrai","Le bien","L’utile","L’agréable"]'::jsonb, 3, 'L’agréable est personnel ; le beau prétend à l’accord de tous.', 11),
    ('4bb82175-944c-5d74-a966-2ab34872c33a'::uuid, 'f2d6398d-9d95-5c20-b2c8-403f246e3bd6'::uuid, 'Pour Platon, l’art est avant tout une source de vérité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il y voit au contraire une imitation qui éloigne du vrai.', 12),
    ('4dee3806-4c88-5e96-a29f-5bf83b078753'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Est légal ce qui est…', 'mcq', '["Fondé en raison","Approuvé par la majorité","Conforme à la morale","Conforme à la loi en vigueur"]'::jsonb, 3, 'Le légal est un fait : ce que dit la loi à un moment donné.', 1),
    ('c11cb318-512a-5cf7-b120-2a3f8f01a390'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Une loi peut être légale et injuste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les lois de ségrégation étaient légales ; elles n’étaient pas légitimes.', 2),
    ('a011276f-e1c5-5441-b2a4-6f5849b6bef0'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'La justice distributive, chez Aristote, repose sur…', 'mcq', '["Une égalité proportionnelle au mérite ou au besoin","Une égalité arithmétique","Le tirage au sort","La loi du plus fort"]'::jsonb, 0, 'On ne donne pas la même chose à tous, mais à chacun selon ce qui lui revient.', 3),
    ('2681db8c-d851-57f4-8744-921d7443aef9'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Rembourser exactement la somme empruntée relève de la justice…', 'mcq', '["Distributive","Corrective (commutative)","Divine","Équitable"]'::jsonb, 1, 'Dans l’échange, on vise l’égalité arithmétique stricte.', 4),
    ('d2ed8c5c-3bfa-5a18-8b17-dd6ab5d19d39'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Qu’est-ce que l’équité selon Aristote ?', 'mcq', '["Le partage égal de tout","La vengeance proportionnée","Le correctif de la loi là où sa généralité la rend injuste","L’obéissance stricte à la lettre de la loi"]'::jsonb, 2, 'La loi ne peut tout prévoir ; le juge équitable l’adapte au cas.', 5),
    ('94e73078-c1b8-5d0b-add1-f1b325aa0a30'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Que permet l’anneau de Gygès dans le récit de Platon ?', 'mcq', '["Devenir riche","Lire dans les pensées","Voyager dans le temps","Devenir invisible"]'::jsonb, 3, 'L’expérience de pensée demande : serait-on juste sans risque d’être vu ?', 6),
    ('a114b169-9f50-5cee-90a2-922ed0f15646'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, '« Ne pouvant faire que ce qui est juste fût fort, on a fait que ce qui est fort fût juste » est de…', 'mcq', '["Pascal","Rousseau","Rawls","Aristote"]'::jsonb, 0, 'Pascal constate que la force se déguise volontiers en justice.', 7),
    ('fbcff331-098c-5115-a9e3-2781ca276db0'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Pour Rousseau, céder à la force est…', 'mcq', '["Un devoir moral","Un acte de nécessité, non de devoir","Le fondement du droit","Une preuve de justice"]'::jsonb, 1, 'Si la force faisait le droit, le droit changerait avec chaque nouveau plus fort.', 8),
    ('becb4d0b-9e64-5558-a620-bfaf9418fd2f'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Le « voile d’ignorance » est une expérience de pensée de…', 'mcq', '["Platon","Pascal","John Rawls","Aristote"]'::jsonb, 2, 'On choisit les règles sans savoir quelle place on occupera dans la société.', 9),
    ('659446aa-2130-5e3f-98e0-ad0f8b0c0b82'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Derrière le voile d’ignorance, quelles inégalités Rawls juge-t-il acceptables ?', 'mcq', '["Toutes, si elles sont légales","Aucune","Celles qui récompensent la naissance","Celles qui profitent aux plus défavorisés"]'::jsonb, 3, 'C’est son « principe de différence ».', 10),
    ('9c9f1daf-eb56-5874-8e73-55db075b545e'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Est ___ ce qui est fondé en justice, même si aucune loi ne le prévoit.', 'mcq', '["Légitime","Légal","Réglementaire","Obligatoire"]'::jsonb, 0, 'Le légitime renvoie à un principe, le légal à un texte.', 11),
    ('fdba8c79-962d-5ac6-97c7-3125e402259f'::uuid, 'ab032fec-0548-59a0-9c3b-6cb08d4853df'::uuid, 'Pour Platon, l’homme injuste qui échappe aux sanctions est pleinement heureux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il reste désordonné en lui-même : l’injustice est un désordre de l’âme.', 12),
    ('6228d9b1-670b-5dee-92c3-8c1e0fda3876'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Quel est le contraire du libre arbitre ?', 'mcq', '["Le déterminisme","La loi","La politique","Le désir"]'::jsonb, 0, 'Le déterminisme soutient que tout choix a des causes qui ne viennent pas de nous.', 1),
    ('6f99c377-9576-586c-a005-ac5e5c77e612'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Pour Épictète, qu’est-ce qui dépend de nous ?', 'mcq', '["Notre santé","Nos jugements et nos désirs","Notre réputation","Notre fortune"]'::jsonb, 1, 'La liberté stoïcienne se joue dans ce que nous pensons des choses.', 2),
    ('1a948bc7-cf4a-5162-9149-5c77f1337853'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Descartes voit dans la liberté d’indifférence…', 'mcq', '["Le plus haut degré de la liberté","Une illusion totale","Le plus bas degré de la liberté","Un privilège des rois"]'::jsonb, 2, 'Choisir sans raison est une liberté pauvre : on est plus libre quand on voit clairement le bien.', 3),
    ('27a62e52-ae54-51cd-8f78-28d5498c0403'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Selon Spinoza, pourquoi les hommes se croient-ils libres ?', 'mcq', '["Dieu leur a donné le libre arbitre","Les lois les protègent","Ils vivent en démocratie","Ils sont conscients de leurs actions et ignorants des causes qui les déterminent"]'::jsonb, 3, 'L’exemple de la pierre qui se croirait libre de voler illustre cette illusion.', 4),
    ('7e588d5a-e534-5cdb-9e82-59c2cec21adf'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, '« L’homme est condamné à être libre » est une formule de…', 'mcq', '["Sartre","Rousseau","Descartes","Montesquieu"]'::jsonb, 0, 'Sans nature fixée d’avance, l’homme se fait par ses choix.', 5),
    ('f515c1b7-b6fd-58d9-a9da-f302992535c3'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Pour Sartre, ne pas choisir est encore un choix.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne peut se décharger de sa liberté sur les circonstances.', 6),
    ('beb71011-5233-5d20-805d-98f9a5417070'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Montesquieu définit la liberté politique comme…', 'mcq', '["L’absence de toute loi","Le droit de faire tout ce que les lois permettent","Le pouvoir de faire ce qu’on veut","L’obéissance au roi"]'::jsonb, 1, 'Sans loi, chacun serait exposé à la volonté des autres.', 7),
    ('bd7baf3f-74c4-5e15-a879-08d982617671'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Pour Rousseau, « l’obéissance à la loi qu’on s’est ___ est liberté ».', 'mcq', '["Imposée","Refusée","Prescrite","Oubliée"]'::jsonb, 2, 'Le citoyen obéit à une loi qu’il a contribué à faire.', 8),
    ('afc6757f-5be8-5c75-8a1e-9a25c9a50a26'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Le fumeur qui ne peut pas s’arrêter illustre…', 'mcq', '["Une liberté parfaite","La liberté politique","Le libre arbitre selon Descartes","Le fait que céder à ses envies n’est pas forcément être libre"]'::jsonb, 3, 'Obéir à un besoin, c’est être dominé par lui.', 9),
    ('7a65ff10-47f0-59a2-a709-1ecd30720413'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Pour Spinoza, être libre, c’est…', 'mcq', '["Agir par la nécessité de sa propre nature comprise","Agir sans aucune cause","Obéir à ses caprices","Refuser toutes les lois"]'::jsonb, 0, 'La liberté n’est pas l’absence de causes mais la compréhension de celles qui nous font agir.', 10),
    ('3c3f27b3-2936-5ba1-a194-edf9502d37ef'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Dans une copie, pourquoi faut-il distinguer les sens du mot « liberté » ?', 'mcq', '["Pour allonger la copie","Parce qu’ils posent des problèmes différents qu’on confond facilement","Parce que le correcteur l’exige par principe","Parce qu’un seul sens est au programme"]'::jsonb, 1, 'Être empêché, être déterminé et être gouverné sont trois questions distinctes.', 11),
    ('66d708e5-76ea-5a7b-b72c-583c59ef961e'::uuid, '33dbee40-5d40-517e-8e78-67fc9de4aa06'::uuid, 'Pour Rousseau, la loi est l’ennemie de la liberté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une loi juste et commune protège de la domination du plus fort.', 12),
    ('27f8df57-9b61-52df-b0d9-aa8e19351883'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Pour Aristote, qu’est-ce qui distingue un être naturel d’un objet technique ?', 'mcq', '["Sa taille","Il a en lui-même le principe de son mouvement","Sa couleur","Il est plus ancien"]'::jsonb, 1, 'L’arbre pousse seul ; le lit ne pousse pas, il est fabriqué.', 1),
    ('736c484d-bbef-55c1-a2c4-a8f6028f13c9'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Dans « la nature du triangle », le mot nature désigne…', 'mcq', '["Les forêts","Le paysage","L’essence de la chose","Ce qui est sauvage"]'::jsonb, 2, 'C’est l’ensemble des propriétés qui font qu’un triangle est un triangle.', 2),
    ('5ebf07d5-1ac8-590f-84cd-476bb0e58508'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Descartes veut rendre l’homme « comme maître et ___ de la nature ».', 'mcq', '["Serviteur","Gardien","Ennemi","Possesseur"]'::jsonb, 3, 'Le programme moderne : connaître la nature pour agir sur elle.', 3),
    ('715bb05f-8f38-5c5b-9e32-5e39d189fd98'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Pour Descartes, à quoi doit d’abord servir la maîtrise de la nature ?', 'mcq', '["À conserver la santé","À faire la guerre","À s’enrichir","À construire des villes"]'::jsonb, 0, 'La médecine est pour lui le premier bien visé.', 4),
    ('f5985edc-bc77-59d0-b31b-f6bd82cf6bae'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Hans Jonas fonde une éthique de…', 'mcq', '["La domination de la nature","La responsabilité envers les générations futures","Le plaisir immédiat","L’obéissance religieuse"]'::jsonb, 1, 'Le pouvoir technique engage désormais ceux qui ne sont pas encore nés.', 5),
    ('754c6459-9517-5b65-8715-a8e114efb94d'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Selon Rousseau, qu’est-ce qui distingue l’homme de l’animal ?', 'mcq', '["La force","L’instinct","La perfectibilité","La vie en groupe"]'::jsonb, 2, 'L’homme se transforme au cours de sa vie et de l’histoire.', 6),
    ('0aa4024b-c881-5215-8106-c365cba74034'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, '« L’existence précède l’essence » signifie que…', 'mcq', '["L’homme a une nature fixée d’avance","L’animal est supérieur à l’homme","La nature n’existe pas","L’homme se définit par ce qu’il fait"]'::jsonb, 3, 'Pour Sartre, aucune nature humaine ne décide à notre place.', 7),
    ('035ae652-c8c4-5b68-a984-ac0d37814eb9'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Pour Merleau-Ponty, chez l’homme…', 'mcq', '["Tout est fabriqué et tout est naturel","Tout est naturel, rien n’est fabriqué","Tout est fabriqué, rien n’est naturel","Seul le corps est naturel"]'::jsonb, 0, 'Nos besoins naturels sont toujours mis en forme par une culture.', 8),
    ('123466dd-eecc-5cd8-9dfc-bbc825a14efb'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Selon Lévi-Strauss, ce qui est universel chez l’homme relève de la culture.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’universel relève de la nature ; la règle, de la culture.', 9),
    ('5f0893b1-14f4-5bc1-a826-699b8da5ebbb'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Pourquoi la prohibition de l’inceste est-elle un cas remarquable pour Lévi-Strauss ?', 'mcq', '["Elle n’existe que dans une seule société","Elle est à la fois une règle et universelle","Elle est purement biologique","Elle a disparu"]'::jsonb, 1, 'Règle (culture) et universelle (nature) : elle marque le passage de l’une à l’autre.', 10),
    ('b36df2f3-2f75-5563-a4d3-b6d55e8869a4'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Un produit « 100 % naturel » utilise le mot nature au sens de…', 'mcq', '["L’essence d’une chose","La nature humaine","Ce qui n’a pas été transformé par l’homme","Le principe de mouvement"]'::jsonb, 2, 'C’est le sens courant : ce qui existe sans intervention humaine.', 11),
    ('0b96c23c-2ed9-569a-ad50-9be1a810d626'::uuid, 'a3560e6b-3577-5931-97b6-851963d37d1b'::uuid, 'Pour les stoïciens, bien vivre, c’est vivre en accord avec la nature.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La nature y est un ordre rationnel qu’il faut suivre.', 12),
    ('19db9d52-ae46-5222-afa9-1a7dc65cd476'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Le latin *religare* signifie…', 'mcq', '["Relire","Refuser","Relier","Réfléchir"]'::jsonb, 2, 'La religion relie l’homme à Dieu et les croyants entre eux.', 1),
    ('21c7f1f5-4fe2-5f88-bee1-0ab22e362f0a'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Chez Durkheim, la religion est d’abord liée à…', 'mcq', '["L’économie","La science","La guerre","La distinction du sacré et du profane"]'::jsonb, 3, 'Les choses sacrées sont séparées et entourées d’interdits.', 2),
    ('271da6e4-67f5-5ed8-8c56-ea5d0964ecf0'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Pour Durkheim, une religion unit ses fidèles en une même…', 'mcq', '["Communauté morale","Entreprise","Nation","Famille biologique"]'::jsonb, 0, 'C’est sa dimension collective : la religion fait lien.', 3),
    ('3e8777eb-7082-5874-b0d2-940615788c88'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, '« Le cœur a ses raisons que la raison ne connaît point » est de…', 'mcq', '["Kant","Pascal","Marx","Durkheim"]'::jsonb, 1, 'Pour Pascal, Dieu est sensible au cœur plus qu’à la démonstration.', 4),
    ('80d08e7f-4abc-50ec-b3ec-d7d54ab9e95f'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Pour Thomas d’Aquin, la foi et la raison…', 'mcq', '["Se contredisent toujours","Sont sans rapport","Ne peuvent se contredire, car elles viennent toutes deux de Dieu","Doivent être séparées par la loi"]'::jsonb, 2, 'La raison démontre certaines vérités, la foi en reçoit d’autres.', 5),
    ('f809efeb-affc-59e9-ab34-85e4c285fe9c'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Selon Kant, la raison peut démontrer que Dieu existe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne peut ni le prouver ni le réfuter : il faut limiter le savoir pour faire place à la croyance.', 6),
    ('238d62f5-71cc-5564-bb87-c6ab729356c3'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Que dit le pari de Pascal ?', 'mcq', '["Qu’il faut jouer aux jeux de hasard","Que Dieu n’existe pas","Que la foi est inutile","Que croire en Dieu est le choix le plus raisonnable pour qui doute"]'::jsonb, 3, 'On a tout à gagner et presque rien à perdre en pariant que Dieu existe.', 7),
    ('d4ad2eae-0ea9-5bbc-a37d-d19ef361fa72'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Qui a écrit que la religion est « l’opium du peuple » ?', 'mcq', '["Marx","Freud","Feuerbach","Pascal"]'::jsonb, 0, 'Elle console d’une misère réelle au lieu de la transformer, selon lui.', 8),
    ('18966929-96d3-5d58-ac95-7e3d71ef9d0a'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Pour Freud, la croyance religieuse est…', 'mcq', '["Une erreur de calcul","Une illusion née du désir de protection","Une vérité démontrée","Une invention des prêtres"]'::jsonb, 1, 'Une illusion est une croyance motivée par un désir.', 9),
    ('cd25dc94-d930-550a-bdcf-89576887d061'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Montrer la cause psychologique d’une croyance suffit à prouver qu’elle est fausse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’origine d’une croyance et sa vérité sont deux questions distinctes.', 10),
    ('21b21393-2d16-5f32-ba59-834d528cfc19'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'En France, la loi de séparation des Églises et de l’État date de…', 'mcq', '["1789","1848","1905","1958"]'::jsonb, 2, 'La laïcité garantit la liberté de conscience et la neutralité de l’État.', 11),
    ('b6b89225-9b04-59a0-b547-665006999b55'::uuid, '5b37be6c-821b-5a6b-952c-8ecc12c860e4'::uuid, 'Pour Feuerbach, l’homme ___ en Dieu ses propres qualités idéalisées.', 'mcq', '["Oublie","Cache","Refuse","Projette"]'::jsonb, 3, 'Dieu serait l’image agrandie de l’homme.', 12),
    ('618160fe-f40d-5d4e-a4d3-dc1e964cf119'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Quelle est la question propre à la technique ?', 'mcq', '["Pourquoi les choses sont-elles ainsi ?","Qu’est-ce que le beau ?","Qu’est-ce que Dieu ?","Comment obtenir un résultat ?"]'::jsonb, 3, 'La science cherche à connaître ; la technique cherche à produire.', 1),
    ('bb9ac756-0b0b-5c49-9905-0ce2c4a39c74'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'La technique est apparue bien avant la science moderne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le feu et les outils de pierre précèdent de loin toute théorie.', 2),
    ('6e99b7d7-90fb-527a-90f2-323dcbe4082f'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Dans le mythe de Prométhée, pourquoi l’homme a-t-il besoin de la technique ?', 'mcq', '["Parce qu’il naît nu et démuni","Pour s’enrichir","Pour dominer les dieux","Pour faire la guerre"]'::jsonb, 0, 'Le feu et les arts compensent un oubli dans la distribution des qualités.', 3),
    ('fc0f37ce-9a2c-5ab4-aa09-9a553af28cce'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Bergson propose d’appeler l’espèce humaine…', 'mcq', '["*Homo sapiens*","*Homo faber*","*Homo ludens*","*Homo economicus*"]'::jsonb, 1, 'L’intelligence humaine se reconnaît d’abord à la fabrication d’outils.', 4),
    ('9a3eb775-8017-52f8-9f2a-3811c63f1fde'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Selon Marx, à l’usine, l’ouvrier devient…', 'mcq', '["Le maître de la machine","Un artiste","L’appendice de la machine","Un ingénieur"]'::jsonb, 2, 'Ce n’est plus lui qui guide l’instrument, c’est la machine qui l’emploie.', 5),
    ('6382dcfd-6fcc-58e1-af47-dd807756d842'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Pour Simondon, qu’est-ce qui nous rend esclaves des objets techniques ?', 'mcq', '["Leur prix","Leur nombre","Leur beauté","Notre ignorance de leur fonctionnement"]'::jsonb, 3, 'Comprendre la technique, c’est cesser de la subir.', 6),
    ('f7be5abf-f797-5113-a58b-0f93fa23fd90'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Pour Heidegger, la technique moderne est un outil neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle impose un regard qui voit tout comme une ressource disponible.', 7),
    ('3c16082a-7ecb-50fc-9141-55c5ae4bf207'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Quel exemple illustre l’idée que la technique n’est qu’un moyen ?', 'mcq', '["Un couteau peut servir à cuisiner ou à tuer","Un fleuve devient une centrale électrique","L’ouvrier suit le rythme de la machine","Le climat se réchauffe"]'::jsonb, 0, 'Selon cette thèse, tout dépend de l’usage qu’on en fait.', 8),
    ('0acad834-2e0e-54a3-946a-e499a868712c'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Le « principe responsabilité » est une idée de…', 'mcq', '["Descartes","Hans Jonas","Bergson","Marx"]'::jsonb, 1, 'Nos actions techniques engagent la vie humaine future sur terre.', 9),
    ('af153a2c-e348-5de6-8298-d68e0056b60a'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Quel mot désigne aujourd’hui l’union étroite de la science et de la technique ?', 'mcq', '["Artisanat","Mécanique","Technoscience","Magie"]'::jsonb, 2, 'La recherche et l’application ne se séparent presque plus.', 10),
    ('9406ec12-4162-5997-8088-11256e6020a2'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'La technique a pour critère ___, la science a pour critère le vrai.', 'mcq', '["Le beau","Le sacré","Le juste","L’efficace"]'::jsonb, 3, 'Un procédé technique se juge à son résultat.', 11),
    ('2393779b-df32-5264-a508-c93a84e7be68'::uuid, '7bf61140-114e-5fc1-9c06-c5ead6140ffb'::uuid, 'Que distingue-t-on entre l’outil et la machine ?', 'mcq', '["L’outil prolonge la main guidée par l’homme ; la machine fait le geste à sa place","L’outil est électrique, la machine non","Il n’y a aucune différence","La machine est plus ancienne"]'::jsonb, 0, 'Avec la machine, le rapport entre l’homme et l’instrument s’inverse.', 12),
    ('909703fa-c8bb-5ebd-ae5b-fb25c7ea9669'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'La vérité est une qualité…', 'mcq', '["De nos jugements et de nos énoncés","Des choses elles-mêmes","Des images seulement","Des émotions"]'::jsonb, 0, 'Une chose est réelle ou non ; c’est ce qu’on en dit qui est vrai ou faux.', 1),
    ('f7d6f550-3cea-56a9-862b-5b9923460a76'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Le critère de la correspondance définit le vrai comme…', 'mcq', '["Ce qui plaît au plus grand nombre","L’accord de l’énoncé avec la chose","Ce qui est utile","Ce que dit l’autorité"]'::jsonb, 1, 'Thomas d’Aquin parle d’adéquation de l’intelligence et de la chose.', 2),
    ('165fd37f-fe4d-501c-8407-01bb88063920'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Pour Descartes, le critère du vrai est…', 'mcq', '["La tradition","L’utilité","L’évidence de ce que je conçois clairement et distinctement","Le vote"]'::jsonb, 2, 'L’évidence résiste au doute méthodique.', 3),
    ('cd8722d8-0072-5969-88ce-fa310cea3a2e'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Quelle est la différence entre l’erreur et le mensonge ?', 'mcq', '["Aucune","Le mensonge est toujours plus grave","L’erreur concerne les sciences seulement","L’erreur est involontaire, le mensonge est une volonté de tromper"]'::jsonb, 3, 'On peut dire faux sans mentir, et mentir en disant vrai.', 4),
    ('97f1d71e-5361-5ead-8cc3-dfcf33662aaf'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Dans l’allégorie de la caverne, les prisonniers prennent…', 'mcq', '["Des ombres pour la réalité","Le soleil pour une lampe","Des livres pour des images","Leurs rêves pour des souvenirs"]'::jsonb, 0, 'Platon y montre la condition de l’homme prisonnier de l’opinion.', 5),
    ('805e6dd9-6a43-5057-8605-fa97170085df'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, '« L’opinion pense mal ; elle ne pense pas » est de…', 'mcq', '["Platon","Bachelard","Nietzsche","Kant"]'::jsonb, 1, 'Pour Bachelard, l’opinion traduit des besoins en connaissances.', 6),
    ('9a9ec801-0310-5db0-b130-4bfb071ea5bc'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Selon Popper, une théorie scientifique doit être…', 'mcq', '["Vérifiée définitivement","Acceptée par tous","Réfutable","Ancienne"]'::jsonb, 2, 'Elle doit pouvoir être mise à l’épreuve par l’expérience.', 7),
    ('d10c6a6b-562e-5f68-8136-2288e8a4eb2a'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Observer mille cygnes blancs prouve définitivement que tous les cygnes sont blancs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un seul cygne noir suffit à réfuter l’énoncé.', 8),
    ('6397afc1-095f-589b-b899-28fd065b6c77'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Pourquoi l’affirmation « tout est relatif » pose-t-elle problème ?', 'mcq', '["Elle est trop longue","Elle est prouvée par la science","Elle vient de Descartes","Elle prétend être vraie absolument, ce qu’elle nie"]'::jsonb, 3, 'Le relativisme absolu se contredit lui-même.', 9),
    ('542e1096-ad8f-5665-985e-8320f094d953'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Pour Kant, a-t-on le droit de mentir pour sauver un ami ?', 'mcq', '["Non : le mensonge ruine la confiance dont dépend toute parole","Oui, toujours","Oui, si l’ami est innocent","Seulement devant un juge"]'::jsonb, 0, 'Benjamin Constant lui objecte qu’on ne doit la vérité qu’à qui y a droit.', 10),
    ('12910240-6618-5693-9141-00a71e15d1d2'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Une photographie retouchée est ___ mais elle n’est pas vraie.', 'mcq', '["Fausse","Réelle","Illusoire","Absente"]'::jsonb, 1, 'Elle existe bien : c’est ce qu’elle prétend montrer qui est faux.', 11),
    ('df92e714-e404-5f4c-8055-9b2f54dcfd6d'::uuid, '7c50b384-2f2b-5764-a5e7-92f136c186c7'::uuid, 'Le contraire de la vérité est l’apparence.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le contraire de la vérité est l’erreur (ou le mensonge) ; l’apparence s’oppose à la réalité.', 12),
    ('931d97d0-88b8-5206-95b8-ffabdbc4c0e0'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Un sujet de dissertation au bac porte-t-il directement sur un repère ?', 'mcq', '["Oui, toujours","Non, jamais directement, mais son intitulé peut en employer un terme","Oui, une année sur deux","Seulement en explication de texte"]'::jsonb, 1, 'Les sujets portent sur les notions ; les repères aident à les traiter.', 1),
    ('371a10d0-dfa4-5434-8926-02a9a1ccb3f1'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Que suffit-il pour réfuter une règle générale ?', 'mcq', '["Un exemple","Une métaphore","Un contre-exemple","Une hypothèse"]'::jsonb, 2, 'Mille exemples ne prouvent pas une règle, un seul contre-exemple la réfute.', 2),
    ('fecb55be-091a-5e46-b142-a5a75079f782'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Persuader, c’est…', 'mcq', '["Faire admettre par des raisons","Démontrer une vérité","Vérifier par l’expérience","Faire croire en touchant les passions"]'::jsonb, 3, 'Convaincre passe par des raisons ; persuader peut s’en passer.', 3),
    ('0ba41ec6-c049-5680-b305-7e8eba93d375'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Savoir se distingue de croire parce que…', 'mcq', '["On peut justifier ce qu’on sait","On le dit plus fort","C’est plus ancien","C’est partagé par tous"]'::jsonb, 0, 'Le savoir s’accompagne de raisons suffisantes.', 4),
    ('e6be9e70-e40a-5fe0-9059-271e5e12120e'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'On peut être certain et se tromper.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La certitude est un état de l’esprit ; la vérité dépend du réel.', 5),
    ('f495e641-b62d-5b92-816f-728e578e47f2'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Expliquer, au sens de ce repère, c’est…', 'mcq', '["Saisir une intention","Rendre compte par des causes","Raconter une histoire","Donner son avis"]'::jsonb, 1, 'Comprendre, c’est saisir un sens ; expliquer, rendre compte par des causes.', 6),
    ('d1d12a3b-d2a7-58e4-acf1-ca0c35ceb5b8'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, '« Le vieillard est au soir de sa vie » repose sur…', 'mcq', '["Une preuve","Une hypothèse","Une analogie de rapports (la vieillesse est à la vie ce que le soir est au jour)","Une analyse"]'::jsonb, 2, 'L’analogie est une identité de rapports, non une simple ressemblance.', 7),
    ('aa19b818-0098-5ee5-b1be-769bfda730ed'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Que désigne le couple « en fait / en droit » ?', 'mcq', '["Le passé / le futur","Le vrai / le faux","Le concret / l’abstrait","Ce qui est / ce qui doit être ou est fondé"]'::jsonb, 3, 'Ce qui se passe n’est pas forcément ce qui devrait se passer.', 8),
    ('b2f31dac-75d9-5f44-8a52-2aacbfe71392'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Une connaissance intuitive est…', 'mcq', '["Saisie d’un coup d’œil","Obtenue par une suite d’étapes","Toujours fausse","Transmise par un autre"]'::jsonb, 0, 'Le discursif, lui, procède par étapes.', 9),
    ('a1c14bed-2d5c-580d-8f86-956cfea657cf'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Ce qui vaut pour tous les sujets capables d’en discuter est…', 'mcq', '["Subjectif","Intersubjectif","Immédiat","Matériel"]'::jsonb, 1, 'L’intersubjectif dépasse l’opinion individuelle sans prétendre à l’objectivité d’une chose.', 10),
    ('18dc88ae-570b-52f7-9a46-46947d42a9bf'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Décomposer un tout en ses éléments, c’est faire ___.', 'mcq', '["Une synthèse","Une métaphore","Une analyse","Une conclusion"]'::jsonb, 2, 'La synthèse fait le chemin inverse : recomposer.', 11),
    ('70225cf4-4dde-5c65-aa70-694666aeda19'::uuid, '631fdb8c-58e8-5fe4-873a-5b211afa4737'::uuid, 'Quelle est la bonne façon d’utiliser un repère dans une copie ?', 'mcq', '["Réciter sa définition en introduction","En citer le plus possible","Le mettre en titre de partie","L’employer pour distinguer deux sens et faire apparaître le problème"]'::jsonb, 3, 'Un repère est un outil qui doit travailler dans l’argument.', 12),
    ('d716d607-f408-5b64-bfe7-e6307c81324f'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Pour l’homme, être blond est…', 'mcq', '["Essentiel","Nécessaire","Accidentel","Universel"]'::jsonb, 2, 'Il pourrait changer sans que la personne cesse d’être un homme.', 1),
    ('f5edc2af-6d48-596e-8e7f-9fdca3d85886'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Le gland est un chêne…', 'mcq', '["En acte","Par accident","En droit","En puissance"]'::jsonb, 3, 'Il peut devenir chêne, il ne l’est pas encore.', 2),
    ('16e0b4b6-ea6f-5d99-8059-807bb66ed535'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Est contingent ce qui…', 'mcq', '["Pourrait ne pas être","Ne peut pas ne pas être","Est impossible","Est universel"]'::jsonb, 0, 'Le nécessaire, lui, ne peut pas être autrement.', 3),
    ('cbbb60ae-8893-53f9-a239-b8b1a3d2d944'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Deux citoyens égaux en droits sont identiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’égalité n’est pas l’identité : on peut être très différents et égaux en droits.', 4),
    ('00107f30-df3b-57b1-b0e2-b7f860b5b9d9'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Quelle est la différence entre obligation et contrainte ?', 'mcq', '["Aucune","L’obligation peut être refusée librement, la contrainte s’impose par la force","La contrainte est morale, l’obligation physique","L’obligation est toujours injuste"]'::jsonb, 1, 'Un devoir s’adresse à ma liberté ; une contrainte la supprime.', 5),
    ('7b7a9157-b608-5ec4-b30b-6218a391236c'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Le fondement d’une règle désigne…', 'mcq', '["Son commencement dans le temps","Son auteur","Ce qui la justifie en droit","Sa date de publication"]'::jsonb, 2, 'L’origine dit d’où elle vient ; le fondement dit ce qui la rend valable.', 6),
    ('cd5ead9a-3692-53ed-819c-626a0957339f'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Dans la série genre / espèce / individu, « Socrate » est…', 'mcq', '["Un genre","Une espèce","Un concept universel","Un individu"]'::jsonb, 3, 'Animal est le genre, homme l’espèce, Socrate l’individu.', 7),
    ('2816f9d3-2134-5828-a76c-7dba108a4ba8'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Ce qui vaut pour la plupart des cas, mais pas pour tous, est…', 'mcq', '["Général","Universel","Singulier","Nécessaire"]'::jsonb, 0, 'L’universel ne souffre aucune exception, le général en admet.', 8),
    ('2f47431d-002c-5dfa-8d17-ea0d4c86aec8'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'La colère que je subis relève plutôt de…', 'mcq', '["L’action","La passion","Le fondement","La fin"]'::jsonb, 1, 'La passion est ce que l’on subit ; l’action, ce dont on est l’auteur.', 9),
    ('fa09443f-2a96-59d5-b871-925296b3f607'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Ce qui reste extérieur et supérieur à la chose est dit ___.', 'mcq', '["Immanent","Relatif","Transcendant","Accidentel"]'::jsonb, 2, 'L’immanent, au contraire, est intérieur à la chose même.', 10),
    ('f5491b74-484d-5a0e-b4d6-98bd59b10659'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Connaître l’origine d’une loi suffit pour juger de sa valeur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’origine est un fait ; la valeur relève du fondement.', 11),
    ('59860f01-b5f9-5639-a519-8190d6eb22db'::uuid, 'f86fa9b8-ae65-543d-9b30-3f68eaa08fda'::uuid, 'Dans le sujet « Obéir, est-ce renoncer à sa liberté ? », quel repère débloque le problème ?', 'mcq', '["Genre / espèce / individu","En acte / en puissance","Formel / matériel","Obligation / contrainte"]'::jsonb, 3, 'Obéir à une obligation reconnue n’est pas subir une contrainte.', 12),
    ('1c9ad9f6-1d8c-509b-8de6-644eb9442c90'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Combien de temps dure l’épreuve de philosophie du bac technologique ?', 'mcq', '["2 heures","3 heures","5 heures","4 heures"]'::jsonb, 3, 'Quatre heures, pour un seul sujet choisi parmi trois.', 1),
    ('343d1ee4-8e2e-5afe-bf06-fa242183d00c'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Quel est le coefficient de la philosophie au bac technologique ?', 'mcq', '["4","2","8","16"]'::jsonb, 0, 'Il est de 4 en voie technologique (8 en voie générale).', 2),
    ('4bfc12cd-ef01-5bee-af7f-92271129a88b'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Combien de sujets de dissertation sont proposés ?', 'mcq', '["Un","Deux","Trois","Quatre"]'::jsonb, 1, 'Deux dissertations et une explication de texte : trois sujets au choix.', 3),
    ('e31f15a1-939f-52db-86bc-0ae9349d127f'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Sous quelle forme se présente toujours un sujet de dissertation ?', 'mcq', '["Une citation à commenter","Un thème","Une question","Un texte"]'::jsonb, 2, 'Et les notions qu’il interroge sont clairement identifiables.', 4),
    ('d5f3337a-5fce-5538-b643-36949b1e04a3'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, '« Peut-on… ? » interroge plutôt…', 'mcq', '["Une obligation","Un fait historique","Une préférence personnelle","Une possibilité ou un droit"]'::jsonb, 3, '« Doit-on… ? » interroge une obligation.', 5),
    ('feafcc8b-ae39-5637-8a2a-02462f612807'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'D’où naît le problème d’une dissertation ?', 'mcq', '["D’une tension entre deux réponses qui semblent vraies à la fois","D’une erreur dans le sujet","De l’avis du candidat","D’une citation célèbre"]'::jsonb, 0, 'Si la réponse est évidente, le problème n’est pas encore trouvé.', 6),
    ('79a06dd7-7921-55d0-968f-82f2c0f98552'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Que doit faire une transition entre deux parties ?', 'mcq', '["Résumer tout le cours","Montrer pourquoi la réponse précédente ne suffit pas","Annoncer la conclusion","Citer un auteur"]'::jsonb, 1, 'Elle fait avancer la réflexion d’une partie à l’autre.', 7),
    ('62b269be-7d9d-56a8-b97a-418414b73d2d'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'La conclusion peut introduire une idée entièrement nouvelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle donne la réponse au problème, sans relancer un nouveau débat.', 8),
    ('d084ac74-87a5-58cd-addd-78e3d34fcd19'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Donner deux sens aux termes du sujet sert à…', 'mcq', '["Allonger l’introduction","Montrer qu’on connaît le dictionnaire","Faire apparaître le problème","Éviter de répondre"]'::jsonb, 2, 'C’est souvent l’écart entre deux sens qui crée la tension.', 9),
    ('d98dad05-c317-5686-a685-d7cc3ebb58f9'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Quel est le défaut d’une citation non expliquée ?', 'mcq', '["Elle est interdite","Elle fait perdre du temps au correcteur","Elle est toujours fausse","Elle ne sert aucun argument"]'::jsonb, 3, 'Une référence doit être expliquée et mise au service de ta thèse.', 10),
    ('7d2d2cc1-75dc-5710-9f9a-72d79427ac32'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Une copie qui donne son avis sans le justifier est une bonne dissertation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une opinion ne devient réflexion que par des arguments.', 11),
    ('8e476e99-55ce-56c6-bef5-6240da40538f'::uuid, 'ad92ff7e-9254-5c36-86e9-7d046ad5c514'::uuid, 'Que doit contenir l’introduction ?', 'mcq', '["Une accroche, le sujet, l’analyse des termes, le problème et l’annonce du plan","Uniquement la réponse finale","La liste des auteurs connus","Une biographie de philosophe"]'::jsonb, 0, 'Elle mène le lecteur jusqu’au problème et annonce le chemin.', 12),
    ('7c821c07-11cb-5462-b18e-974a271ecf9b'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Sur quel auteur peut porter le texte à expliquer ?', 'mcq', '["Un auteur de la liste du programme","N’importe quel écrivain","Un journaliste contemporain","Uniquement un auteur antique"]'::jsonb, 0, 'Les extraits sont obligatoirement empruntés à la liste d’auteurs du programme.', 1),
    ('4c5943a4-66f6-59fe-8fbc-f0bc7e0bffdf'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'En voie technologique, combien de manières de rédiger l’explication te sont proposées ?', 'mcq', '["Une seule","Deux","Trois","Quatre"]'::jsonb, 1, 'Répondre aux questions (option 1) ou suivre son propre développement (option 2).', 2),
    ('b2ac9cbe-21ff-5503-972e-c5a7605eb785'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Où dois-tu indiquer l’option choisie ?', 'mcq', '["À la fin de la copie","Nulle part","Au début de la copie","Sur une feuille à part"]'::jsonb, 2, 'Le correcteur doit savoir d’emblée comment lire ta copie.', 3),
    ('97011f0b-1ce8-5a03-9cbc-1f682fff64b6'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Que demande le bloc « éléments de synthèse » ?', 'mcq', '["Une réflexion personnelle","La biographie de l’auteur","Un résumé ligne à ligne","La question du texte, ses moments et son idée principale"]'::jsonb, 3, 'C’est la vue d’ensemble du texte.', 4),
    ('6531872f-b2b0-5350-bd81-7f71761b2619'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Que demande le bloc « commentaire » ?', 'mcq', '["Une réflexion personnelle argumentée sur le problème du texte","Recopier le texte","La date de publication","La liste des connecteurs"]'::jsonb, 0, 'Tu prends position en argumentant, avec des exemples.', 5),
    ('5faf588e-ba72-5ec9-b5f3-2ad7664a6694'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'En option 1, il faut traiter les questions dans l’ordre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On répond dans l’ordre, de manière précise et développée.', 6),
    ('32b88ea0-de54-5605-a761-2eaa7c09c4a3'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Qu’est-ce que la paraphrase ?', 'mcq', '["Une explication réussie","Répéter le texte avec d’autres mots sans l’expliquer","Une citation exacte","Un plan en trois parties"]'::jsonb, 1, 'Reformuler ne suffit pas : il faut dire pourquoi l’auteur dit ce qu’il dit.', 7),
    ('1c573325-7b7a-58e9-ab3a-839f8c34941a'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Quels mots aident le plus à découper un texte en moments ?', 'mcq', '["Les noms propres","Les adjectifs","Les connecteurs logiques","Les dates"]'::jsonb, 2, '« Mais », « donc », « car », « au contraire » marquent les articulations.', 8),
    ('8724a03e-12d5-50d6-aad2-d036348263e7'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Pourquoi faire le bloc B au brouillon avant le bloc A ?', 'mcq', '["Parce que le sujet l’impose","Pour gagner des points bonus","Parce que le bloc A est facultatif","Parce qu’on explique mieux un détail quand on sait où va le texte"]'::jsonb, 3, 'La thèse d’ensemble éclaire chaque passage.', 9),
    ('f753eed9-b413-59d8-98e3-dd0e96a8b299'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Pour expliquer un passage, on le cite, on le reformule, puis on ___.', 'mcq', '["L’explique","Le recopie","L’ignore","Le résume en un mot"]'::jsonb, 0, 'Citer et reformuler préparent l’explication, qui est l’essentiel.', 10),
    ('3e376dc7-03d1-5477-9c4c-45ba67809bd8'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'Il faut connaître toute la doctrine de l’auteur pour réussir l’explication.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le texte doit pouvoir se comprendre par lui-même ; la connaissance de l’auteur n’est pas exigée.', 11),
    ('2174ff09-7b49-526e-94f2-d34e47e7c174'::uuid, '8550fd75-4347-51c3-b369-ebea29e54d1a'::uuid, 'À quoi sert d’identifier la question à laquelle répond le texte ?', 'mcq', '["À connaître la date du texte","À trouver le problème et le rattacher aux notions du programme","À deviner la note","À choisir l’option 2"]'::jsonb, 1, 'Un texte est toujours une réponse à un problème : le trouver, c’est commencer à expliquer.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo-techno', 'histoire-geo-techno', 'maths-techno', 'maths-techno', 'philosophie-techno');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo-techno', 'histoire-geo-techno', 'maths-techno', 'maths-techno', 'philosophie-techno')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 388 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 388 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
